-- ===== 20261008152613_chart_of_accounts.sql =====

-- Step 3 of the POS foundation, on ERPNext's model: Financial Structure
-- (.claude/erpnext-docs/POS-System-Only-Features.md 3.1–3.2; docs.frappe.io/erpnext/chart-of-accounts,
-- /cost-center).
--
-- 1. accounts: the Chart of Accounts tree. Group accounts organise it; ledgers are the leaves transactions
--    post to. Every account carries its root's type (Asset, Liability, Equity, Income, Expense), and an
--    Account Type when it has a purpose (Cash, Stock, Tax …) — the type later filters account fields.
-- 2. cost_centers: the tree that tags income and expense lines; one root per system, its company.
-- 3. private.validate_tree(): the rules both trees share.
-- 4. Their doctypes, permissions and policies — restrictable, so a User Permission can hold a user to a
--    branch of either tree.
-- 5. The seed: ERPNext's standard chart, cut to what a POS posts to (current-plan.md, "Seed data"), and the
--    company's cost center with Main under it.
--
-- Names are stored bare: the " - ABBR" suffix ERPNext appends is shown, never stored, so editing the
-- abbreviation renames nothing. Out of scope, so not seeded and not allowed as types: receivable and
-- payable (no Customer or Supplier), fixed assets. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Accounts.

create table if not exists public.accounts (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  account_name text not null,
  account_number text,
  -- Null only for the five roots.
  parent_id uuid,
  is_group boolean not null default false,
  root_type text not null,
  account_type text,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint accounts_id_merchant unique (id, merchant_id),
  constraint accounts_name_unique unique (merchant_id, account_name),
  constraint accounts_number_unique unique (merchant_id, account_number),
  constraint accounts_name_length check (length(btrim(account_name)) between 1 and 140),
  constraint accounts_number_length check (account_number is null or length(btrim(account_number)) between 1 and 20),
  constraint accounts_root_type check (root_type in ('Asset', 'Liability', 'Equity', 'Income', 'Expense')),
  -- ERPNext's account types this app uses, each under the root types it belongs to.
  constraint accounts_type_fits_root check (
    account_type is null or account_type = any (case root_type
      when 'Asset' then array['Bank', 'Cash', 'Chargeable', 'Current Asset', 'Stock', 'Tax', 'Temporary']
      when 'Liability' then array['Chargeable', 'Current Liability', 'Stock Received But Not Billed', 'Tax', 'Temporary']
      when 'Equity' then array['Equity', 'Temporary']
      when 'Income' then array['Direct Income', 'Income Account', 'Indirect Income', 'Temporary']
      when 'Expense' then array[
        'Chargeable', 'Cost of Goods Sold', 'Direct Expense', 'Expense Account', 'Expenses Included In Valuation',
        'Indirect Expense', 'Round Off', 'Stock Adjustment', 'Tax', 'Temporary'
      ]
    end)
  ),
  -- A parent of the same system. NO ACTION, not RESTRICT: deleting a system removes the whole tree in one
  -- statement, which RESTRICT would refuse row by row.
  constraint accounts_parent_fk foreign key (parent_id, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.accounts enable row level security;
create index if not exists accounts_parent_idx on public.accounts (parent_id, merchant_id);


-- 2. Cost Centers.

create table if not exists public.cost_centers (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  cost_center_name text not null,
  cost_center_number text,
  -- Null only for the root: the company.
  parent_id uuid,
  is_group boolean not null default false,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint cost_centers_id_merchant unique (id, merchant_id),
  constraint cost_centers_name_unique unique (merchant_id, cost_center_name),
  constraint cost_centers_number_unique unique (merchant_id, cost_center_number),
  constraint cost_centers_name_length check (length(btrim(cost_center_name)) between 1 and 140),
  constraint cost_centers_number_length check (cost_center_number is null or length(btrim(cost_center_number)) between 1 and 20),
  constraint cost_centers_parent_fk foreign key (parent_id, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.cost_centers enable row level security;
create index if not exists cost_centers_parent_idx on public.cost_centers (parent_id, merchant_id);

-- One root per system.
create unique index if not exists cost_centers_one_root on public.cost_centers (merchant_id) where parent_id is null;


-- 3. The tree rules (docs.frappe.io/erpnext/managing-tree-structure-masters): a parent is a group, a node is
-- never its own ancestor, a group keeps its group-ness while it has children, a root is a group; an account
-- takes its root type from its parent and keeps it while it has children. Security definer, as
-- validate_user_permission is: a User Permission with Hide Descendants hides children from their writer,
-- and the checks must see them anyway. Every read is held to the written row's own system.
create or replace function private.validate_tree()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent_group boolean;
  v_parent_root text;
  v_cycle boolean;
  v_children boolean;
begin
  if tg_op = 'DELETE' then
    -- The cost-center root is the company's; it goes only with the system. Deleting the system cascades
    -- here after its row is gone, so a root whose system still exists is a direct delete. (Not
    -- `current_user`: inside a security definer function it is always the owner.)
    if tg_table_name = 'cost_centers' and old.parent_id is null
      and exists (select 1 from public.merchants m where m.id = old.merchant_id) then
      raise exception 'root_locked' using errcode = '42501', detail = 'The company''s cost center cannot be deleted.';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    execute format('select exists (select 1 from public.%I where parent_id = $1 and merchant_id = $2)', tg_table_name)
      into v_children using new.id, new.merchant_id;
  else
    v_children := false;
  end if;

  if new.parent_id is null then
    if not new.is_group then
      raise exception 'root_must_be_group' using errcode = '23514', detail = 'A root of the tree must be a group.';
    end if;
  else
    if tg_table_name = 'accounts' then
      execute 'select is_group, root_type from public.accounts where id = $1 and merchant_id = $2'
        into v_parent_group, v_parent_root using new.parent_id, new.merchant_id;
    else
      execute 'select is_group from public.cost_centers where id = $1 and merchant_id = $2'
        into v_parent_group using new.parent_id, new.merchant_id;
    end if;

    if not coalesce(v_parent_group, false) then
      raise exception 'parent_not_group' using errcode = '23514', detail = 'A parent must be a group.';
    end if;

    if tg_op = 'UPDATE' then
      execute format(
        'with recursive up (id, parent_id) as (
           select id, parent_id from public.%I where id = $1 and merchant_id = $3
           union
           select t.id, t.parent_id from public.%I t join up on t.id = up.parent_id and t.merchant_id = $3
         )
         select exists (select 1 from up where id = $2)',
        tg_table_name, tg_table_name
      ) into v_cycle using new.parent_id, new.id, new.merchant_id;
      if v_cycle then
        raise exception 'tree_cycle' using errcode = '23514', detail = 'A record cannot sit under itself.';
      end if;
    end if;

    if tg_table_name = 'accounts' then
      new.root_type := v_parent_root;
    end if;
  end if;

  if tg_op = 'UPDATE' and v_children then
    if old.is_group and not new.is_group then
      raise exception 'group_has_children' using errcode = '23514', detail = 'A group with records under it cannot become a ledger.';
    end if;
    if tg_table_name = 'accounts' and new.root_type is distinct from old.root_type then
      raise exception 'root_type_locked' using errcode = '23514', detail = 'An account with accounts under it cannot move to another root type.';
    end if;
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_tree() from public, anon, authenticated, service_role;

drop trigger if exists accounts_validate_tree on public.accounts;
create trigger accounts_validate_tree
  before insert or update or delete on public.accounts
  for each row execute function private.validate_tree();

drop trigger if exists cost_centers_validate_tree on public.cost_centers;
create trigger cost_centers_validate_tree
  before insert or update or delete on public.cost_centers
  for each row execute function private.validate_tree();


-- 4. Doctypes, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('Account', 'accounts', 'tree', true),
  ('Cost Center', 'cost_centers', 'tree', true)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Accounts Manager', 'Account', true, true, true, true, true),
  ('Accounts User', 'Account', true, true, false, false, false),
  ('All', 'Account', true, false, false, false, false),
  ('Accounts Manager', 'Cost Center', true, true, true, true, true),
  ('Accounts User', 'Cost Center', true, true, false, false, false),
  ('All', 'Cost Center', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('accounts', 'Account');
select private.apply_doctype_policies('cost_centers', 'Cost Center');


-- 5. Seeding.

-- One account, found or made, for a re-runnable seed. Returns its id.
create or replace function private.seed_account(
  p_merchant uuid, p_name text, p_parent uuid, p_is_group boolean, p_root_type text, p_account_type text
)
returns uuid
language plpgsql
set search_path = ''
as $$
declare
  v_id uuid;
begin
  insert into public.accounts (merchant_id, account_name, parent_id, is_group, root_type, account_type)
  values (p_merchant, p_name, p_parent, p_is_group, p_root_type, p_account_type)
  on conflict (merchant_id, account_name) do nothing
  returning id into v_id;

  if v_id is null then
    select a.id into v_id from public.accounts a where a.merchant_id = p_merchant and a.account_name = p_name;
  end if;
  return v_id;
end;
$$;

revoke execute on function private.seed_account(uuid, text, uuid, boolean, text, text) from public, anon, authenticated, service_role;

-- ERPNext's Standard chart, the part a POS posts to: Cash, Stock In Hand, Sales, Cost of Goods Sold, the tax
-- group, Write Off, Round Off, and the stock clearing accounts perpetual inventory needs.
create or replace function private.seed_chart_for(p_merchant uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_root uuid;
  v_group uuid;
  v_sub uuid;
  v_cc uuid;
begin
  v_root := private.seed_account(p_merchant, 'Application of Funds (Assets)', null, true, 'Asset', null);
  v_group := private.seed_account(p_merchant, 'Current Assets', v_root, true, 'Asset', null);
  perform private.seed_account(p_merchant, 'Bank Accounts', v_group, true, 'Asset', 'Bank');
  v_sub := private.seed_account(p_merchant, 'Cash In Hand', v_group, true, 'Asset', 'Cash');
  perform private.seed_account(p_merchant, 'Cash', v_sub, false, 'Asset', 'Cash');
  v_sub := private.seed_account(p_merchant, 'Stock Assets', v_group, true, 'Asset', 'Stock');
  perform private.seed_account(p_merchant, 'Stock In Hand', v_sub, false, 'Asset', 'Stock');
  perform private.seed_account(p_merchant, 'Tax Assets', v_group, true, 'Asset', null);
  v_group := private.seed_account(p_merchant, 'Temporary Accounts', v_root, true, 'Asset', null);
  perform private.seed_account(p_merchant, 'Temporary Opening', v_group, false, 'Asset', 'Temporary');

  v_root := private.seed_account(p_merchant, 'Source of Funds (Liabilities)', null, true, 'Liability', null);
  v_group := private.seed_account(p_merchant, 'Current Liabilities', v_root, true, 'Liability', null);
  perform private.seed_account(p_merchant, 'Duties and Taxes', v_group, true, 'Liability', 'Tax');
  v_sub := private.seed_account(p_merchant, 'Stock Liabilities', v_group, true, 'Liability', null);
  perform private.seed_account(p_merchant, 'Stock Received But Not Billed', v_sub, false, 'Liability', 'Stock Received But Not Billed');

  v_root := private.seed_account(p_merchant, 'Equity', null, true, 'Equity', null);
  perform private.seed_account(p_merchant, 'Capital Stock', v_root, false, 'Equity', 'Equity');
  perform private.seed_account(p_merchant, 'Opening Balance Equity', v_root, false, 'Equity', 'Equity');
  perform private.seed_account(p_merchant, 'Retained Earnings', v_root, false, 'Equity', 'Equity');

  v_root := private.seed_account(p_merchant, 'Income', null, true, 'Income', null);
  v_group := private.seed_account(p_merchant, 'Direct Income', v_root, true, 'Income', null);
  perform private.seed_account(p_merchant, 'Sales', v_group, false, 'Income', 'Income Account');
  perform private.seed_account(p_merchant, 'Indirect Income', v_root, true, 'Income', null);

  v_root := private.seed_account(p_merchant, 'Expenses', null, true, 'Expense', null);
  v_group := private.seed_account(p_merchant, 'Direct Expenses', v_root, true, 'Expense', null);
  v_sub := private.seed_account(p_merchant, 'Stock Expenses', v_group, true, 'Expense', null);
  perform private.seed_account(p_merchant, 'Cost of Goods Sold', v_sub, false, 'Expense', 'Cost of Goods Sold');
  perform private.seed_account(p_merchant, 'Expenses Included In Valuation', v_sub, false, 'Expense', 'Expenses Included In Valuation');
  perform private.seed_account(p_merchant, 'Stock Adjustment', v_sub, false, 'Expense', 'Stock Adjustment');
  v_group := private.seed_account(p_merchant, 'Indirect Expenses', v_root, true, 'Expense', null);
  perform private.seed_account(p_merchant, 'Write Off', v_group, false, 'Expense', null);
  perform private.seed_account(p_merchant, 'Round Off', v_group, false, 'Expense', 'Round Off');

  -- The company's cost center, named as the company is, with Main under it.
  insert into public.cost_centers (merchant_id, cost_center_name, is_group)
  select m.id, m.name, true from public.merchants m where m.id = p_merchant
  on conflict do nothing;
  select c.id into v_cc from public.cost_centers c where c.merchant_id = p_merchant and c.parent_id is null;
  insert into public.cost_centers (merchant_id, cost_center_name, parent_id, is_group)
  values (p_merchant, 'Main', v_cc, false)
  on conflict do nothing;
end;
$$;

revoke execute on function private.seed_chart_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_accounting()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_chart_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_accounting() from public, anon, authenticated, service_role;

drop trigger if exists merchants_seed_40_accounting on public.merchants;
create trigger merchants_seed_40_accounting
  after insert on public.merchants
  for each row execute function private.seed_accounting();

-- The systems that already exist.
select private.seed_chart_for(m.id) from public.merchants m;


-- ===== 20261008224129_tree_and_profile_fixes.sql =====

-- Two fixes found on the 2026-10-09 device run (.claude/tests/test-report/).
--
-- 1. private.validate_tree() raised 42703 on every edit of a cost-center group with children: its
--    root_type check read new.root_type on a table that has no such column. Same function, with that
--    check nested under the accounts branch. Everything else in it is unchanged
--    (20261008152613_chart_of_accounts.sql).
--
-- 2. Accounts that signed up before the signup trigger existed (20260902000002_profiles.sql) have no
--    public.profiles row, so my_permissions and the Users page show them without a name. Backfilled
--    the way private.handle_new_user() fills a new one.

create or replace function private.validate_tree()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent_group boolean;
  v_parent_root text;
  v_cycle boolean;
  v_children boolean;
begin
  if tg_op = 'DELETE' then
    -- The cost-center root is the company's; it goes only with the system. Deleting the system cascades
    -- here after its row is gone, so a root whose system still exists is a direct delete. (Not
    -- `current_user`: inside a security definer function it is always the owner.)
    if tg_table_name = 'cost_centers' and old.parent_id is null
      and exists (select 1 from public.merchants m where m.id = old.merchant_id) then
      raise exception 'root_locked' using errcode = '42501', detail = 'The company''s cost center cannot be deleted.';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    execute format('select exists (select 1 from public.%I where parent_id = $1 and merchant_id = $2)', tg_table_name)
      into v_children using new.id, new.merchant_id;
  else
    v_children := false;
  end if;

  if new.parent_id is null then
    if not new.is_group then
      raise exception 'root_must_be_group' using errcode = '23514', detail = 'A root of the tree must be a group.';
    end if;
  else
    if tg_table_name = 'accounts' then
      execute 'select is_group, root_type from public.accounts where id = $1 and merchant_id = $2'
        into v_parent_group, v_parent_root using new.parent_id, new.merchant_id;
    else
      execute 'select is_group from public.cost_centers where id = $1 and merchant_id = $2'
        into v_parent_group using new.parent_id, new.merchant_id;
    end if;

    if not coalesce(v_parent_group, false) then
      raise exception 'parent_not_group' using errcode = '23514', detail = 'A parent must be a group.';
    end if;

    if tg_op = 'UPDATE' then
      execute format(
        'with recursive up (id, parent_id) as (
           select id, parent_id from public.%I where id = $1 and merchant_id = $3
           union
           select t.id, t.parent_id from public.%I t join up on t.id = up.parent_id and t.merchant_id = $3
         )
         select exists (select 1 from up where id = $2)',
        tg_table_name, tg_table_name
      ) into v_cycle using new.parent_id, new.id, new.merchant_id;
      if v_cycle then
        raise exception 'tree_cycle' using errcode = '23514', detail = 'A record cannot sit under itself.';
      end if;
    end if;

    if tg_table_name = 'accounts' then
      new.root_type := v_parent_root;
    end if;
  end if;

  if tg_op = 'UPDATE' and v_children then
    if old.is_group and not new.is_group then
      raise exception 'group_has_children' using errcode = '23514', detail = 'A group with records under it cannot become a ledger.';
    end if;
    -- Nested, not `and`-ed: plpgsql may evaluate both sides, and a cost_centers row has no root_type
    -- (42703 "record new has no field root_type" on every edit of a group with children).
    if tg_table_name = 'accounts' then
      if new.root_type is distinct from old.root_type then
        raise exception 'root_type_locked' using errcode = '23514', detail = 'An account with accounts under it cannot move to another root type.';
      end if;
    end if;
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_tree() from public, anon, authenticated, service_role;

insert into public.profiles (id, display_name, avatar_url)
select
  u.id,
  nullif(u.raw_user_meta_data ->> 'full_name', ''),
  nullif(u.raw_user_meta_data ->> 'avatar_url', '')
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id)
on conflict (id) do nothing;


-- ===== 20261009004357_accounting_defaults.sql =====

-- Step 4 of the POS foundation, on ERPNext's model: Accounting Defaults & Inventory Accounting
-- (.claude/erpnext-docs/POS-System-Only-Features.md 4.1–4.4; docs.frappe.io/erpnext/company-accounting-defaults,
-- /perpetual-inventory, /accounting-of-inventory-stock, /accounts-settings).
--
-- 1. The Company's accounting defaults, as merchants columns (a system IS its company,
--    .claude/instruction-mds/tenancy.md rule 10): the fallback Cash, Bank, Income and Expense accounts, Cost
--    Center, Write Off and Round Off — used when an item, warehouse, mode of payment or row gives none.
-- 2. Perpetual Inventory, also on the Company: on by default, with the four accounts every stock movement
--    posts to. ERPNext only warns when it is on without a Default Inventory Account, and so does this app.
-- 3. private.validate_company_accounts(): each default is an enabled ledger of the kind its field takes —
--    ERPNext's own filters on the Company form.
-- 4. accounts_settings: a single per system — invoice cancellation, Immutable Ledger, discount accounting, item
--    tax templates, and the frozen-accounts date with the role allowed past it.
-- 5. The doctype, its permissions and policies, and the seed that fills a system's defaults from its chart.
--
-- Out of scope, so absent: receivable and payable (no Customer or Supplier), exchange gain/loss (one
-- currency), fixed-asset, deferred-accounting and budget defaults. Re-runnable, like the rest of
-- supabase/migrations.

create schema if not exists private;


-- 1–2. The Company's defaults. Each account column is held to an account of the same system by a composite
-- foreign key. NO ACTION, not RESTRICT: deleting a system removes its accounts and its row in one statement,
-- and NO ACTION checks only at the statement's end, after the row naming them is gone. Deleting an account a
-- default still names fails with 23503 — the Chart of Accounts says "in use".

alter table public.merchants
  add column if not exists default_cash_account uuid,
  add column if not exists default_bank_account uuid,
  add column if not exists default_income_account uuid,
  add column if not exists default_expense_account uuid,
  add column if not exists cost_center uuid,
  add column if not exists write_off_account uuid,
  add column if not exists round_off_account uuid,
  add column if not exists round_off_cost_center uuid,
  add column if not exists enable_perpetual_inventory boolean not null default true,
  add column if not exists default_inventory_account uuid,
  add column if not exists stock_adjustment_account uuid,
  add column if not exists stock_received_but_not_billed uuid,
  add column if not exists expenses_included_in_valuation uuid;

do $$
declare
  v_col text;
begin
  foreach v_col in array array[
    'default_cash_account', 'default_bank_account', 'default_income_account', 'default_expense_account',
    'write_off_account', 'round_off_account', 'default_inventory_account', 'stock_adjustment_account',
    'stock_received_but_not_billed', 'expenses_included_in_valuation'
  ] loop
    if not exists (select 1 from pg_catalog.pg_constraint where conname = 'merchants_' || v_col || '_fk') then
      execute format(
        'alter table public.merchants add constraint %I foreign key (%I, id) references public.accounts (id, merchant_id)',
        'merchants_' || v_col || '_fk', v_col
      );
    end if;
  end loop;

  foreach v_col in array array['cost_center', 'round_off_cost_center'] loop
    if not exists (select 1 from pg_catalog.pg_constraint where conname = 'merchants_' || v_col || '_fk') then
      execute format(
        'alter table public.merchants add constraint %I foreign key (%I, id) references public.cost_centers (id, merchant_id)',
        'merchants_' || v_col || '_fk', v_col
      );
    end if;
  end loop;
end;
$$;


-- 3. What each default may name: an enabled ledger, of the type (or root type) ERPNext's Company form filters
-- that field to. Security definer, as private.validate_tree is: a User Permission holding the writer to one
-- branch must not hide the account from the check. Only a changed column is checked, so renaming the company
-- never fails over an account disabled since it was picked.
create or replace function private.validate_company_accounts()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rule record;
  v_new uuid;
  v_old uuid;
  v_ok boolean;
begin
  for v_rule in
    select * from (values
      ('default_cash_account', 'type', 'Cash'),
      ('default_bank_account', 'type', 'Bank'),
      ('default_income_account', 'root', 'Income'),
      ('default_expense_account', 'root', 'Expense'),
      ('write_off_account', 'root', 'Expense'),
      ('round_off_account', 'root', 'Expense'),
      ('default_inventory_account', 'type', 'Stock'),
      ('stock_adjustment_account', 'type', 'Stock Adjustment'),
      ('stock_received_but_not_billed', 'type', 'Stock Received But Not Billed'),
      ('expenses_included_in_valuation', 'type', 'Expenses Included In Valuation'),
      ('cost_center', 'cost_center', null),
      ('round_off_cost_center', 'cost_center', null)
    ) as r (col, kind, want)
  loop
    execute format('select ($1).%I, ($2).%I', v_rule.col, v_rule.col) into v_new, v_old using new, old;
    continue when v_new is null or (tg_op = 'UPDATE' and v_new is not distinct from v_old);

    if v_rule.kind = 'cost_center' then
      select not c.is_group and not c.disabled into v_ok
      from public.cost_centers c where c.id = v_new and c.merchant_id = new.id;
    else
      select not a.is_group and not a.disabled
        and (case v_rule.kind when 'type' then a.account_type = v_rule.want else a.root_type = v_rule.want end)
      into v_ok
      from public.accounts a where a.id = v_new and a.merchant_id = new.id;
    end if;

    if not coalesce(v_ok, false) then
      raise exception 'company_account_invalid' using errcode = '23514',
        detail = format('%s cannot name that record.', v_rule.col);
    end if;
  end loop;

  return new;
end;
$$;

revoke execute on function private.validate_company_accounts() from public, anon, authenticated, service_role;

drop trigger if exists merchants_validate_accounts on public.merchants;
create trigger merchants_validate_accounts
  before insert or update of
    default_cash_account, default_bank_account, default_income_account, default_expense_account, cost_center,
    write_off_account, round_off_account, round_off_cost_center, default_inventory_account,
    stock_adjustment_account, stock_received_but_not_billed, expenses_included_in_valuation
  on public.merchants
  for each row execute function private.validate_company_accounts();


-- 4. Accounts Settings.

create table if not exists public.accounts_settings (
  merchant_id uuid primary key references public.merchants (id) on delete cascade,
  -- Cancelling an invoice turns the payments made against it into unallocated amounts.
  unlink_payment_on_cancellation boolean not null default true,
  -- Deleting a cancelled document also removes its ledger rows. Off: the audit trail stays.
  delete_linked_ledger_entries boolean not null default false,
  -- Cancelling posts reversal rows instead of rewriting history — the docs' "safer choice".
  enable_immutable_ledger boolean not null default true,
  -- Discounts post to a discount account rather than reducing revenue.
  enable_discount_accounting boolean not null default false,
  -- A missing tax row is added from an item's Item Tax Template.
  add_taxes_from_item_tax_template boolean not null default true,
  -- No accounting entry on or before this date, except by the role below.
  accounts_frozen_till_date date,
  frozen_accounts_modifier uuid,

  -- A role of the same system. Deleting that role clears the field rather than refusing the delete.
  constraint accounts_settings_modifier_fk foreign key (frozen_accounts_modifier, merchant_id)
    references public.roles (id, merchant_id) on delete set null (frozen_accounts_modifier)
);

alter table public.accounts_settings enable row level security;
create index if not exists accounts_settings_modifier_idx on public.accounts_settings (frozen_accounts_modifier, merchant_id);


-- 5. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Accounts Settings', 'accounts_settings', 'single', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('System Manager', 'Accounts Settings', true, true, true, false, false),
  ('Accounts Manager', 'Accounts Settings', true, true, true, false, false),
  ('Accounts User', 'Accounts Settings', true, true, false, false, false),
  -- Select only, ERPNext's permission for a link field: whoever edits Accounts Settings can pick the frozen-
  -- accounts role without being able to open Roles.
  ('All', 'Role', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('accounts_settings', 'Accounts Settings');


-- 6. Seeding: a system's defaults from the chart merchants_seed_40_accounting made, found by name and kind so
-- a renamed or retyped account is left alone. Only empty defaults are filled. No Bank default: the standard
-- chart has no bank ledger until the owner adds one.

create or replace function private.seed_accounting_defaults_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  update public.merchants m set
    default_cash_account = coalesce(m.default_cash_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Cash' and a.account_type = 'Cash' and not a.is_group)),
    default_income_account = coalesce(m.default_income_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Sales' and a.root_type = 'Income' and not a.is_group)),
    default_expense_account = coalesce(m.default_expense_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Cost of Goods Sold' and a.root_type = 'Expense' and not a.is_group)),
    write_off_account = coalesce(m.write_off_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Write Off' and a.root_type = 'Expense' and not a.is_group)),
    round_off_account = coalesce(m.round_off_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Round Off' and a.root_type = 'Expense' and not a.is_group)),
    default_inventory_account = coalesce(m.default_inventory_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Stock In Hand' and a.account_type = 'Stock' and not a.is_group)),
    stock_adjustment_account = coalesce(m.stock_adjustment_account,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Stock Adjustment' and a.account_type = 'Stock Adjustment' and not a.is_group)),
    stock_received_but_not_billed = coalesce(m.stock_received_but_not_billed,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Stock Received But Not Billed' and a.account_type = 'Stock Received But Not Billed' and not a.is_group)),
    expenses_included_in_valuation = coalesce(m.expenses_included_in_valuation,
      (select a.id from public.accounts a where a.merchant_id = m.id and a.account_name = 'Expenses Included In Valuation' and a.account_type = 'Expenses Included In Valuation' and not a.is_group)),
    cost_center = coalesce(m.cost_center,
      (select c.id from public.cost_centers c where c.merchant_id = m.id and c.cost_center_name = 'Main' and not c.is_group)),
    round_off_cost_center = coalesce(m.round_off_cost_center,
      (select c.id from public.cost_centers c where c.merchant_id = m.id and c.cost_center_name = 'Main' and not c.is_group))
  where m.id = p_merchant;

  insert into public.accounts_settings (merchant_id) values (p_merchant) on conflict (merchant_id) do nothing;
$$;

revoke execute on function private.seed_accounting_defaults_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_accounting_defaults()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_accounting_defaults_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_accounting_defaults() from public, anon, authenticated, service_role;

-- After merchants_seed_40_accounting, by name: the chart exists when this runs.
drop trigger if exists merchants_seed_50_accounting_defaults on public.merchants;
create trigger merchants_seed_50_accounting_defaults
  after insert on public.merchants
  for each row execute function private.seed_accounting_defaults();

-- The systems that already exist.
select private.seed_accounting_defaults_for(m.id) from public.merchants m;


-- ===== 20261009004450_modes_of_payment.sql =====

-- Step 5 of the POS foundation, on ERPNext's model: Retail Payments
-- (.claude/erpnext-docs/POS-System-Only-Features.md 5.1–5.2; docs.frappe.io/erpnext/mode-of-payment,
-- /bank-accounts-and-modes-of-payment).
--
-- 1. modes_of_payment: how money is received — Cash, Credit Card … — with its Type and the ledger ERPNext
--    proposes when it is chosen. ERPNext keeps that ledger in a per-company child table; a system is one
--    company, so it is a column.
-- 2. private.validate_mode_of_payment_account(): the ledger is an enabled Cash or Bank ledger that fits the
--    Type — the docs' warning that "the label Cash does not make the linked ledger a cash account".
-- 3. The doctype, its permissions and policies, and the seed: Cash on the Cash ledger, Credit Card with no
--    account until the owner adds a bank or clearing ledger.
--
-- 5.1 (Bank vs Bank Account vs ledger vs Mode of Payment) is the form's help text: no Bank or Bank Account
-- doctypes — bank reconciliation is out of scope. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Modes of Payment.

create table if not exists public.modes_of_payment (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  mode_of_payment text not null,
  type text not null default 'General',
  enabled boolean not null default true,
  default_account uuid,
  created_at timestamptz not null default now(),

  constraint modes_of_payment_id_merchant unique (id, merchant_id),
  constraint modes_of_payment_name_unique unique (merchant_id, mode_of_payment),
  constraint modes_of_payment_name_length check (length(btrim(mode_of_payment)) between 1 and 140),
  constraint modes_of_payment_type check (type in ('Cash', 'Bank', 'General', 'Phone')),
  -- An account of the same system. Deleting a ledger a mode still names fails with 23503 ("in use").
  constraint modes_of_payment_account_fk foreign key (default_account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.modes_of_payment enable row level security;
create index if not exists modes_of_payment_account_idx on public.modes_of_payment (default_account, merchant_id);


-- 2. The ledger fits the Type: Cash → a Cash ledger, Bank → a Bank ledger, General and Phone → either.
-- Security definer, as private.validate_company_accounts is: a User Permission must not hide the account from
-- the check.
create or replace function private.validate_mode_of_payment_account()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ok boolean;
begin
  if new.default_account is null then
    return new;
  end if;

  select not a.is_group and not a.disabled
    and a.account_type = any (case new.type when 'Cash' then array['Cash'] when 'Bank' then array['Bank'] else array['Cash', 'Bank'] end)
  into v_ok
  from public.accounts a where a.id = new.default_account and a.merchant_id = new.merchant_id;

  if not coalesce(v_ok, false) then
    raise exception 'mode_account_invalid' using errcode = '23514',
      detail = 'A mode of payment''s account is an enabled Cash or Bank ledger that fits its type.';
  end if;
  return new;
end;
$$;

revoke execute on function private.validate_mode_of_payment_account() from public, anon, authenticated, service_role;

drop trigger if exists modes_of_payment_validate_account on public.modes_of_payment;
create trigger modes_of_payment_validate_account
  before insert or update of type, default_account on public.modes_of_payment
  for each row execute function private.validate_mode_of_payment_account();


-- 3. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Mode of Payment', 'modes_of_payment', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Accounts Manager', 'Mode of Payment', true, true, true, true, true),
  ('Accounts User', 'Mode of Payment', true, true, false, false, false),
  ('Sales User', 'Mode of Payment', true, true, false, false, false),
  ('All', 'Mode of Payment', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('modes_of_payment', 'Mode of Payment');


-- 4. Seeding: Cash on the Cash ledger (found by name and type, so a renamed one is left out), and Credit Card.

create or replace function private.seed_payments_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.modes_of_payment (merchant_id, mode_of_payment, type, default_account)
  values
    (p_merchant, 'Cash', 'Cash',
      (select a.id from public.accounts a
       where a.merchant_id = p_merchant and a.account_name = 'Cash' and a.account_type = 'Cash' and not a.is_group and not a.disabled)),
    (p_merchant, 'Credit Card', 'Bank', null)
  on conflict (merchant_id, mode_of_payment) do nothing;
$$;

revoke execute on function private.seed_payments_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_payments()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_payments_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_payments() from public, anon, authenticated, service_role;

-- After merchants_seed_40_accounting, by name: the Cash ledger exists when this runs.
drop trigger if exists merchants_seed_60_payments on public.merchants;
create trigger merchants_seed_60_payments
  after insert on public.merchants
  for each row execute function private.seed_payments();

-- The systems that already exist.
select private.seed_payments_for(m.id) from public.merchants m;


-- ===== 20261009091028_taxes.sql =====

-- Step 6 of the POS foundation, on ERPNext's model: Sales Tax Setup
-- (.claude/erpnext-docs/POS-System-Only-Features.md 6.1–6.5; docs.frappe.io/erpnext/setting-up-taxes,
-- /tax-category, /sales-taxes-and-charges-template, /item-tax-template, /types-in-tax-template,
-- /tax-inclusive-accounting).
--
-- 1. tax_categories: a named tax treatment (Standard, Exempt …). No rate of its own.
-- 2. sales_tax_templates + sales_tax_template_rows: the reusable tax and charge rows a POS Profile applies —
--    each row a calculation type, a ledger, a rate (or a fixed amount), optionally on an earlier row, and
--    optionally already included in the shelf price.
-- 3. item_tax_templates + item_tax_template_rows: a different rate, or Not Applicable, for particular items,
--    per tax account. Linked on an Item or Item Group later (Step 9).
-- 4. The checks ERPNext runs on save (accounts_controller.validate_taxes_and_charges, validate_inclusive_tax,
--    valdiate_taxes_and_charges_template, item_tax_template.validate_tax_accounts), held by the database.
-- 5. save_sales_tax_template / save_item_tax_template: a template and its rows in one transaction.
-- 6. Doctypes, permissions, policies.
-- 7. tax_presets and the seed: what ERPNext's setup wizard creates for the company's country
--    (setup_wizard/data/country_wise_tax.json, taxes_setup.simple_to_detailed) — a tax ledger under
--    Duties and Taxes, a Sales Taxes and Charges Template and an Item Tax Template per preset.
--
-- Out of scope, so absent: purchase tax templates (no Supplier), Tax Withholding (separate workflow),
-- Considered In Paid Amount, regional fields. The Tax Rule that picks a template is Step 7.
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Tax Categories.

create table if not exists public.tax_categories (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  title text not null,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint tax_categories_id_merchant unique (id, merchant_id),
  constraint tax_categories_title_unique unique (merchant_id, title),
  constraint tax_categories_title_length check (length(btrim(title)) between 1 and 140)
);

alter table public.tax_categories enable row level security;


-- 2. Sales Taxes and Charges Templates.

create table if not exists public.sales_tax_templates (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  title text not null,
  is_default boolean not null default false,
  disabled boolean not null default false,
  tax_category_id uuid,
  created_at timestamptz not null default now(),

  constraint sales_tax_templates_id_merchant unique (id, merchant_id),
  constraint sales_tax_templates_title_unique unique (merchant_id, title),
  constraint sales_tax_templates_title_length check (length(btrim(title)) between 1 and 140),
  -- "Disabled template must not be default template."
  constraint sales_tax_templates_default_enabled check (not (is_default and disabled)),
  -- A category of the same system. Deleting one a template still names fails with 23503 ("in use").
  constraint sales_tax_templates_category_fk foreign key (tax_category_id, merchant_id) references public.tax_categories (id, merchant_id)
);

alter table public.sales_tax_templates enable row level security;
create index if not exists sales_tax_templates_category_idx on public.sales_tax_templates (tax_category_id, merchant_id);

-- One default per system.
create unique index if not exists sales_tax_templates_one_default on public.sales_tax_templates (merchant_id) where is_default;

-- "Only one template is allowed with each tax category" — among the enabled ones.
create unique index if not exists sales_tax_templates_one_per_category
  on public.sales_tax_templates (merchant_id, tax_category_id) where tax_category_id is not null and not disabled;

-- Making a template the default clears the old one in the same statement, as ERPNext does on save.
-- Invoker, like private.fiscal_years_single_default: RLS decides whether the caller may touch the other row.
create or replace function private.sales_tax_templates_single_default()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.is_default then
    update public.sales_tax_templates
    set is_default = false
    where merchant_id = new.merchant_id and id <> new.id and is_default;
  end if;
  return new;
end;
$$;

revoke execute on function private.sales_tax_templates_single_default() from public, anon, authenticated, service_role;

drop trigger if exists sales_tax_templates_single_default on public.sales_tax_templates;
create trigger sales_tax_templates_single_default
  before insert or update of is_default on public.sales_tax_templates
  for each row execute function private.sales_tax_templates_single_default();

-- The rows, in calculation order. Amounts are computed on a transaction, never stored on the template.
create table if not exists public.sales_tax_template_rows (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  template_id uuid not null,
  idx integer not null,
  charge_type text not null,
  account uuid not null,
  description text not null,
  -- A percentage, or for On Item Quantity an amount per unit.
  rate numeric not null default 0,
  -- The fixed amount of an Actual row.
  tax_amount numeric not null default 0,
  -- Reference Row #: the earlier row a previous-row type is calculated on.
  row_id integer,
  -- "Is this Tax included in Basic Rate?"
  included_in_print_rate boolean not null default false,
  cost_center uuid,

  constraint sales_tax_template_rows_idx unique (template_id, idx),
  constraint sales_tax_template_rows_idx_positive check (idx >= 1),
  constraint sales_tax_template_rows_charge_type check (
    charge_type in ('Actual', 'On Net Total', 'On Previous Row Amount', 'On Previous Row Total', 'On Item Quantity')
  ),
  constraint sales_tax_template_rows_description_length check (length(btrim(description)) between 1 and 140),
  -- "Can refer row only if the charge type is 'On Previous Row Amount' or 'Previous Row Total'", and then
  -- only an earlier row — which also refuses a previous-row type on row 1.
  constraint sales_tax_template_rows_reference check (
    case when charge_type in ('On Previous Row Amount', 'On Previous Row Total')
      then row_id is not null and row_id between 1 and idx - 1
      else row_id is null
    end
  ),
  -- "Charge of type 'Actual' cannot be included in Item Rate."
  constraint sales_tax_template_rows_inclusive_actual check (not (included_in_print_rate and charge_type = 'Actual')),
  constraint sales_tax_template_rows_template_fk foreign key (template_id, merchant_id) references public.sales_tax_templates (id, merchant_id) on delete cascade,
  -- NO ACTION: deleting a system removes its accounts and rows in one statement; deleting an account a row
  -- names fails with 23503 ("in use").
  constraint sales_tax_template_rows_account_fk foreign key (account, merchant_id) references public.accounts (id, merchant_id),
  constraint sales_tax_template_rows_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.sales_tax_template_rows enable row level security;
create index if not exists sales_tax_template_rows_template_idx on public.sales_tax_template_rows (template_id, merchant_id);
create index if not exists sales_tax_template_rows_account_idx on public.sales_tax_template_rows (account, merchant_id);
create index if not exists sales_tax_template_rows_cost_center_idx on public.sales_tax_template_rows (cost_center, merchant_id);


-- 3. Item Tax Templates.

create table if not exists public.item_tax_templates (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  title text not null,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint item_tax_templates_id_merchant unique (id, merchant_id),
  constraint item_tax_templates_title_unique unique (merchant_id, title),
  constraint item_tax_templates_title_length check (length(btrim(title)) between 1 and 140)
);

alter table public.item_tax_templates enable row level security;

create table if not exists public.item_tax_template_rows (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  template_id uuid not null,
  idx integer not null,
  -- ERPNext's "Tax" column: the tax account whose rate this overrides.
  account uuid not null,
  tax_rate numeric not null default 0,
  -- The tax does not apply to the item at all — not the same as 0% for reporting.
  not_applicable boolean not null default false,

  -- "{account} entered twice in Item Tax."
  constraint item_tax_template_rows_account_unique unique (template_id, account),
  constraint item_tax_template_rows_template_fk foreign key (template_id, merchant_id) references public.item_tax_templates (id, merchant_id) on delete cascade,
  constraint item_tax_template_rows_account_fk foreign key (account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.item_tax_template_rows enable row level security;
create index if not exists item_tax_template_rows_template_idx on public.item_tax_template_rows (template_id, merchant_id);
create index if not exists item_tax_template_rows_account_idx on public.item_tax_template_rows (account, merchant_id);


-- 4. The checks.

-- A tax row's account is an enabled ledger of the types ERPNext's tax tables offer; a sales row's cost
-- center an enabled ledger. Security definer, as private.validate_mode_of_payment_account is: a User
-- Permission must not hide the account from the check.
create or replace function private.validate_tax_account()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ok boolean;
begin
  select not a.is_group and not a.disabled
    and a.account_type = any (array['Tax', 'Chargeable', 'Income Account', 'Expense Account', 'Expenses Included In Valuation'])
  into v_ok
  from public.accounts a where a.id = new.account and a.merchant_id = new.merchant_id;

  if not coalesce(v_ok, false) then
    raise exception 'tax_account_invalid' using errcode = '23514',
      detail = 'A tax row''s account is an enabled ledger of type Tax, Chargeable, Income Account, Expense Account or Expenses Included In Valuation.';
  end if;

  -- Nested, not and-ed: item_tax_template_rows has no cost_center (the 42703 trap,
  -- 20261008224129_tree_and_profile_fixes.sql).
  if tg_table_name = 'sales_tax_template_rows' then
    if new.cost_center is not null then
      select not c.is_group and not c.disabled into v_ok
      from public.cost_centers c where c.id = new.cost_center and c.merchant_id = new.merchant_id;

      if not coalesce(v_ok, false) then
        raise exception 'tax_cost_center_invalid' using errcode = '23514', detail = 'A tax row''s cost center is an enabled ledger.';
      end if;
    end if;
  end if;
  return new;
end;
$$;

revoke execute on function private.validate_tax_account() from public, anon, authenticated, service_role;

drop trigger if exists sales_tax_template_rows_validate_account on public.sales_tax_template_rows;
create trigger sales_tax_template_rows_validate_account
  before insert or update of account, cost_center on public.sales_tax_template_rows
  for each row execute function private.validate_tax_account();

drop trigger if exists item_tax_template_rows_validate_account on public.item_tax_template_rows;
create trigger item_tax_template_rows_validate_account
  before insert or update of account on public.item_tax_template_rows
  for each row execute function private.validate_tax_account();

-- The rules that read other rows of the template (ERPNext validate_inclusive_tax): a Reference Row # names a
-- row that exists; an inclusive tax calculated on an earlier row needs that row inclusive (On Previous Row
-- Amount) or every row up to it inclusive (On Previous Row Total). A deferred constraint trigger, so a save
-- that replaces all rows is checked once they are all in place, at commit. Checks the whole template, so a
-- change to the referenced row is caught too.
create or replace function private.validate_tax_row_references()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_template uuid := coalesce(new.template_id, old.template_id);
begin
  if exists (
    select 1 from public.sales_tax_template_rows r
    where r.template_id = v_template and r.row_id is not null
      and not exists (select 1 from public.sales_tax_template_rows p where p.template_id = r.template_id and p.idx = r.row_id)
  ) then
    raise exception 'tax_row_reference_missing' using errcode = '23514', detail = 'A Reference Row # names a row of the same template.';
  end if;

  if exists (
    select 1 from public.sales_tax_template_rows r
    where r.template_id = v_template and r.included_in_print_rate and (
      (r.charge_type = 'On Previous Row Amount' and exists (
        select 1 from public.sales_tax_template_rows p
        where p.template_id = r.template_id and p.idx = r.row_id and not p.included_in_print_rate
      ))
      or (r.charge_type = 'On Previous Row Total' and exists (
        select 1 from public.sales_tax_template_rows p
        where p.template_id = r.template_id and p.idx <= r.row_id and not p.included_in_print_rate
      ))
    )
  ) then
    raise exception 'tax_inclusive_reference' using errcode = '23514',
      detail = 'To include a tax in the rate, the rows it is calculated on must be included too.';
  end if;
  return null;
end;
$$;

revoke execute on function private.validate_tax_row_references() from public, anon, authenticated, service_role;

drop trigger if exists sales_tax_template_rows_validate_references on public.sales_tax_template_rows;
create constraint trigger sales_tax_template_rows_validate_references
  after insert or update or delete on public.sales_tax_template_rows
  deferrable initially deferred
  for each row execute function private.validate_tax_row_references();


-- 5. Saving a template with its rows. Security invoker, like public.save_role_profile: the caller's own
-- policies decide every row. The rows are replaced as a set; idx is their order in the payload.

create or replace function public.save_sales_tax_template(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  if v_id is null then
    insert into public.sales_tax_templates (merchant_id, title, is_default, disabled, tax_category_id)
    values (
      v_merchant,
      btrim(payload ->> 'title'),
      coalesce((payload ->> 'is_default')::boolean, false),
      coalesce((payload ->> 'disabled')::boolean, false),
      nullif(payload ->> 'tax_category_id', '')::uuid
    )
    returning id into v_id;
  else
    update public.sales_tax_templates set
      title = btrim(payload ->> 'title'),
      is_default = coalesce((payload ->> 'is_default')::boolean, false),
      disabled = coalesce((payload ->> 'disabled')::boolean, false),
      tax_category_id = nullif(payload ->> 'tax_category_id', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'template_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.sales_tax_template_rows where template_id = v_id;

  insert into public.sales_tax_template_rows (
    merchant_id, template_id, idx, charge_type, account, description, rate, tax_amount, row_id, included_in_print_rate, cost_center
  )
  select
    v_merchant, v_id, r.idx::integer,
    r.value ->> 'charge_type',
    (r.value ->> 'account')::uuid,
    btrim(r.value ->> 'description'),
    coalesce(nullif(r.value ->> 'rate', '')::numeric, 0),
    coalesce(nullif(r.value ->> 'tax_amount', '')::numeric, 0),
    nullif(r.value ->> 'row_id', '')::integer,
    coalesce((r.value ->> 'included_in_print_rate')::boolean, false),
    nullif(r.value ->> 'cost_center', '')::uuid
  from jsonb_array_elements(coalesce(payload -> 'rows', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_sales_tax_template(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_sales_tax_template(jsonb) to authenticated;

create or replace function public.save_item_tax_template(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  if v_id is null then
    insert into public.item_tax_templates (merchant_id, title, disabled)
    values (v_merchant, btrim(payload ->> 'title'), coalesce((payload ->> 'disabled')::boolean, false))
    returning id into v_id;
  else
    update public.item_tax_templates set
      title = btrim(payload ->> 'title'),
      disabled = coalesce((payload ->> 'disabled')::boolean, false)
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'template_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.item_tax_template_rows where template_id = v_id;

  insert into public.item_tax_template_rows (merchant_id, template_id, idx, account, tax_rate, not_applicable)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'account')::uuid,
    coalesce(nullif(r.value ->> 'tax_rate', '')::numeric, 0),
    coalesce((r.value ->> 'not_applicable')::boolean, false)
  from jsonb_array_elements(coalesce(payload -> 'rows', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item_tax_template(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item_tax_template(jsonb) to authenticated;


