-- One system's presets: the tax ledger under the Tax group (Duties and Taxes), a Sales Taxes and Charges
-- Template of one On Net Total row — described "<account> @ <rate>" and tagged with the company's cost
-- center, as taxes_setup.make_taxes_and_charges_template does — and an Item Tax Template of the same title.
-- Re-runnable: what exists is left alone. A preset whose account name the owner already uses for something
-- other than a tax ledger is left out.
create or replace function private.seed_taxes_for(p_merchant uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_country text;
  v_cost_center uuid;
  v_group uuid;
  v_preset record;
  v_account uuid;
  v_template uuid;
begin
  select m.country_code, m.cost_center into v_country, v_cost_center from public.merchants m where m.id = p_merchant;

  select a.id into v_group
  from public.accounts a
  where a.merchant_id = p_merchant and a.is_group and a.root_type = 'Liability' and a.account_type = 'Tax'
  order by a.created_at
  limit 1;

  if v_group is null then
    return;
  end if;

  for v_preset in
    select p.* from public.tax_presets p where p.country_code = v_country order by p.template
  loop
    v_account := private.seed_account(p_merchant, v_preset.account_name, v_group, false, 'Liability', 'Tax');

    if not exists (
      select 1 from public.accounts a where a.id = v_account and a.account_type = 'Tax' and not a.is_group and not a.disabled
    ) then
      continue;
    end if;

    insert into public.sales_tax_templates (merchant_id, title, is_default)
    values (p_merchant, v_preset.template, v_preset.is_default)
    on conflict (merchant_id, title) do nothing
    returning id into v_template;

    if v_template is not null then
      insert into public.sales_tax_template_rows (merchant_id, template_id, idx, charge_type, account, description, rate, cost_center)
      values (
        p_merchant, v_template, 1, 'On Net Total', v_account,
        v_preset.account_name || ' @ ' || trim_scale(v_preset.tax_rate)::text, v_preset.tax_rate, v_cost_center
      );
    end if;

    insert into public.item_tax_templates (merchant_id, title)
    values (p_merchant, v_preset.template)
    on conflict (merchant_id, title) do nothing
    returning id into v_template;

    if v_template is not null then
      insert into public.item_tax_template_rows (merchant_id, template_id, idx, account, tax_rate)
      values (p_merchant, v_template, 1, v_account, v_preset.tax_rate);
    end if;
  end loop;
end;
$$;

revoke execute on function private.seed_taxes_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_taxes()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_taxes_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_taxes() from public, anon, authenticated, service_role;

-- After merchants_seed_40_accounting (the Tax group) and merchants_seed_50_accounting_defaults (the
-- company's cost center), by name.
drop trigger if exists merchants_seed_70_taxes on public.merchants;
create trigger merchants_seed_70_taxes
  after insert on public.merchants
  for each row execute function private.seed_taxes();

-- The systems that already exist.
select private.seed_taxes_for(m.id) from public.merchants m;


-- ===== 20261009171705_stock_building_blocks.sql =====

-- Step 8 of the POS foundation, on ERPNext's model: Stock Building Blocks
-- (.claude/erpnext-docs/POS-System-Only-Features.md 8.1–8.4; docs.frappe.io/erpnext/warehouse, /uom,
-- /managing-fractions-in-uom, /price-lists, /brand, /inventory-account).
--
-- 1. private.validate_tree() serves a third tree: its parent lookup reads the table it fires on.
-- 2. warehouses: where stock is kept, as a tree (All Warehouses → Stores …), each optionally linked to the
--    Stock ledger its value posts to. Restrictable, so a User Permission can hold someone to one warehouse.
-- 3. uoms and uom_conversion_factors: the units items are counted in, whether a unit takes fractions, and how
--    many of one make another.
-- 4. price_lists: the books item prices will be kept in. Selling only, in the system's currency.
-- 5. brands: a brand name, with the sales defaults items of that brand will take.
-- 6. Their doctypes, permissions and policies; the seed: All Warehouses → Stores, thirteen UOMs and three
--    conversions, Standard Selling.
--
-- A warehouse with no account of its own uses its parent's, up the tree, then the Company's Default Inventory
-- Account (docs "Linking stock warehouse and accounts"). ponytail: resolved on the Warehouses screen only —
-- nothing posts stock yet; a server-side resolver lands with stock posting.
--
-- Out of scope, so absent: Warehouse Type, addresses and contacts; buying price lists and a price list's
-- countries; a brand's purchase defaults (no Supplier). Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. The tree rules, now for any tree table. The only change to 20261008224129_tree_and_profile_fixes.sql's
-- version is the parent lookup outside the accounts branch, which named cost_centers.

create or replace function private.validate_tree()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent_group boolean;
  v_parent_root text;
  v_cycle boolean;
  v_children boolean;
begin
  if tg_op = 'DELETE' then
    -- The cost-center root is the company's; it goes only with the system. Deleting the system cascades
    -- here after its row is gone, so a root whose system still exists is a direct delete. (Not
    -- `current_user`: inside a security definer function it is always the owner.)
    if tg_table_name = 'cost_centers' and old.parent_id is null
      and exists (select 1 from public.merchants m where m.id = old.merchant_id) then
      raise exception 'root_locked' using errcode = '42501', detail = 'The company''s cost center cannot be deleted.';
    end if;
    return old;
  end if;

  if tg_op = 'UPDATE' then
    execute format('select exists (select 1 from public.%I where parent_id = $1 and merchant_id = $2)', tg_table_name)
      into v_children using new.id, new.merchant_id;
  else
    v_children := false;
  end if;

  if new.parent_id is null then
    if not new.is_group then
      raise exception 'root_must_be_group' using errcode = '23514', detail = 'A root of the tree must be a group.';
    end if;
  else
    if tg_table_name = 'accounts' then
      execute 'select is_group, root_type from public.accounts where id = $1 and merchant_id = $2'
        into v_parent_group, v_parent_root using new.parent_id, new.merchant_id;
    else
      execute format('select is_group from public.%I where id = $1 and merchant_id = $2', tg_table_name)
        into v_parent_group using new.parent_id, new.merchant_id;
    end if;

    if not coalesce(v_parent_group, false) then
      raise exception 'parent_not_group' using errcode = '23514', detail = 'A parent must be a group.';
    end if;

    if tg_op = 'UPDATE' then
      execute format(
        'with recursive up (id, parent_id) as (
           select id, parent_id from public.%I where id = $1 and merchant_id = $3
           union
           select t.id, t.parent_id from public.%I t join up on t.id = up.parent_id and t.merchant_id = $3
         )
         select exists (select 1 from up where id = $2)',
        tg_table_name, tg_table_name
      ) into v_cycle using new.parent_id, new.id, new.merchant_id;
      if v_cycle then
        raise exception 'tree_cycle' using errcode = '23514', detail = 'A record cannot sit under itself.';
      end if;
    end if;

    if tg_table_name = 'accounts' then
      new.root_type := v_parent_root;
    end if;
  end if;

  if tg_op = 'UPDATE' and v_children then
    if old.is_group and not new.is_group then
      raise exception 'group_has_children' using errcode = '23514', detail = 'A group with records under it cannot become a ledger.';
    end if;
    -- Nested, not `and`-ed: plpgsql may evaluate both sides, and a cost_centers row has no root_type
    -- (42703 "record new has no field root_type" on every edit of a group with children).
    if tg_table_name = 'accounts' then
      if new.root_type is distinct from old.root_type then
        raise exception 'root_type_locked' using errcode = '23514', detail = 'An account with accounts under it cannot move to another root type.';
      end if;
    end if;
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_tree() from public, anon, authenticated, service_role;


-- 2. Warehouses.

create table if not exists public.warehouses (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  warehouse_name text not null,
  -- Null for a root: All Warehouses.
  parent_id uuid,
  is_group boolean not null default false,
  -- The Stock ledger this warehouse's stock value posts to. Null: its parent's, then the company's.
  account uuid,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint warehouses_id_merchant unique (id, merchant_id),
  constraint warehouses_name_unique unique (merchant_id, warehouse_name),
  constraint warehouses_name_length check (length(btrim(warehouse_name)) between 1 and 140),
  -- NO ACTION, as accounts_parent_fk: deleting a system removes the whole tree in one statement.
  constraint warehouses_parent_fk foreign key (parent_id, merchant_id) references public.warehouses (id, merchant_id),
  -- Deleting a ledger a warehouse still names fails with 23503 ("in use").
  constraint warehouses_account_fk foreign key (account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.warehouses enable row level security;
create index if not exists warehouses_parent_idx on public.warehouses (parent_id, merchant_id);
create index if not exists warehouses_account_idx on public.warehouses (account, merchant_id);

drop trigger if exists warehouses_validate_tree on public.warehouses;
create trigger warehouses_validate_tree
  before insert or update or delete on public.warehouses
  for each row execute function private.validate_tree();

-- The account is an enabled Stock ledger — ERPNext's filter on the Warehouse's Account field. Checked only
-- when it changes, so a ledger disabled later does not block the warehouse's other edits. Security definer,
-- as validate_company_accounts is: a User Permission must not hide the account from the check.
create or replace function private.validate_warehouse_account()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ok boolean;
begin
  if new.account is null or (tg_op = 'UPDATE' and new.account is not distinct from old.account) then
    return new;
  end if;

  select not a.is_group and not a.disabled and a.account_type = 'Stock'
  into v_ok
  from public.accounts a where a.id = new.account and a.merchant_id = new.merchant_id;

  if not coalesce(v_ok, false) then
    raise exception 'warehouse_account_invalid' using errcode = '23514',
      detail = 'A warehouse''s account is an enabled Stock ledger.';
  end if;
  return new;
end;
$$;

revoke execute on function private.validate_warehouse_account() from public, anon, authenticated, service_role;

drop trigger if exists warehouses_validate_account on public.warehouses;
create trigger warehouses_validate_account
  before insert or update of account on public.warehouses
  for each row execute function private.validate_warehouse_account();


-- 3. Units of measure, and how they convert.

create table if not exists public.uoms (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  uom_name text not null,
  -- On: a quantity in this unit cannot be a fraction ("Quantity cannot be a fraction at row #").
  must_be_whole_number boolean not null default false,
  enabled boolean not null default true,
  created_at timestamptz not null default now(),

  constraint uoms_id_merchant unique (id, merchant_id),
  constraint uoms_name_unique unique (merchant_id, uom_name),
  constraint uoms_name_length check (length(btrim(uom_name)) between 1 and 140)
);

alter table public.uoms enable row level security;

-- One from_uom is `value` to_uom: 1 Kg = 1000 Gram.
create table if not exists public.uom_conversion_factors (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  from_uom uuid not null,
  to_uom uuid not null,
  value numeric not null,
  created_at timestamptz not null default now(),

  constraint uom_conversion_factors_id_merchant unique (id, merchant_id),
  constraint uom_conversion_factors_pair_unique unique (merchant_id, from_uom, to_uom),
  constraint uom_conversion_factors_value check (value > 0),
  constraint uom_conversion_factors_two_units check (from_uom <> to_uom),
  -- Deleting a unit a conversion names fails with 23503 ("in use").
  constraint uom_conversion_factors_from_fk foreign key (from_uom, merchant_id) references public.uoms (id, merchant_id),
  constraint uom_conversion_factors_to_fk foreign key (to_uom, merchant_id) references public.uoms (id, merchant_id)
);

alter table public.uom_conversion_factors enable row level security;
create index if not exists uom_conversion_factors_from_idx on public.uom_conversion_factors (from_uom, merchant_id);
create index if not exists uom_conversion_factors_to_idx on public.uom_conversion_factors (to_uom, merchant_id);


-- 4. Price Lists. Selling only; the currency is one of the system's (today its base currency).

create table if not exists public.price_lists (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  price_list_name text not null,
  currency text not null,
  enabled boolean not null default true,
  -- On: a price saved per unit also prices the item's bigger units by their conversion factor.
  price_not_uom_dependent boolean not null default false,
  created_at timestamptz not null default now(),

  constraint price_lists_id_merchant unique (id, merchant_id),
  constraint price_lists_name_unique unique (merchant_id, price_list_name),
  constraint price_lists_name_length check (length(btrim(price_list_name)) between 1 and 140),
  constraint price_lists_currency_fk foreign key (merchant_id, currency) references public.currencies (merchant_id, code)
);

alter table public.price_lists enable row level security;


-- 5. Brands, with the sales defaults an item of the brand will take. ERPNext keeps them in a per-company child
-- table; a system is one company, so they are columns.

create table if not exists public.brands (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  brand text not null,
  description text,
  default_warehouse uuid,
  default_price_list uuid,
  selling_cost_center uuid,
  income_account uuid,
  created_at timestamptz not null default now(),

  constraint brands_id_merchant unique (id, merchant_id),
  constraint brands_name_unique unique (merchant_id, brand),
  constraint brands_name_length check (length(btrim(brand)) between 1 and 140),
  constraint brands_description_length check (description is null or length(description) <= 1000),
  -- Deleting a record a brand still names fails with 23503 ("in use").
  constraint brands_warehouse_fk foreign key (default_warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint brands_price_list_fk foreign key (default_price_list, merchant_id) references public.price_lists (id, merchant_id),
  constraint brands_cost_center_fk foreign key (selling_cost_center, merchant_id) references public.cost_centers (id, merchant_id),
  constraint brands_income_account_fk foreign key (income_account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.brands enable row level security;
create index if not exists brands_warehouse_idx on public.brands (default_warehouse, merchant_id);
create index if not exists brands_price_list_idx on public.brands (default_price_list, merchant_id);
create index if not exists brands_cost_center_idx on public.brands (selling_cost_center, merchant_id);
create index if not exists brands_income_account_idx on public.brands (income_account, merchant_id);

-- Each default is one its field takes: a warehouse an enabled non-group one, a price list an enabled one, a
-- cost center an enabled ledger, the income account an enabled ledger under Income. Only a changed default is
-- checked, as private.validate_company_accounts does; definer for the same reason.
create or replace function private.validate_brand_defaults()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ok boolean;
begin
  if new.default_warehouse is not null and (tg_op = 'INSERT' or new.default_warehouse is distinct from old.default_warehouse) then
    select not w.is_group and not w.disabled into v_ok
    from public.warehouses w where w.id = new.default_warehouse and w.merchant_id = new.merchant_id;
    if not coalesce(v_ok, false) then
      raise exception 'brand_default_invalid' using errcode = '23514', detail = 'default_warehouse cannot name that record.';
    end if;
  end if;

  if new.default_price_list is not null and (tg_op = 'INSERT' or new.default_price_list is distinct from old.default_price_list) then
    select p.enabled into v_ok
    from public.price_lists p where p.id = new.default_price_list and p.merchant_id = new.merchant_id;
    if not coalesce(v_ok, false) then
      raise exception 'brand_default_invalid' using errcode = '23514', detail = 'default_price_list cannot name that record.';
    end if;
  end if;

  if new.selling_cost_center is not null and (tg_op = 'INSERT' or new.selling_cost_center is distinct from old.selling_cost_center) then
    select not c.is_group and not c.disabled into v_ok
    from public.cost_centers c where c.id = new.selling_cost_center and c.merchant_id = new.merchant_id;
    if not coalesce(v_ok, false) then
      raise exception 'brand_default_invalid' using errcode = '23514', detail = 'selling_cost_center cannot name that record.';
    end if;
  end if;

  if new.income_account is not null and (tg_op = 'INSERT' or new.income_account is distinct from old.income_account) then
    select not a.is_group and not a.disabled and a.root_type = 'Income' into v_ok
    from public.accounts a where a.id = new.income_account and a.merchant_id = new.merchant_id;
    if not coalesce(v_ok, false) then
      raise exception 'brand_default_invalid' using errcode = '23514', detail = 'income_account cannot name that record.';
    end if;
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_brand_defaults() from public, anon, authenticated, service_role;

drop trigger if exists brands_validate_defaults on public.brands;
create trigger brands_validate_defaults
  before insert or update of default_warehouse, default_price_list, selling_cost_center, income_account on public.brands
  for each row execute function private.validate_brand_defaults();


-- 6. Doctypes, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('Warehouse', 'warehouses', 'tree', true),
  ('UOM', 'uoms', 'record', false),
  ('UOM Conversion Factor', 'uom_conversion_factors', 'record', false),
  ('Price List', 'price_lists', 'record', false),
  ('Brand', 'brands', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Stock Manager', 'Warehouse', true, true, true, true, true),
  ('Item Manager', 'Warehouse', true, true, true, true, true),
  ('Stock User', 'Warehouse', true, true, false, false, false),
  ('Sales User', 'Warehouse', true, true, false, false, false),
  ('Accounts User', 'Warehouse', true, true, false, false, false),
  ('All', 'Warehouse', true, false, false, false, false),
  ('Stock Manager', 'UOM', true, true, true, true, true),
  ('Item Manager', 'UOM', true, true, true, true, true),
  ('All', 'UOM', true, true, false, false, false),
  ('Stock Manager', 'UOM Conversion Factor', true, true, true, true, true),
  ('Item Manager', 'UOM Conversion Factor', true, true, true, true, true),
  ('All', 'UOM Conversion Factor', true, true, false, false, false),
  ('Sales Master Manager', 'Price List', true, true, true, true, true),
  ('Sales Manager', 'Price List', true, true, false, false, false),
  ('Sales User', 'Price List', true, true, false, false, false),
  ('Stock Manager', 'Price List', true, true, false, false, false),
  ('Item Manager', 'Price List', true, true, false, false, false),
  ('Accounts User', 'Price List', true, true, false, false, false),
  ('All', 'Price List', true, false, false, false, false),
  ('Item Manager', 'Brand', true, true, true, true, true),
  ('Sales Master Manager', 'Brand', true, true, true, true, true),
  ('Stock Manager', 'Brand', true, true, false, false, false),
  ('Stock User', 'Brand', true, true, false, false, false),
  ('Sales User', 'Brand', true, true, false, false, false),
  ('All', 'Brand', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('warehouses', 'Warehouse');
select private.apply_doctype_policies('uoms', 'UOM');
select private.apply_doctype_policies('uom_conversion_factors', 'UOM Conversion Factor');
select private.apply_doctype_policies('price_lists', 'Price List');
select private.apply_doctype_policies('brands', 'Brand');


-- 7. Seeding: what ERPNext's company setup and install make, cut to a POS — All Warehouses with Stores under
-- it, the common units and three conversions, and Standard Selling in the company's currency.

create or replace function private.seed_stock_for(p_merchant uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_root uuid;
begin
  insert into public.warehouses (merchant_id, warehouse_name, is_group)
  values (p_merchant, 'All Warehouses', true)
  on conflict (merchant_id, warehouse_name) do nothing;
  select w.id into v_root from public.warehouses w where w.merchant_id = p_merchant and w.warehouse_name = 'All Warehouses';
  -- A renamed or re-parented All Warehouses that is no longer a group gets no Stores under it.
  if exists (select 1 from public.warehouses w where w.id = v_root and w.is_group) then
    insert into public.warehouses (merchant_id, warehouse_name, parent_id)
    values (p_merchant, 'Stores', v_root)
    on conflict (merchant_id, warehouse_name) do nothing;
  end if;

  insert into public.uoms (merchant_id, uom_name, must_be_whole_number)
  values
    (p_merchant, 'Nos', true), (p_merchant, 'Unit', true), (p_merchant, 'Box', true), (p_merchant, 'Pack', true),
    (p_merchant, 'Pair', true), (p_merchant, 'Set', true),
    (p_merchant, 'Kg', false), (p_merchant, 'Gram', false), (p_merchant, 'Litre', false),
    (p_merchant, 'Millilitre', false), (p_merchant, 'Meter', false), (p_merchant, 'Centimeter', false),
    (p_merchant, 'Hour', false)
  on conflict (merchant_id, uom_name) do nothing;

  insert into public.uom_conversion_factors (merchant_id, from_uom, to_uom, value)
  select p_merchant, f.id, t.id, c.value
  from (values ('Kg', 'Gram', 1000), ('Litre', 'Millilitre', 1000), ('Meter', 'Centimeter', 100)) as c (from_name, to_name, value)
  join public.uoms f on f.merchant_id = p_merchant and f.uom_name = c.from_name
  join public.uoms t on t.merchant_id = p_merchant and t.uom_name = c.to_name
  on conflict (merchant_id, from_uom, to_uom) do nothing;

  -- In the company's currency, once merchants_seed_30_defaults has given it a currencies row.
  insert into public.price_lists (merchant_id, price_list_name, currency)
  select m.id, 'Standard Selling', m.default_currency
  from public.merchants m
  where m.id = p_merchant
    and exists (select 1 from public.currencies c where c.merchant_id = m.id and c.code = m.default_currency)
  on conflict (merchant_id, price_list_name) do nothing;
end;
$$;

revoke execute on function private.seed_stock_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_stock()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_stock_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_stock() from public, anon, authenticated, service_role;

-- After merchants_seed_30_defaults, by name: the company's currencies row exists when this runs.
drop trigger if exists merchants_seed_80_stock on public.merchants;
create trigger merchants_seed_80_stock
  after insert on public.merchants
  for each row execute function private.seed_stock();

-- The systems that already exist.
select private.seed_stock_for(m.id) from public.merchants m;


-- ===== 20261010011003_item_groups_and_selling_settings.sql =====

-- Step 9.1–9.2 of the POS foundation, on ERPNext's model: Item Groups and Selling Settings
-- (.claude/erpnext-docs/POS-System-Only-Features.md 9.1, 9.2; docs.frappe.io/erpnext/item-group,
-- /selling-settings).
--
-- 1. private.validate_defaults(): one check for every record that names defaults — a brand's, an item group's,
--    Selling Settings' and Stock Settings'. It replaces private.validate_brand_defaults().
-- 2. item_groups: how items are classified, as a tree (All Item Groups → Products, Services …), with the
--    defaults its items will take: price list, warehouse, selling cost center, income and expense account.
--    Restrictable, so a User Permission can hold someone to one group.
-- 3. item_group_taxes: an item group's Item Tax rows — the Item Tax Template its items take, for a tax
--    category, from a date, within a net-rate range.
-- 4. public.save_item_group(): a group and its tax rows in one transaction.
-- 5. selling_settings: a single per system — the Pricing tab: Default Price List, the fallback to it, editing
--    the Price List Rate, and validating the selling price against valuation.
-- 6. Their doctypes, permissions and policies; the seed: All Item Groups → Products, Services, and Selling
--    Settings on Standard Selling.
--
-- Out of scope, so absent: an item group's Default Supplier and buying cost center (no Supplier), its website
-- settings; Selling Settings' Customer Defaults, Transaction, Advanced Features, Subcontracting and Document
-- Naming tabs (no Customer, Sales Order, Delivery Note or commission). Re-runnable, like the rest of
-- supabase/migrations.

create schema if not exists private;


-- 1. Defaults. Each default a record names must be one its field takes: a warehouse an enabled non-group one,
-- a price list an enabled one, a cost center an enabled ledger, the income account an enabled Income ledger,
-- the expense account an enabled Expense ledger, a unit an enabled one. Columns are read through to_jsonb, so
-- a table without one of them skips it. Only a changed default is checked, as
-- private.validate_company_accounts does: one disabled later does not block the record's other edits.
-- Security definer for the same reason as that function: a User Permission must not hide the record from the
-- check.

create or replace function private.validate_defaults()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_column text;
  v_id uuid;
  v_ok boolean;
begin
  foreach v_column in array array['default_warehouse', 'default_price_list', 'selling_cost_center', 'income_account', 'expense_account', 'stock_uom'] loop
    v_id := (v_new ->> v_column)::uuid;
    continue when v_id is null or (v_new ->> v_column) is not distinct from (v_old ->> v_column);

    v_ok := case v_column
      when 'default_warehouse' then
        (select not w.is_group and not w.disabled from public.warehouses w where w.id = v_id and w.merchant_id = new.merchant_id)
      when 'default_price_list' then
        (select p.enabled from public.price_lists p where p.id = v_id and p.merchant_id = new.merchant_id)
      when 'selling_cost_center' then
        (select not c.is_group and not c.disabled from public.cost_centers c where c.id = v_id and c.merchant_id = new.merchant_id)
      when 'income_account' then
        (select not a.is_group and not a.disabled and a.root_type = 'Income' from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      when 'expense_account' then
        (select not a.is_group and not a.disabled and a.root_type = 'Expense' from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      when 'stock_uom' then
        (select u.enabled from public.uoms u where u.id = v_id and u.merchant_id = new.merchant_id)
    end;

    if not coalesce(v_ok, false) then
      raise exception 'default_invalid' using errcode = '23514', detail = format('%s cannot name that record.', v_column);
    end if;
  end loop;

  return new;
end;
$$;

revoke execute on function private.validate_defaults() from public, anon, authenticated, service_role;

drop trigger if exists brands_validate_defaults on public.brands;
create trigger brands_validate_defaults
  before insert or update of default_warehouse, default_price_list, selling_cost_center, income_account on public.brands
  for each row execute function private.validate_defaults();

drop function if exists private.validate_brand_defaults();


-- 2. Item Groups. ERPNext keeps an item group's defaults in a per-company child table; a system is one
-- company, so they are columns.

create table if not exists public.item_groups (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_group_name text not null,
  -- Null for a root: All Item Groups.
  parent_id uuid,
  is_group boolean not null default false,
  default_price_list uuid,
  default_warehouse uuid,
  selling_cost_center uuid,
  income_account uuid,
  expense_account uuid,
  created_at timestamptz not null default now(),

  constraint item_groups_id_merchant unique (id, merchant_id),
  -- "Nodes in different parts of the tree cannot have the same name."
  constraint item_groups_name_unique unique (merchant_id, item_group_name),
  constraint item_groups_name_length check (length(btrim(item_group_name)) between 1 and 140),
  -- NO ACTION, as accounts_parent_fk: deleting a system removes the whole tree in one statement.
  constraint item_groups_parent_fk foreign key (parent_id, merchant_id) references public.item_groups (id, merchant_id),
  -- Deleting a record an item group still names fails with 23503 ("in use").
  constraint item_groups_price_list_fk foreign key (default_price_list, merchant_id) references public.price_lists (id, merchant_id),
  constraint item_groups_warehouse_fk foreign key (default_warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint item_groups_cost_center_fk foreign key (selling_cost_center, merchant_id) references public.cost_centers (id, merchant_id),
  constraint item_groups_income_account_fk foreign key (income_account, merchant_id) references public.accounts (id, merchant_id),
  constraint item_groups_expense_account_fk foreign key (expense_account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.item_groups enable row level security;
create index if not exists item_groups_parent_idx on public.item_groups (parent_id, merchant_id);
create index if not exists item_groups_price_list_idx on public.item_groups (default_price_list, merchant_id);
create index if not exists item_groups_warehouse_idx on public.item_groups (default_warehouse, merchant_id);
create index if not exists item_groups_cost_center_idx on public.item_groups (selling_cost_center, merchant_id);
create index if not exists item_groups_income_account_idx on public.item_groups (income_account, merchant_id);
create index if not exists item_groups_expense_account_idx on public.item_groups (expense_account, merchant_id);

drop trigger if exists item_groups_validate_tree on public.item_groups;
create trigger item_groups_validate_tree
  before insert or update or delete on public.item_groups
  for each row execute function private.validate_tree();

drop trigger if exists item_groups_validate_defaults on public.item_groups;
create trigger item_groups_validate_defaults
  before insert or update of default_price_list, default_warehouse, selling_cost_center, income_account, expense_account on public.item_groups
  for each row execute function private.validate_defaults();


-- 3. An item group's Item Tax rows (docs 2.3): the Item Tax Template its items take — for one tax category
-- when it names one, from a date when it gives one, and for a net rate inside the range when it sets one.

create table if not exists public.item_group_taxes (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_group_id uuid not null,
  idx integer not null,
  item_tax_template_id uuid not null,
  tax_category_id uuid,
  valid_from date,
  minimum_net_rate numeric not null default 0,
  -- 0: no upper bound.
  maximum_net_rate numeric not null default 0,

  constraint item_group_taxes_rates check (minimum_net_rate >= 0 and maximum_net_rate >= 0),
  -- ERPNext's "Maximum Net Rate cannot be less than Minimum Net Rate".
  constraint item_group_taxes_range check (maximum_net_rate = 0 or minimum_net_rate <= maximum_net_rate),
  constraint item_group_taxes_group_fk foreign key (item_group_id, merchant_id) references public.item_groups (id, merchant_id) on delete cascade,
  -- Deleting a template or category a row names fails with 23503 ("in use").
  constraint item_group_taxes_template_fk foreign key (item_tax_template_id, merchant_id) references public.item_tax_templates (id, merchant_id),
  constraint item_group_taxes_category_fk foreign key (tax_category_id, merchant_id) references public.tax_categories (id, merchant_id)
);

alter table public.item_group_taxes enable row level security;
create index if not exists item_group_taxes_group_idx on public.item_group_taxes (item_group_id, merchant_id);
create index if not exists item_group_taxes_template_idx on public.item_group_taxes (item_tax_template_id, merchant_id);
create index if not exists item_group_taxes_category_idx on public.item_group_taxes (tax_category_id, merchant_id);


-- 4. Saving a group with its tax rows. Security invoker, like public.save_item_tax_template: the caller's own
-- policies decide every row. The rows are replaced as a set; idx is their order in the payload.

create or replace function public.save_item_group(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  if v_id is null then
    insert into public.item_groups (
      merchant_id, item_group_name, parent_id, is_group,
      default_price_list, default_warehouse, selling_cost_center, income_account, expense_account
    )
    values (
      v_merchant,
      btrim(payload ->> 'item_group_name'),
      nullif(payload ->> 'parent_id', '')::uuid,
      coalesce((payload ->> 'is_group')::boolean, false),
      nullif(payload ->> 'default_price_list', '')::uuid,
      nullif(payload ->> 'default_warehouse', '')::uuid,
      nullif(payload ->> 'selling_cost_center', '')::uuid,
      nullif(payload ->> 'income_account', '')::uuid,
      nullif(payload ->> 'expense_account', '')::uuid
    )
    returning id into v_id;
  else
    update public.item_groups set
      item_group_name = btrim(payload ->> 'item_group_name'),
      parent_id = nullif(payload ->> 'parent_id', '')::uuid,
      is_group = coalesce((payload ->> 'is_group')::boolean, false),
      default_price_list = nullif(payload ->> 'default_price_list', '')::uuid,
      default_warehouse = nullif(payload ->> 'default_warehouse', '')::uuid,
      selling_cost_center = nullif(payload ->> 'selling_cost_center', '')::uuid,
      income_account = nullif(payload ->> 'income_account', '')::uuid,
      expense_account = nullif(payload ->> 'expense_account', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'item_group_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.item_group_taxes where item_group_id = v_id;

  insert into public.item_group_taxes (
    merchant_id, item_group_id, idx, item_tax_template_id, tax_category_id, valid_from, minimum_net_rate, maximum_net_rate
  )
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_tax_template_id')::uuid,
    nullif(r.value ->> 'tax_category_id', '')::uuid,
    nullif(r.value ->> 'valid_from', '')::date,
    coalesce(nullif(r.value ->> 'minimum_net_rate', '')::numeric, 0),
    coalesce(nullif(r.value ->> 'maximum_net_rate', '')::numeric, 0)
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item_group(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item_group(jsonb) to authenticated;


-- 5. Selling Settings, the Pricing tab.

create table if not exists public.selling_settings (
  merchant_id uuid primary key references public.merchants (id) on delete cascade,
  -- The price list a sale starts on.
  default_price_list uuid,
  -- An item with no price in the sale's price list takes its price from the default one.
  fallback_to_default_price_list boolean not null default false,
  -- The Price List Rate can be changed on a sale's line.
  editable_price_list_rate boolean not null default false,
  -- A sale below the item's purchase or valuation rate is refused.
  validate_selling_price boolean not null default false,

  -- Deleting the price list named here fails with 23503 ("in use").
  constraint selling_settings_price_list_fk foreign key (default_price_list, merchant_id) references public.price_lists (id, merchant_id)
);

alter table public.selling_settings enable row level security;
create index if not exists selling_settings_price_list_idx on public.selling_settings (default_price_list, merchant_id);

drop trigger if exists selling_settings_validate_defaults on public.selling_settings;
create trigger selling_settings_validate_defaults
  before insert or update of default_price_list on public.selling_settings
  for each row execute function private.validate_defaults();


-- 6. Doctypes, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('Item Group', 'item_groups', 'tree', true),
  ('Selling Settings', 'selling_settings', 'single', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Item Manager', 'Item Group', true, true, true, true, true),
  ('Sales Master Manager', 'Item Group', true, true, true, true, true),
  ('Stock Manager', 'Item Group', true, true, false, false, false),
  ('Stock User', 'Item Group', true, true, false, false, false),
  ('Sales User', 'Item Group', true, true, false, false, false),
  ('All', 'Item Group', true, false, false, false, false),

  ('System Manager', 'Selling Settings', true, true, true, false, false),
  ('Sales Manager', 'Selling Settings', true, true, true, false, false),
  ('All', 'Selling Settings', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('item_groups', 'Item Group');
select private.apply_doctype_policies('item_group_taxes', 'Item Group', true);
select private.apply_doctype_policies('selling_settings', 'Selling Settings');


-- 7. Seeding: ERPNext's install makes All Item Groups with its standard groups under it; a POS keeps Products
-- and Services. Selling Settings starts on Standard Selling, made by merchants_seed_80_stock.

create or replace function private.seed_selling_for(p_merchant uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_root uuid;
begin
  insert into public.item_groups (merchant_id, item_group_name, is_group)
  values (p_merchant, 'All Item Groups', true)
  on conflict (merchant_id, item_group_name) do nothing;
  select g.id into v_root from public.item_groups g where g.merchant_id = p_merchant and g.item_group_name = 'All Item Groups';
  -- A renamed or re-parented All Item Groups that is no longer a group gets nothing under it.
  if exists (select 1 from public.item_groups g where g.id = v_root and g.is_group) then
    insert into public.item_groups (merchant_id, item_group_name, parent_id)
    values (p_merchant, 'Products', v_root), (p_merchant, 'Services', v_root)
    on conflict (merchant_id, item_group_name) do nothing;
  end if;

  insert into public.selling_settings (merchant_id, default_price_list)
  values (
    p_merchant,
    (select p.id from public.price_lists p where p.merchant_id = p_merchant and p.price_list_name = 'Standard Selling' and p.enabled)
  )
  on conflict (merchant_id) do nothing;
end;
$$;

revoke execute on function private.seed_selling_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_selling()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_selling_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_selling() from public, anon, authenticated, service_role;

-- After merchants_seed_80_stock, by name: Standard Selling exists when this runs.
drop trigger if exists merchants_seed_90_selling on public.merchants;
create trigger merchants_seed_90_selling
  after insert on public.merchants
  for each row execute function private.seed_selling();

-- The systems that already exist.
select private.seed_selling_for(m.id) from public.merchants m;


-- ===== 20261010011005_tax_rules.sql =====

-- Step 7 of the POS foundation, on ERPNext's model: Tax Rule
-- (.claude/erpnext-docs/POS-System-Only-Features.md 7.1; docs.frappe.io/erpnext/tax-rule).
--
-- tax_rules: which Sales Taxes and Charges Template a sale takes, chosen from its context — a tax category, an
-- item group, the date — and a priority. A rule only selects a template; the template's rows do the tax.
--
-- Picking the rule for a sale is src/features/tax-rules/resolve.ts, as the tax arithmetic is
-- calculate.ts: the POS Invoice builds its sale on the device. Rejected: a resolve RPC here — a second copy of
-- the same ranking for nothing to call yet.
--
-- Out of scope, so absent: Purchase rules and the Purchase Tax Template (no Supplier), Customer and Customer
-- Group, Supplier, Item (no Item yet), billing and shipping locations (no Address), Use for Shopping Cart, and
-- Company (one company). Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;

create table if not exists public.tax_rules (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  sales_tax_template_id uuid not null,
  -- A blank condition matches every sale; each one filled in narrows the rule.
  tax_category_id uuid,
  item_group_id uuid,
  from_date date,
  to_date date,
  -- 1 is the highest: among rules that match as closely, the lowest number wins.
  priority integer not null default 1,
  created_at timestamptz not null default now(),

  constraint tax_rules_id_merchant unique (id, merchant_id),
  constraint tax_rules_priority check (priority >= 1),
  -- "From Date cannot be greater than To Date."
  constraint tax_rules_dates check (from_date is null or to_date is null or from_date <= to_date),
  -- Deleting a template, category or item group a rule names fails with 23503 ("in use").
  constraint tax_rules_template_fk foreign key (sales_tax_template_id, merchant_id) references public.sales_tax_templates (id, merchant_id),
  constraint tax_rules_category_fk foreign key (tax_category_id, merchant_id) references public.tax_categories (id, merchant_id),
  constraint tax_rules_item_group_fk foreign key (item_group_id, merchant_id) references public.item_groups (id, merchant_id),
  -- ERPNext's "Tax Rule Conflicts with …": the same conditions at the same priority on overlapping dates
  -- (23P01). A blank condition counts as its own value; a blank date as open-ended. btree_gist is installed by
  -- 20261008101635_company_and_fiscal_year.sql.
  constraint tax_rules_no_conflict exclude using gist (
    merchant_id with =,
    (coalesce(tax_category_id, '00000000-0000-0000-0000-000000000000'::uuid)) with =,
    (coalesce(item_group_id, '00000000-0000-0000-0000-000000000000'::uuid)) with =,
    priority with =,
    (daterange(from_date, to_date, '[]')) with &&
  )
);

alter table public.tax_rules enable row level security;
create index if not exists tax_rules_template_idx on public.tax_rules (sales_tax_template_id, merchant_id);
create index if not exists tax_rules_category_idx on public.tax_rules (tax_category_id, merchant_id);
create index if not exists tax_rules_item_group_idx on public.tax_rules (item_group_id, merchant_id);


-- Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). No seed: ERPNext
-- makes no rule, and one tax treatment needs none.

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Tax Rule', 'tax_rules', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Accounts Manager', 'Tax Rule', true, true, true, true, true),
  ('Sales Master Manager', 'Tax Rule', true, true, true, true, true),
  ('Accounts User', 'Tax Rule', true, true, false, false, false),
  ('Sales User', 'Tax Rule', true, true, false, false, false),
  ('All', 'Tax Rule', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('tax_rules', 'Tax Rule');


-- ===== 20261010011013_stock_settings.sql =====

-- Step 10 of the POS foundation, with 9.3, on ERPNext's model: Stock Settings
-- (.claude/erpnext-docs/POS-System-Only-Features.md 9.3, 10.1; docs.frappe.io/erpnext/stock-settings,
-- /fifo-and-moving-average, /change-valuation-method).
--
-- stock_settings: a single per system — how new items are named, the item group, unit and warehouse they
-- start with, the valuation method that will cost each sale, whether stock may go negative, and whether a
-- first sale's rate becomes the item's price.
--
-- Out of scope, so absent: Show Barcode Field (no barcode), LIFO and Standard Cost (FIFO and Moving Average
-- only), sample retention, over-delivery allowances, serial and batch settings, automatic Material Requests,
-- inter-warehouse transfers and frozen stock. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;

create table if not exists public.stock_settings (
  merchant_id uuid primary key references public.merchants (id) on delete cascade,
  -- Item Code: an item is named by the code typed for it. Naming Series: by the Item series (Step 12).
  item_naming_by text not null default 'Item Code',
  -- What a new item starts with.
  item_group uuid,
  stock_uom uuid,
  default_warehouse uuid,
  -- How each sale's cost of goods is worked out; a new item takes it.
  valuation_method text not null default 'FIFO',
  allow_negative_stock boolean not null default false,
  -- An item's first sale writes its rate into the price list as the item's price.
  auto_insert_price_list_rate_if_missing boolean not null default false,

  constraint stock_settings_item_naming_by check (item_naming_by in ('Item Code', 'Naming Series')),
  constraint stock_settings_valuation_method check (valuation_method in ('FIFO', 'Moving Average')),
  -- Deleting a group, unit or warehouse named here fails with 23503 ("in use").
  constraint stock_settings_item_group_fk foreign key (item_group, merchant_id) references public.item_groups (id, merchant_id),
  constraint stock_settings_uom_fk foreign key (stock_uom, merchant_id) references public.uoms (id, merchant_id),
  constraint stock_settings_warehouse_fk foreign key (default_warehouse, merchant_id) references public.warehouses (id, merchant_id)
);

alter table public.stock_settings enable row level security;
create index if not exists stock_settings_item_group_idx on public.stock_settings (item_group, merchant_id);
create index if not exists stock_settings_uom_idx on public.stock_settings (stock_uom, merchant_id);
create index if not exists stock_settings_warehouse_idx on public.stock_settings (default_warehouse, merchant_id);

-- The warehouse an enabled non-group one, the unit an enabled one
-- (20261010011003_item_groups_and_selling_settings.sql).
drop trigger if exists stock_settings_validate_defaults on public.stock_settings;
create trigger stock_settings_validate_defaults
  before insert or update of stock_uom, default_warehouse on public.stock_settings
  for each row execute function private.validate_defaults();


-- Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql).

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Stock Settings', 'stock_settings', 'single', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('System Manager', 'Stock Settings', true, true, true, false, false),
  ('Stock Manager', 'Stock Settings', true, true, true, false, false),
  ('All', 'Stock Settings', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('stock_settings', 'Stock Settings');


-- Seeding: what ERPNext's setup wizard sets — new items in Products, counted in Nos, kept in Stores, valued
-- FIFO. Each default is found by name, so a renamed one is left empty.

create or replace function private.seed_stock_settings_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.stock_settings (merchant_id, item_group, stock_uom, default_warehouse)
  values (
    p_merchant,
    (select g.id from public.item_groups g where g.merchant_id = p_merchant and g.item_group_name = 'Products'),
    (select u.id from public.uoms u where u.merchant_id = p_merchant and u.uom_name = 'Nos' and u.enabled),
    (select w.id from public.warehouses w where w.merchant_id = p_merchant and w.warehouse_name = 'Stores' and not w.is_group and not w.disabled)
  )
  on conflict (merchant_id) do nothing;
$$;

revoke execute on function private.seed_stock_settings_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_stock_settings()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_stock_settings_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_stock_settings() from public, anon, authenticated, service_role;

-- After merchants_seed_80_stock and merchants_seed_90_selling, by name: Nos, Stores and Products exist when
-- this runs. 92, not 100 — triggers fire in name order, and "100" sorts before "20".
drop trigger if exists merchants_seed_92_stock_settings on public.merchants;
create trigger merchants_seed_92_stock_settings
  after insert on public.merchants
  for each row execute function private.seed_stock_settings();

-- The systems that already exist.
select private.seed_stock_settings_for(m.id) from public.merchants m;


-- ===== 20261010064803_naming_series.sql =====

-- Step 12.1–12.2 of the POS foundation, on ERPNext's model: Naming Series and Document Naming Settings
-- (.claude/erpnext-docs/POS-System-Only-Features.md 12.1–12.2; docs.frappe.io/erpnext/naming-series,
-- /document-naming-settings, /naming-series-current-value).
--
-- 1. private.is_naming_series() / are_naming_series(): what a series may be.
-- 2. naming_series: per document — POS Invoice, Sales Invoice, Item — the series it may be numbered by, the
--    first one the default, and whether the person must always pick one.
-- 3. naming_series_counters: ERPNext's tabSeries — the last number given out under each resolved prefix.
-- 4. private.series_prefix() and private.make_name(): a series resolved for a date, and the next name under it.
-- 5. public.naming_series_preview() and public.update_series_counter(): what Document Naming Settings shows,
--    and its Update Series.
-- 6. The doctype, its permissions and policies, and the seed.
--
-- A series, as the docs write them — ACC-SINV-.YYYY.-, SINV12####, PO-.YY.MM.-.####: parts separated by dots.
-- YYYY, YY, MM and DD are the date's; FY is the fiscal year the date falls in; a run of # at the end is the
-- counter, that many digits; no # means five. Anything else is printed as typed.
--
-- The parser lives here only. Rejected: a second copy in TypeScript for a live preview — the database has to
-- hand out the numbers, and two parsers drift.
--
-- Out of scope, so absent: field values in a series (.vendor_id. — custom fields), a counter anywhere but the
-- end, the amended-documents counter, Document Naming Rule, and company-wise series (one company).
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. What a series may be: letters, digits, - / _ and the dots between parts, at least one of them a
-- character that prints, then at most ten #.

create or replace function private.is_naming_series(p_series text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select length(p_series) <= 140 and p_series ~ '^[A-Za-z0-9_/.-]*[A-Za-z0-9_/-][A-Za-z0-9_/.-]*#{0,10}$';
$$;

-- One document's series: one to twenty, each of them a series, none twice.
create or replace function private.are_naming_series(p_options text[])
returns boolean
language sql
immutable
set search_path = ''
as $$
  select cardinality(p_options) between 1 and 20
    and not exists (select 1 from unnest(p_options) s where s is null or not private.is_naming_series(s))
    and (select count(distinct s) from unnest(p_options) s) = cardinality(p_options);
$$;

-- A check constraint runs its function as the writing role, so `authenticated` keeps execute on these two;
-- they only match strings (as private.is_number_format, 20261008151723_defaults_and_money.sql).
revoke execute on function private.is_naming_series(text) from public, anon, authenticated, service_role;
grant execute on function private.is_naming_series(text) to authenticated;
revoke execute on function private.are_naming_series(text[]) from public, anon, authenticated, service_role;
grant execute on function private.are_naming_series(text[]) to authenticated;


-- 2. Naming Series. One row per document that takes one; the rows are made by the seed and go with the system.

create table if not exists public.naming_series (
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  document_type text not null,
  -- "The first prefix will be the default prefix."
  options text[] not null,
  -- "There will be no default naming series if this is ticked."
  user_must_select boolean not null default false,

  primary key (merchant_id, document_type),
  constraint naming_series_document_type check (document_type in ('POS Invoice', 'Sales Invoice', 'Item')),
  constraint naming_series_options check (private.are_naming_series(options))
);

alter table public.naming_series enable row level security;

-- "Edit the series as required with unique prefixes for each series": one series numbers one document, or
-- two documents would share a counter. Security definer, as the other validators are: a writer who cannot read
-- the other rows must not slip past the check.
create or replace function private.naming_series_unique()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_taken text;
begin
  select s into v_taken
  from public.naming_series n
  cross join lateral unnest(n.options) s
  where n.merchant_id = new.merchant_id and n.document_type <> new.document_type and s = any (new.options)
  limit 1;

  if v_taken is not null then
    raise exception 'series_in_use' using errcode = '23505',
      detail = format('%s already numbers another document.', v_taken);
  end if;
  return new;
end;
$$;

revoke execute on function private.naming_series_unique() from public, anon, authenticated, service_role;

drop trigger if exists naming_series_unique on public.naming_series;
create trigger naming_series_unique
  before insert or update of options on public.naming_series
  for each row execute function private.naming_series_unique();


-- 3. The counters. Keyed by the resolved prefix (ACC-SINV-2026-), so a series with the year in it starts
-- again each year by itself. current_value is the last number given out: the next document takes one more.

create table if not exists public.naming_series_counters (
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  prefix text not null,
  current_value bigint not null default 0,

  primary key (merchant_id, prefix),
  constraint naming_series_counters_current_value check (current_value >= 0)
);

alter table public.naming_series_counters enable row level security;


-- 4. A series resolved for a date — today in the system's time zone when none is given — into the prefix its
-- counter is kept under and the counter's digits. A null prefix: the series has .FY. and no enabled fiscal
-- year covers the date. Invoker: it reads System Settings and Fiscal Years as the caller, which every member
-- may (All's Read and Select).
create or replace function private.series_prefix(
  p_merchant uuid, p_series text, p_date date default null, out prefix text, out digits integer
)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_date date := p_date;
  v_body text := rtrim(p_series, '#');
  v_part text;
begin
  if v_date is null then
    select (now() at time zone s.time_zone)::date into v_date from public.system_settings s where s.merchant_id = p_merchant;
    v_date := coalesce(v_date, (now() at time zone 'UTC')::date);
  end if;

  digits := length(p_series) - length(v_body);
  if digits = 0 then
    digits := 5;
  end if;

  prefix := '';
  foreach v_part in array string_to_array(v_body, '.') loop
    prefix := prefix || case v_part
      when 'YYYY' then to_char(v_date, 'YYYY')
      when 'YY' then to_char(v_date, 'YY')
      when 'MM' then to_char(v_date, 'MM')
      when 'DD' then to_char(v_date, 'DD')
      when 'FY' then (
        select f.year from public.fiscal_years f
        where f.merchant_id = p_merchant and not f.disabled and v_date between f.year_start_date and f.year_end_date
      )
      else v_part
    end;
  end loop;
end;
$$;

-- The two public functions below run as the caller and call this one.
revoke execute on function private.series_prefix(uuid, text, date) from public, anon, authenticated, service_role;
grant execute on function private.series_prefix(uuid, text, date) to authenticated;

-- The next name under a series: its counter moved up by one and printed at the series' digits, never cut
-- short. One statement, so two sales at once cannot take the same number. Security definer — a cashier numbers
-- a sale without holding Document Naming Settings — and out of every role's reach: the triggers of the
-- documents that take a series (Item, POS Invoice) call it.
create or replace function private.make_name(p_merchant uuid, p_series text, p_date date default null)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prefix text;
  v_digits integer;
  v_number bigint;
begin
  if (select auth.uid()) is not null and p_merchant not in (select private.current_merchant_ids()) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;

  select p.prefix, p.digits into v_prefix, v_digits from private.series_prefix(p_merchant, p_series, p_date) p;
  if v_prefix is null then
    raise exception 'no_fiscal_year' using errcode = '23514',
      detail = 'No fiscal year covers the date, so .FY. has nothing to print.';
  end if;

  insert into public.naming_series_counters as c (merchant_id, prefix, current_value)
  values (p_merchant, v_prefix, 1)
  on conflict (merchant_id, prefix) do update set current_value = c.current_value + 1
  returning c.current_value into v_number;

  return v_prefix || lpad(v_number::text, greatest(v_digits, length(v_number::text)), '0');
end;
$$;

revoke execute on function private.make_name(uuid, text, date) from public, anon, authenticated, service_role;


-- 5. What Document Naming Settings shows: each document's series in order, the prefix it resolves to today,
-- the counter's current value and the name the next document would take. Security invoker: the caller's own
-- policies decide the rows.
create or replace function public.naming_series_preview(p_merchant uuid)
returns table (document_type text, series text, prefix text, current_value bigint, next_name text)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    n.document_type,
    o.series,
    p.prefix,
    coalesce(c.current_value, 0),
    p.prefix || lpad(
      (coalesce(c.current_value, 0) + 1)::text,
      greatest(p.digits, length((coalesce(c.current_value, 0) + 1)::text)),
      '0'
    )
  from public.naming_series n
  cross join lateral unnest(n.options) with ordinality as o (series, idx)
  cross join lateral private.series_prefix(n.merchant_id, o.series) p
  left join public.naming_series_counters c on c.merchant_id = n.merchant_id and c.prefix = p.prefix
  where n.merchant_id = p_merchant
  order by n.document_type, o.idx;
$$;

revoke execute on function public.naming_series_preview(uuid) from public, anon, authenticated, service_role;
grant execute on function public.naming_series_preview(uuid) to authenticated;

-- Update Series: "select the prefix whose sequence is to be changed … change the current sequence number". Sets
-- the counter of the prefix a series resolves to today. Security invoker: the counters' policies decide.
create or replace function public.update_series_counter(p_merchant uuid, p_series text, p_current bigint)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_prefix text;
begin
  if not exists (select 1 from public.naming_series n where n.merchant_id = p_merchant and p_series = any (n.options)) then
    raise exception 'series_not_found' using errcode = 'P0002';
  end if;

  select p.prefix into v_prefix from private.series_prefix(p_merchant, p_series) p;
  if v_prefix is null then
    raise exception 'no_fiscal_year' using errcode = '23514',
      detail = 'No fiscal year covers today, so .FY. has nothing to print.';
  end if;

  insert into public.naming_series_counters (merchant_id, prefix, current_value)
  values (p_merchant, v_prefix, p_current)
  on conflict (merchant_id, prefix) do update set current_value = excluded.current_value;
end;
$$;

revoke execute on function public.update_series_counter(uuid, text, bigint) from public, anon, authenticated, service_role;
grant execute on function public.update_series_counter(uuid, text, bigint) to authenticated;


-- 6. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). A single: its
-- rows are made by the seed, so select and update only. The counters follow it as a child table.

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Document Naming Settings', 'naming_series', 'single', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values ('System Manager', 'Document Naming Settings', true, true, true, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('naming_series', 'Document Naming Settings');
select private.apply_doctype_policies('naming_series_counters', 'Document Naming Settings', true);


-- Seeding: the series ERPNext ships for the three documents.

create or replace function private.seed_naming_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.naming_series (merchant_id, document_type, options)
  values
    (p_merchant, 'POS Invoice', array['ACC-PSINV-.YYYY.-']),
    (p_merchant, 'Sales Invoice', array['ACC-SINV-.YYYY.-']),
    (p_merchant, 'Item', array['STO-ITEM-.YYYY.-'])
  on conflict (merchant_id, document_type) do nothing;
$$;

revoke execute on function private.seed_naming_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_naming()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_naming_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_naming() from public, anon, authenticated, service_role;

-- 94: after every step so far, and two digits — triggers fire in name order, and "100" sorts before "20".
drop trigger if exists merchants_seed_94_naming on public.merchants;
create trigger merchants_seed_94_naming
  after insert on public.merchants
  for each row execute function private.seed_naming();

-- The systems that already exist.
select private.seed_naming_for(m.id) from public.merchants m;


-- ===== 20261010065138_printing.sql =====

-- Step 12.3–12.5 of the POS foundation, on ERPNext's model: Print Format, Letter Head, Print Settings
-- (.claude/erpnext-docs/POS-System-Only-Features.md 12.3–12.5; docs.frappe.io/erpnext/print-format,
-- /letter-head, /print-settings).
--
-- 1. private.single_default(): one default per system, for any table with merchant_id, id and is_default.
-- 2. letter_heads: the header and footer a printed document carries — the company's name, address, tax ID.
-- 3. print_formats: how the receipt is laid out — its paper, heading, whether the item code prints, a note at
--    the foot.
-- 4. print_settings: a single per system — print with the letter head, compact item print, taxes with zero
--    amount.
-- 5. The doctypes, their permissions and policies, and the seed.
--
-- A print format here is a structured layout, not Jinja or HTML, and a letter head is text: nothing prints yet
-- but the sample receipt on the Print Format page. Real printing and the logo arrive with the POS Invoice.
--
-- Out of scope, so absent: a print format's DocType (only the POS Invoice prints — the column arrives with a
-- second document), Custom Format and Raw Printing, the Print Format Builder, Print Style, the Print Heading
-- master, a letter head's image and HTML; from Print Settings the PDF settings, printing of draft and cancelled
-- documents, page breaks and the print server. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Making a record the default clears the old one in the same statement, as ERPNext does on save. One
-- function for every table shaped (id, merchant_id, is_default). Invoker, like
-- private.sales_tax_templates_single_default: RLS decides whether the caller may touch the other row.
create or replace function private.single_default()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.is_default then
    execute format('update public.%I set is_default = false where merchant_id = $1 and id <> $2 and is_default', tg_table_name)
    using new.merchant_id, new.id;
  end if;
  return new;
end;
$$;

revoke execute on function private.single_default() from public, anon, authenticated, service_role;


-- 2. Letter Heads.

create table if not exists public.letter_heads (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  letter_head_name text not null,
  -- The header, as lines of text: the organization's name, address, tax ID.
  content text not null default '',
  footer text not null default '',
  is_default boolean not null default false,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint letter_heads_id_merchant unique (id, merchant_id),
  constraint letter_heads_name_unique unique (merchant_id, letter_head_name),
  constraint letter_heads_name_length check (length(btrim(letter_head_name)) between 1 and 140),
  constraint letter_heads_content_length check (length(content) <= 1000),
  constraint letter_heads_footer_length check (length(footer) <= 500),
  constraint letter_heads_default_enabled check (not (is_default and disabled))
);

alter table public.letter_heads enable row level security;

-- One default per system.
create unique index if not exists letter_heads_one_default on public.letter_heads (merchant_id) where is_default;

drop trigger if exists letter_heads_single_default on public.letter_heads;
create trigger letter_heads_single_default
  before insert or update of is_default on public.letter_heads
  for each row execute function private.single_default();


-- 3. Print Formats.

create table if not exists public.print_formats (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  print_format_name text not null,
  -- The roll a receipt printer takes, or a page.
  paper text not null default '80mm',
  -- The title printed over the receipt: "Receipt", "Official Receipt". Blank prints none.
  print_heading text not null default '',
  -- ERPNext's Print Hide on Item Code, as its docs' own example.
  show_item_code boolean not null default true,
  footer_note text not null default '',
  is_default boolean not null default false,
  disabled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint print_formats_id_merchant unique (id, merchant_id),
  constraint print_formats_name_unique unique (merchant_id, print_format_name),
  constraint print_formats_name_length check (length(btrim(print_format_name)) between 1 and 140),
  constraint print_formats_paper check (paper in ('58mm', '80mm', 'A4')),
  constraint print_formats_heading_length check (length(print_heading) <= 140),
  constraint print_formats_footer_note_length check (length(footer_note) <= 500),
  constraint print_formats_default_enabled check (not (is_default and disabled))
);

alter table public.print_formats enable row level security;

-- One default per system: the format a receipt takes when the POS Profile names none.
create unique index if not exists print_formats_one_default on public.print_formats (merchant_id) where is_default;

drop trigger if exists print_formats_single_default on public.print_formats;
create trigger print_formats_single_default
  before insert or update of is_default on public.print_formats
  for each row execute function private.single_default();


-- 4. Print Settings. ERPNext's own field names and defaults.

create table if not exists public.print_settings (
  merchant_id uuid primary key references public.merchants (id) on delete cascade,
  -- A printed document starts with the default letter head.
  with_letterhead boolean not null default true,
  -- Four columns — Description, Qty, Rate, Amount — the rest folded into Description.
  compact_item_print boolean not null default true,
  -- A tax that came to nothing is printed too.
  print_taxes_with_zero_amount boolean not null default false
);

alter table public.print_settings enable row level security;


-- 5. Doctypes, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). Everyone who
-- prints a receipt reads all three; a System Manager keeps them.

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('Print Format', 'print_formats', 'record', false),
  ('Letter Head', 'letter_heads', 'record', false),
  ('Print Settings', 'print_settings', 'single', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('System Manager', 'Print Format', true, true, true, true, true),
  ('All', 'Print Format', true, true, false, false, false),
  ('System Manager', 'Letter Head', true, true, true, true, true),
  ('All', 'Letter Head', true, true, false, false, false),
  ('System Manager', 'Print Settings', true, true, true, false, false),
  ('All', 'Print Settings', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('print_formats', 'Print Format');
select private.apply_doctype_policies('letter_heads', 'Letter Head');
select private.apply_doctype_policies('print_settings', 'Print Settings');


-- Seeding: Print Settings as ERPNext ships them; one print format, POS Receipt, on the 80mm roll; and a letter
-- head named and worded as the company — "every company has a default Letter Head". Each is the default only
-- while the system has none, so running this again never takes the default from a record the owner chose.

create or replace function private.seed_printing_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.print_settings (merchant_id) values (p_merchant)
  on conflict (merchant_id) do nothing;

  insert into public.print_formats (merchant_id, print_format_name, print_heading, is_default)
  select p_merchant, 'POS Receipt', 'Receipt',
    not exists (select 1 from public.print_formats f where f.merchant_id = p_merchant and f.is_default)
  on conflict (merchant_id, print_format_name) do nothing;

  insert into public.letter_heads (merchant_id, letter_head_name, content, is_default)
  select m.id, m.name, m.name,
    not exists (select 1 from public.letter_heads l where l.merchant_id = m.id and l.is_default)
  from public.merchants m
  where m.id = p_merchant
  on conflict (merchant_id, letter_head_name) do nothing;
$$;

revoke execute on function private.seed_printing_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_printing()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_printing_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_printing() from public, anon, authenticated, service_role;

-- 96: the last seed, and two digits — triggers fire in name order, and "100" sorts before "20".
drop trigger if exists merchants_seed_96_printing on public.merchants;
create trigger merchants_seed_96_printing
  after insert on public.merchants
  for each row execute function private.seed_printing();

-- The systems that already exist.
select private.seed_printing_for(m.id) from public.merchants m;


-- ===== 20261011134250_items.sql =====

-- Step 13 of the POS system, on ERPNext's model: the Item master
-- (.claude/erpnext-docs/POS-System-Added-Features.md 13.1–13.5; docs.frappe.io/erpnext/item,
-- /Selling-in-different-UOM, /item-tax-template).
--
-- 1. items: a product or service sold — code, name, item group, stock unit, description, brand, Disabled,
--    Maintain Stock; the inventory options (13.2: Valuation Method, Allow Negative Stock, Re-order Level); the
--    defaults a sale falls back on (13.3); the Default Sales Unit of Measure (13.4).
-- 2. item_uoms: the Item's UOMs table — a unit and how many stock units make one of it.
-- 3. item_taxes: the Item's Item Tax rows — an Item Tax Template, for a tax category, from a date. They take
--    priority over the item group's rows (13.5).
-- 4. public.save_item(): an item and its rows in one transaction.
-- 5. The doctype, its permissions and policies. No seed: ERPNext makes no item.
--
-- Out of scope, so absent: barcodes, variants, batches and serial numbers, fixed-asset and manufacturing
-- fields, the purchase, supplier and customer sections, the website and hub sections, automatic re-ordering
-- (Re-order Level stays only as the low-stock threshold). Max Discount and the Discount Account arrive with
-- Step 20; Opening Stock with Step 16; Standard Selling Rate with Step 14. Re-runnable, like the rest of
-- supabase/migrations.

create schema if not exists private;


-- 1. Items. ERPNext keeps an item's defaults in a per-company child table; a system is one company, so they
-- are columns, named as brands' and item groups' are so private.validate_defaults() checks them.

create table if not exists public.items (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  -- Typed, or taken from the Item naming series when Stock Settings names items by it (the trigger below).
  item_code text not null,
  item_name text not null,
  item_group_id uuid not null,
  -- The Default Unit of Measure: the unit stock is counted in.
  stock_uom uuid not null,
  description text,
  brand_id uuid,
  disabled boolean not null default false,
  -- Maintain Stock. Off: a service, with no stock ledger.
  is_stock_item boolean not null default true,
  -- Null: Stock Settings' Default Valuation Method.
  valuation_method text,
  -- On: this item may go below zero even when Stock Settings forbids it.
  allow_negative_stock boolean not null default false,
  -- The low-stock threshold. No Material Request is raised from it.
  reorder_level numeric,
  -- Default Sales Unit of Measure. Null: the stock unit.
  sales_uom uuid,
  default_warehouse uuid,
  default_price_list uuid,
  selling_cost_center uuid,
  income_account uuid,
  expense_account uuid,
  created_at timestamptz not null default now(),

  constraint items_id_merchant unique (id, merchant_id),
  constraint items_code_unique unique (merchant_id, item_code),
  constraint items_code_length check (length(item_code) between 1 and 140),
  constraint items_name_length check (length(btrim(item_name)) between 1 and 140),
  constraint items_valuation_method check (valuation_method in ('FIFO', 'Moving Average')),
  constraint items_reorder_level check (reorder_level >= 0),
  -- Deleting a record an item still names fails with 23503 ("in use").
  constraint items_item_group_fk foreign key (item_group_id, merchant_id) references public.item_groups (id, merchant_id),
  constraint items_stock_uom_fk foreign key (stock_uom, merchant_id) references public.uoms (id, merchant_id),
  constraint items_brand_fk foreign key (brand_id, merchant_id) references public.brands (id, merchant_id),
  constraint items_sales_uom_fk foreign key (sales_uom, merchant_id) references public.uoms (id, merchant_id),
  constraint items_warehouse_fk foreign key (default_warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint items_price_list_fk foreign key (default_price_list, merchant_id) references public.price_lists (id, merchant_id),
  constraint items_cost_center_fk foreign key (selling_cost_center, merchant_id) references public.cost_centers (id, merchant_id),
  constraint items_income_account_fk foreign key (income_account, merchant_id) references public.accounts (id, merchant_id),
  constraint items_expense_account_fk foreign key (expense_account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.items enable row level security;
create index if not exists items_item_group_idx on public.items (item_group_id, merchant_id);
create index if not exists items_stock_uom_idx on public.items (stock_uom, merchant_id);
create index if not exists items_brand_idx on public.items (brand_id, merchant_id);
create index if not exists items_sales_uom_idx on public.items (sales_uom, merchant_id);
create index if not exists items_warehouse_idx on public.items (default_warehouse, merchant_id);
create index if not exists items_price_list_idx on public.items (default_price_list, merchant_id);
create index if not exists items_cost_center_idx on public.items (selling_cost_center, merchant_id);
create index if not exists items_income_account_idx on public.items (income_account, merchant_id);
create index if not exists items_expense_account_idx on public.items (expense_account, merchant_id);

-- An item's code and its group. Security definer: private.make_name() is out of every role's reach, and a
-- User Permission must not hide the item group from the check.
--
-- Stock Settings' Item Naming By decides the code: Naming Series takes the next name of the Item series'
-- first option, whatever was typed; Item Code keeps what was typed. A code never changes afterwards — ERPNext
-- renames through a tool of its own, which is out of scope. A blank name is the code, as ERPNext fills it.
create or replace function private.prepare_item()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_series text;
begin
  if tg_op = 'INSERT' then
    if (select s.item_naming_by from public.stock_settings s where s.merchant_id = new.merchant_id) = 'Naming Series' then
      select n.options[1] into v_series from public.naming_series n where n.merchant_id = new.merchant_id and n.document_type = 'Item';
      if v_series is null then
        raise exception 'no_item_series' using errcode = '23514', detail = 'Document Naming Settings has no series for Item.';
      end if;
      new.item_code := private.make_name(new.merchant_id, v_series);
    end if;

    new.item_code := btrim(coalesce(new.item_code, ''));
    if new.item_code = '' then
      raise exception 'item_code_required' using errcode = '23514', detail = 'Stock Settings names items by Item Code, and none was given.';
    end if;
  elsif new.item_code is distinct from old.item_code then
    raise exception 'item_code_locked' using errcode = '23514', detail = 'An item keeps its code.';
  end if;

  new.item_name := coalesce(nullif(btrim(coalesce(new.item_name, '')), ''), new.item_code);

  -- "Items are classified into it": a leaf, not a group.
  if (tg_op = 'INSERT' or new.item_group_id is distinct from old.item_group_id)
    and coalesce((select g.is_group from public.item_groups g where g.id = new.item_group_id and g.merchant_id = new.merchant_id), true) then
    raise exception 'item_group_is_group' using errcode = '23514', detail = 'An item goes in an item group that is not a group.';
  end if;

  return new;
end;
$$;

revoke execute on function private.prepare_item() from public, anon, authenticated, service_role;

drop trigger if exists items_prepare on public.items;
create trigger items_prepare
  before insert or update on public.items
  for each row execute function private.prepare_item();

-- The stock unit an enabled one, each default a record its field takes (20261010011003).
drop trigger if exists items_validate_defaults on public.items;
create trigger items_validate_defaults
  before insert or update of stock_uom, default_warehouse, default_price_list, selling_cost_center, income_account, expense_account on public.items
  for each row execute function private.validate_defaults();


-- 2. The Item's UOMs table (docs 3.5): one of `uom_id` is `conversion_factor` stock units — a Carton of 10
-- Units has factor 10. The stock unit itself has no row; its factor is 1. A unit with no row here falls back
-- to the system's UOM Conversion Factors when a sale uses it.

create table if not exists public.item_uoms (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_id uuid not null,
  idx integer not null,
  uom_id uuid not null,
  conversion_factor numeric not null,

  constraint item_uoms_factor check (conversion_factor > 0),
  constraint item_uoms_unique unique (item_id, uom_id),
  constraint item_uoms_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id) on delete cascade,
  -- Deleting a unit an item sells in fails with 23503 ("in use").
  constraint item_uoms_uom_fk foreign key (uom_id, merchant_id) references public.uoms (id, merchant_id)
);

alter table public.item_uoms enable row level security;
create index if not exists item_uoms_item_idx on public.item_uoms (item_id, merchant_id);
create index if not exists item_uoms_uom_idx on public.item_uoms (uom_id, merchant_id);


-- 3. The Item's Item Tax rows (docs 3.16): the Item Tax Template it takes, for one tax category when it names
-- one, from a date when it gives one.

create table if not exists public.item_taxes (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_id uuid not null,
  idx integer not null,
  item_tax_template_id uuid not null,
  tax_category_id uuid,
  valid_from date,

  constraint item_taxes_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id) on delete cascade,
  -- Deleting a template or category a row names fails with 23503 ("in use").
  constraint item_taxes_template_fk foreign key (item_tax_template_id, merchant_id) references public.item_tax_templates (id, merchant_id),
  constraint item_taxes_category_fk foreign key (tax_category_id, merchant_id) references public.tax_categories (id, merchant_id)
);

alter table public.item_taxes enable row level security;
create index if not exists item_taxes_item_idx on public.item_taxes (item_id, merchant_id);
create index if not exists item_taxes_template_idx on public.item_taxes (item_tax_template_id, merchant_id);
create index if not exists item_taxes_category_idx on public.item_taxes (tax_category_id, merchant_id);


-- 4. Saving an item with its rows. Security invoker, like public.save_item_group: the caller's own policies
-- decide every row. The rows are replaced as a set; idx is their order in the payload. The code is set on
-- creation only (private.prepare_item).

create or replace function public.save_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  if v_id is null then
    insert into public.items (
      merchant_id, item_code, item_name, item_group_id, stock_uom, description, brand_id, disabled, is_stock_item,
      valuation_method, allow_negative_stock, reorder_level, sales_uom,
      default_warehouse, default_price_list, selling_cost_center, income_account, expense_account
    )
    values (
      v_merchant,
      payload ->> 'item_code',
      payload ->> 'item_name',
      (payload ->> 'item_group_id')::uuid,
      (payload ->> 'stock_uom')::uuid,
      nullif(btrim(payload ->> 'description'), ''),
      nullif(payload ->> 'brand_id', '')::uuid,
      coalesce((payload ->> 'disabled')::boolean, false),
      coalesce((payload ->> 'is_stock_item')::boolean, true),
      nullif(payload ->> 'valuation_method', ''),
      coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      nullif(payload ->> 'reorder_level', '')::numeric,
      nullif(payload ->> 'sales_uom', '')::uuid,
      nullif(payload ->> 'default_warehouse', '')::uuid,
      nullif(payload ->> 'default_price_list', '')::uuid,
      nullif(payload ->> 'selling_cost_center', '')::uuid,
      nullif(payload ->> 'income_account', '')::uuid,
      nullif(payload ->> 'expense_account', '')::uuid
    )
    returning id into v_id;
  else
    update public.items set
      item_name = payload ->> 'item_name',
      item_group_id = (payload ->> 'item_group_id')::uuid,
      stock_uom = (payload ->> 'stock_uom')::uuid,
      description = nullif(btrim(payload ->> 'description'), ''),
      brand_id = nullif(payload ->> 'brand_id', '')::uuid,
      disabled = coalesce((payload ->> 'disabled')::boolean, false),
      is_stock_item = coalesce((payload ->> 'is_stock_item')::boolean, true),
      valuation_method = nullif(payload ->> 'valuation_method', ''),
      allow_negative_stock = coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      reorder_level = nullif(payload ->> 'reorder_level', '')::numeric,
      sales_uom = nullif(payload ->> 'sales_uom', '')::uuid,
      default_warehouse = nullif(payload ->> 'default_warehouse', '')::uuid,
      default_price_list = nullif(payload ->> 'default_price_list', '')::uuid,
      selling_cost_center = nullif(payload ->> 'selling_cost_center', '')::uuid,
      income_account = nullif(payload ->> 'income_account', '')::uuid,
      expense_account = nullif(payload ->> 'expense_account', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.item_uoms where item_id = v_id;

  insert into public.item_uoms (merchant_id, item_id, idx, uom_id, conversion_factor)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'uom_id')::uuid, (r.value ->> 'conversion_factor')::numeric
  from jsonb_array_elements(coalesce(payload -> 'uoms', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.item_taxes where item_id = v_id;

  insert into public.item_taxes (merchant_id, item_id, idx, item_tax_template_id, tax_category_id, valid_from)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_tax_template_id')::uuid,
    nullif(r.value ->> 'tax_category_id', '')::uuid,
    nullif(r.value ->> 'valid_from', '')::date
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item(jsonb) to authenticated;


-- 5. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). ERPNext's
-- matrix for Item: the Item Manager keeps it, everyone who sells, stocks or books it reads it.

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Item', 'items', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Item Manager', 'Item', true, true, true, true, true),
  ('Stock Manager', 'Item', true, true, false, false, false),
  ('Stock User', 'Item', true, true, false, false, false),
  ('Sales Manager', 'Item', true, true, false, false, false),
  ('Sales Master Manager', 'Item', true, true, false, false, false),
  ('Sales User', 'Item', true, true, false, false, false),
  ('Accounts Manager', 'Item', true, true, false, false, false),
  ('Accounts User', 'Item', true, true, false, false, false),
  ('All', 'Item', true, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('items', 'Item');
select private.apply_doctype_policies('item_uoms', 'Item', true);
select private.apply_doctype_policies('item_taxes', 'Item', true);


-- ===== 20261011134357_item_prices.sql =====

-- Step 14 of the POS system, on ERPNext's model: Selling Prices
-- (.claude/erpnext-docs/POS-System-Added-Features.md 14.1; docs.frappe.io/erpnext/item-price,
-- /Selling-in-different-UOM).
--
-- 1. item_prices: the rate of one item in one price list for one unit, with Valid From and Valid Upto.
-- 2. public.save_item(), re-created: a new item's Standard Selling Rate writes its Item Price in Selling
--    Settings' default price list, as ERPNext's Item does on creation.
-- 3. The doctype, its permissions and policies. No seed.
--
-- Finding a sale's price — price list, unit and date, then Selling Settings' fallback and Price Not UOM
-- Dependent — is src/features/item-prices/resolve.ts, as picking a tax rule is resolve.ts: the sale is built
-- on the device. Stock Settings' auto-insert of a missing rate arrives with the POS Invoice (Step 18).
--
-- Out of scope, so absent: buying prices, a price for one Customer or Supplier, a price for one Batch, Packing
-- Unit, Minimum Quantity, Lead Time and Note. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Item Prices.

create table if not exists public.item_prices (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_id uuid not null,
  price_list_id uuid not null,
  -- "A price is always specific to a certain UOM": the item's stock unit, or one of its UOMs rows.
  uom_id uuid not null,
  price_list_rate numeric not null,
  -- Blank: no start, or no end.
  valid_from date,
  valid_upto date,
  created_at timestamptz not null default now(),

  constraint item_prices_id_merchant unique (id, merchant_id),
  constraint item_prices_rate check (price_list_rate >= 0),
  constraint item_prices_dates check (valid_from is null or valid_upto is null or valid_from <= valid_upto),
  -- ERPNext's "Item Price appears multiple times": the same item, price list, unit and dates (23505). Prices
  -- whose dates only overlap are allowed, as there — a dated price over an open-ended one; the later Valid
  -- From wins on a sale.
  constraint item_prices_unique unique nulls not distinct (merchant_id, item_id, price_list_id, uom_id, valid_from, valid_upto),
  -- An item's prices go with it, as ERPNext deletes them with the Item.
  constraint item_prices_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id) on delete cascade,
  -- Deleting a price list or unit a price names fails with 23503 ("in use").
  constraint item_prices_price_list_fk foreign key (price_list_id, merchant_id) references public.price_lists (id, merchant_id),
  constraint item_prices_uom_fk foreign key (uom_id, merchant_id) references public.uoms (id, merchant_id)
);

alter table public.item_prices enable row level security;
create index if not exists item_prices_item_idx on public.item_prices (item_id, merchant_id);
create index if not exists item_prices_price_list_idx on public.item_prices (price_list_id, merchant_id);
create index if not exists item_prices_uom_idx on public.item_prices (uom_id, merchant_id);

-- A price names an enabled price list, and a unit the item is counted or sold in: its stock unit or one of its
-- UOMs rows. Checked when either is set or changed. Security definer, as private.validate_defaults: a User
-- Permission must not hide the record from the check.
create or replace function private.validate_item_price()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (tg_op = 'INSERT' or new.price_list_id is distinct from old.price_list_id)
    and not coalesce((select p.enabled from public.price_lists p where p.id = new.price_list_id and p.merchant_id = new.merchant_id), false) then
    raise exception 'price_list_disabled' using errcode = '23514', detail = 'A price goes in an enabled price list.';
  end if;

  if (tg_op = 'INSERT' or new.uom_id is distinct from old.uom_id or new.item_id is distinct from old.item_id)
    and not exists (
      select 1 from public.items i where i.id = new.item_id and i.merchant_id = new.merchant_id and i.stock_uom = new.uom_id
      union all
      select 1 from public.item_uoms u where u.item_id = new.item_id and u.merchant_id = new.merchant_id and u.uom_id = new.uom_id
    ) then
    raise exception 'uom_not_on_item' using errcode = '23514', detail = 'The unit is neither the item''s stock unit nor in its UOMs table.';
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_item_price() from public, anon, authenticated, service_role;

drop trigger if exists item_prices_validate on public.item_prices;
create trigger item_prices_validate
  before insert or update of item_id, price_list_id, uom_id on public.item_prices
  for each row execute function private.validate_item_price();


-- 2. public.save_item() with the Standard Selling Rate (docs.frappe.io/erpnext/item 2.2): "When creating an
-- Item, entering a value for this field will automatically create an Item Price … Entering a value after the
-- Item has been saved will not work." The price is for the stock unit, with no dates. Still security invoker:
-- the caller needs Item Price create for it, as ERPNext's insert does.

create or replace function public.save_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_rate numeric := nullif(payload ->> 'standard_rate', '')::numeric;
  v_list uuid;
begin
  if v_id is null then
    insert into public.items (
      merchant_id, item_code, item_name, item_group_id, stock_uom, description, brand_id, disabled, is_stock_item,
      valuation_method, allow_negative_stock, reorder_level, sales_uom,
      default_warehouse, default_price_list, selling_cost_center, income_account, expense_account
    )
    values (
      v_merchant,
      payload ->> 'item_code',
      payload ->> 'item_name',
      (payload ->> 'item_group_id')::uuid,
      (payload ->> 'stock_uom')::uuid,
      nullif(btrim(payload ->> 'description'), ''),
      nullif(payload ->> 'brand_id', '')::uuid,
      coalesce((payload ->> 'disabled')::boolean, false),
      coalesce((payload ->> 'is_stock_item')::boolean, true),
      nullif(payload ->> 'valuation_method', ''),
      coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      nullif(payload ->> 'reorder_level', '')::numeric,
      nullif(payload ->> 'sales_uom', '')::uuid,
      nullif(payload ->> 'default_warehouse', '')::uuid,
      nullif(payload ->> 'default_price_list', '')::uuid,
      nullif(payload ->> 'selling_cost_center', '')::uuid,
      nullif(payload ->> 'income_account', '')::uuid,
      nullif(payload ->> 'expense_account', '')::uuid
    )
    returning id into v_id;

    if coalesce(v_rate, 0) > 0 then
      select s.default_price_list into v_list from public.selling_settings s where s.merchant_id = v_merchant;
      if v_list is null then
        raise exception 'no_default_price_list' using errcode = '23514',
          detail = 'Selling Settings names no default price list for the Standard Selling Rate.';
      end if;

      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_merchant, v_id, v_list, (payload ->> 'stock_uom')::uuid, v_rate);
    end if;
  else
    update public.items set
      item_name = payload ->> 'item_name',
      item_group_id = (payload ->> 'item_group_id')::uuid,
      stock_uom = (payload ->> 'stock_uom')::uuid,
      description = nullif(btrim(payload ->> 'description'), ''),
      brand_id = nullif(payload ->> 'brand_id', '')::uuid,
      disabled = coalesce((payload ->> 'disabled')::boolean, false),
      is_stock_item = coalesce((payload ->> 'is_stock_item')::boolean, true),
      valuation_method = nullif(payload ->> 'valuation_method', ''),
      allow_negative_stock = coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      reorder_level = nullif(payload ->> 'reorder_level', '')::numeric,
      sales_uom = nullif(payload ->> 'sales_uom', '')::uuid,
      default_warehouse = nullif(payload ->> 'default_warehouse', '')::uuid,
      default_price_list = nullif(payload ->> 'default_price_list', '')::uuid,
      selling_cost_center = nullif(payload ->> 'selling_cost_center', '')::uuid,
      income_account = nullif(payload ->> 'income_account', '')::uuid,
      expense_account = nullif(payload ->> 'expense_account', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.item_uoms where item_id = v_id;

  insert into public.item_uoms (merchant_id, item_id, idx, uom_id, conversion_factor)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'uom_id')::uuid, (r.value ->> 'conversion_factor')::numeric
  from jsonb_array_elements(coalesce(payload -> 'uoms', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.item_taxes where item_id = v_id;

  insert into public.item_taxes (merchant_id, item_id, idx, item_tax_template_id, tax_category_id, valid_from)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_tax_template_id')::uuid,
    nullif(r.value ->> 'tax_category_id', '')::uuid,
    nullif(r.value ->> 'valid_from', '')::date
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item(jsonb) to authenticated;


-- 3. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). ERPNext gives
-- Item Price to the Sales Master Manager; here the Item Manager keeps it too, since an item's Standard Selling
-- Rate is written with the item.

insert into public.doctypes (name, table_name, kind, restrictable)
values ('Item Price', 'item_prices', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Sales Master Manager', 'Item Price', true, true, true, true, true),
  ('Item Manager', 'Item Price', true, true, true, true, true),
  ('Sales Manager', 'Item Price', true, true, false, false, false),
  ('Sales User', 'Item Price', true, true, false, false, false),
  ('Stock Manager', 'Item Price', true, true, false, false, false),
  ('Stock User', 'Item Price', true, true, false, false, false),
  ('Accounts Manager', 'Item Price', true, true, false, false, false),
  ('Accounts User', 'Item Price', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('item_prices', 'Item Price');


-- ===== 20261011165554_ledgers.sql =====

-- Step 15 of the POS system, on ERPNext's model: the Ledgers — the posting engine every later step uses
-- (.claude/erpnext-docs/POS-System-Added-Features.md 15.1–15.4, and 21.1's Submit and Cancel;
-- docs.frappe.io/erpnext/accounting-entries, /general-ledger, /immutable-ledger-in-erpnext,
-- /freeze-accounting-entries, /stock-ledger, /stock-level-report, /fifo-and-moving-average,
-- /perpetual-inventory, /stock-adjustment-cogs-with-negative-stock, /role-based-permissions).
--
-- 1. Submit and Cancel join the permission matrix and the functions that read it.
-- 2. Two doctype kinds. `document`: submittable — docstatus 0 draft, 1 submitted, 2 cancelled; a signed-in
--    person writes a draft and nothing else. `ledger`: read-only for everyone, the owner included.
-- 3. The ledgers: gl_entries (General Ledger), stock_ledger_entries (Stock Ledger), bins (Stock Balance).
-- 4. The engine, in `private` and out of every role's reach: when a date may be posted to, balanced GL
--    rows, stock movements valued by FIFO or Moving Average, and their reversal.
-- 5. public.submit_document() and public.cancel_document(): the two doors into the engine.
--
-- Known ceiling (ponytail): there is no repost engine. A stock posting dated before the item's last
-- movement in that warehouse is refused, and a cancel is the exact reversal at today's date or it is
-- refused. ERPNext recalculates every later entry instead (Repost Item Valuation).
--
-- Out of scope, so absent: parties and receivables, finance books, accounting dimensions beyond the cost
-- center, multi-currency, batches and serial numbers, Stock Frozen Upto, period closing.
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Submit and Cancel (docs: "Permissions are applied on each stage of the document like Creation, Saving,
-- Submission, Cancellation"). Amend, print, report and export stay out of scope.

alter table public.standard_role_permissions
  add column if not exists can_submit boolean not null default false,
  add column if not exists can_cancel boolean not null default false;

alter table public.role_permissions
  add column if not exists can_submit boolean not null default false,
  add column if not exists can_cancel boolean not null default false;

-- The seam (20261008145056_users_and_access.sql), with the two new permission types.
create or replace function private.permitted_merchant_ids(p_doctype text, p_ptype text)
returns setof uuid
language sql
security definer
stable
set search_path = ''
as $$
  select m.id from public.merchants m where m.owner_id = (select auth.uid())
  union
  select e.merchant_id
  from private.effective_role_ids() e
  join public.role_permissions rp on rp.role_id = e.role_id and rp.doctype = p_doctype
  where case p_ptype
    when 'select' then rp.can_select or rp.can_read
    when 'read' then rp.can_read
    when 'write' then rp.can_write
    when 'create' then rp.can_create
    when 'delete' then rp.can_delete
    when 'submit' then rp.can_submit
    when 'cancel' then rp.can_cancel
    else false
  end;
$$;

create or replace function public.my_permissions(p_merchant uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_owner uuid;
  v_owner_email text;
  v_owner_name text;
  v_perms jsonb;
begin
  select m.owner_id, u.email, p.display_name into v_owner, v_owner_email, v_owner_name
  from public.merchants m
  join auth.users u on u.id = m.owner_id
  left join public.profiles p on p.id = m.owner_id
  where m.id = p_merchant;

  if v_owner is null or v_uid is null then
    return null;
  end if;

  if v_owner = v_uid then
    select jsonb_object_agg(d.name, jsonb_build_object(
      'select', true, 'read', true, 'write', true, 'create', true, 'delete', true, 'submit', true, 'cancel', true
    ))
    into v_perms from public.doctypes d;
  elsif exists (select 1 from public.merchant_members mm where mm.merchant_id = p_merchant and mm.user_id = v_uid and mm.enabled) then
    select coalesce(jsonb_object_agg(x.doctype, jsonb_build_object(
      'select', x.can_select, 'read', x.can_read, 'write', x.can_write, 'create', x.can_create, 'delete', x.can_delete,
      'submit', x.can_submit, 'cancel', x.can_cancel
    )), '{}'::jsonb)
    into v_perms
    from (
      select rp.doctype,
        bool_or(rp.can_select or rp.can_read) as can_select,
        bool_or(rp.can_read) as can_read,
        bool_or(rp.can_write) as can_write,
        bool_or(rp.can_create) as can_create,
        bool_or(rp.can_delete) as can_delete,
        bool_or(rp.can_submit) as can_submit,
        bool_or(rp.can_cancel) as can_cancel
      from private.effective_role_ids() e
      join public.role_permissions rp on rp.role_id = e.role_id
      where e.merchant_id = p_merchant
      group by rp.doctype
    ) x;
  else
    return null;
  end if;

  return jsonb_build_object(
    'is_owner', v_owner = v_uid,
    'owner_email', v_owner_email,
    'owner_name', v_owner_name,
    'perms', v_perms
  );
end;
$$;

create or replace function public.save_role_permissions(p_merchant uuid, p_doctype text, p_rows jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  delete from public.role_permissions rp
  where rp.merchant_id = p_merchant and rp.doctype = p_doctype
    and rp.role_id not in (
      select (r.value ->> 'role_id')::uuid from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) as r (value)
    );

  insert into public.role_permissions (merchant_id, role_id, doctype, can_select, can_read, can_write, can_create, can_delete, can_submit, can_cancel)
  select p_merchant, (r.value ->> 'role_id')::uuid, p_doctype,
    coalesce((r.value ->> 'can_select')::boolean, false),
    coalesce((r.value ->> 'can_read')::boolean, false),
    coalesce((r.value ->> 'can_write')::boolean, false),
    coalesce((r.value ->> 'can_create')::boolean, false),
    coalesce((r.value ->> 'can_delete')::boolean, false),
    coalesce((r.value ->> 'can_submit')::boolean, false),
    coalesce((r.value ->> 'can_cancel')::boolean, false)
  from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) as r (value)
  on conflict (role_id, doctype) do update set
    can_select = excluded.can_select,
    can_read = excluded.can_read,
    can_write = excluded.can_write,
    can_create = excluded.can_create,
    can_delete = excluded.can_delete,
    can_submit = excluded.can_submit,
    can_cancel = excluded.can_cancel;
end;
$$;

create or replace function private.sync_standard_permissions(p_merchant uuid default null)
returns void
language sql
set search_path = ''
as $$
  insert into public.role_permissions (merchant_id, role_id, doctype, can_select, can_read, can_write, can_create, can_delete, can_submit, can_cancel)
  select r.merchant_id, r.id, s.doctype, s.can_select, s.can_read, s.can_write, s.can_create, s.can_delete, s.can_submit, s.can_cancel
  from public.standard_role_permissions s
  join public.roles r on r.role_name = s.role_name and r.is_standard
  where p_merchant is null or r.merchant_id = p_merchant
  on conflict (role_id, doctype) do nothing;
$$;


-- 2. The two kinds.

alter table public.doctypes drop constraint if exists doctypes_kind;
alter table public.doctypes add constraint doctypes_kind
  check (kind in ('record', 'single', 'tree', 'document', 'ledger'));

-- A document's table carries `name`, `posting_date` and `docstatus`. A signed-in person writes a draft and
-- nothing else: a submitted or cancelled document changes only inside the engine, whose functions are
-- security definer — inside them current_user is their owner, not `authenticated` (as private.guard_roles
-- tells a seed from a client).
create or replace function private.guard_docstatus()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.docstatus <> 0 then
      raise exception 'not_a_draft' using errcode = '23514', detail = 'A document starts as a draft; Submit posts it.';
    end if;
    return new;
  end if;

  if old.docstatus <> 0 then
    raise exception 'document_locked' using errcode = '23514', detail = 'A submitted or cancelled document cannot be changed or deleted.';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if new.docstatus <> 0 then
    raise exception 'not_a_draft' using errcode = '23514', detail = 'Submit posts a document; its status cannot be written.';
  end if;
  if new.name is distinct from old.name then
    raise exception 'document_name_locked' using errcode = '23514', detail = 'A document keeps its name.';
  end if;
  return new;
end;
$$;

revoke execute on function private.guard_docstatus() from public, anon, authenticated, service_role;

-- The same for a document's rows. tg_argv[0] is the document's table, tg_argv[1] this table's key to it.
-- A parent the caller cannot read counts as locked.
create or replace function private.guard_docstatus_child()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_row jsonb;
  v_status smallint;
begin
  if tg_op = 'DELETE' then
    v_row := to_jsonb(old);
  else
    v_row := to_jsonb(new);
  end if;

  if current_user in ('authenticated', 'anon') then
    execute format('select d.docstatus from public.%I d where d.id = $1', tg_argv[0])
      into v_status using (v_row ->> tg_argv[1])::uuid;
    if v_status is distinct from 0 then
      raise exception 'document_locked' using errcode = '23514', detail = 'A submitted or cancelled document cannot be changed or deleted.';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

revoke execute on function private.guard_docstatus_child() from public, anon, authenticated, service_role;

-- A document takes its name from the first series of its Document Naming Settings row, when it is first
-- saved — as ERPNext names a draft. tg_argv[0] is the document type. Security definer: private.make_name()
-- is out of every role's reach.
create or replace function private.name_document()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_series text;
begin
  select n.options[1] into v_series
  from public.naming_series n
  where n.merchant_id = new.merchant_id and n.document_type = tg_argv[0];

  if v_series is null then
    raise exception 'no_document_series' using errcode = '23514',
      detail = format('Document Naming Settings has no series for %s.', tg_argv[0]);
  end if;

  new.name := private.make_name(new.merchant_id, v_series);
  return new;
end;
$$;

revoke execute on function private.name_document() from public, anon, authenticated, service_role;

-- The policy helper (20261008145056_users_and_access.sql), with the two kinds.
-- ledger: a select policy and nothing else — only the engine writes it.
-- document: the record's four policies, and the draft-only guard on the table and on each of its rows'
-- tables (found by the row table's foreign key to the document).
create or replace function private.apply_doctype_policies(p_table text, p_doctype text, p_child boolean default false)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_kind text;
  v_parent text;
  v_restrictable boolean;
  v_restrict text := '';
  v_cmd text;
  v_key text;
begin
  select d.kind, d.restrictable, d.table_name into v_kind, v_restrictable, v_parent from public.doctypes d where d.name = p_doctype;
  if v_kind is null then
    raise exception 'unknown doctype %', p_doctype;
  end if;

  foreach v_cmd in array array['select', 'insert', 'update', 'delete'] loop
    execute format('drop policy if exists %I on public.%I', p_table || '_' || v_cmd, p_table);
  end loop;

  if v_restrictable and not p_child then
    v_restrict := format(
      ' and (merchant_id not in (select private.restricted_merchant_ids(%L)) or id in (select private.allowed_record_ids(%L)))',
      p_doctype, p_doctype
    );
  end if;

  execute format(
    'create policy %I on public.%I for select to authenticated using (merchant_id in (select private.permitted_merchant_ids(%L, %L))%s)',
    p_table || '_select', p_table, p_doctype, case when p_child then 'read' else 'select' end, v_restrict
  );

  if v_kind = 'ledger' then
    return;
  end if;

  execute format(
    'create policy %I on public.%I for update to authenticated
       using (merchant_id in (select private.permitted_merchant_ids(%L, ''write''))%s)
       with check (merchant_id in (select private.permitted_merchant_ids(%L, ''write''))%s)',
    p_table || '_update', p_table, p_doctype, v_restrict, p_doctype, v_restrict
  );

  if v_kind = 'single' and not p_child then
    return;
  end if;

  execute format(
    'create policy %I on public.%I for insert to authenticated with check (merchant_id in (select private.permitted_merchant_ids(%L, %L)))',
    p_table || '_insert', p_table, p_doctype, case when p_child then 'write' else 'create' end
  );

  execute format(
    'create policy %I on public.%I for delete to authenticated using (merchant_id in (select private.permitted_merchant_ids(%L, %L))%s)',
    p_table || '_delete', p_table, p_doctype, case when p_child then 'write' else 'delete' end, v_restrict
  );

  if v_kind <> 'document' then
    return;
  end if;

  execute format('drop trigger if exists %I on public.%I', p_table || '_docstatus', p_table);

  if not p_child then
    execute format(
      'create trigger %I before insert or update or delete on public.%I for each row execute function private.guard_docstatus()',
      p_table || '_docstatus', p_table
    );
    return;
  end if;

  select a.attname into v_key
  from pg_catalog.pg_constraint c
  join pg_catalog.pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
  where c.contype = 'f'
    and c.conrelid = format('public.%I', p_table)::regclass
    and c.confrelid = format('public.%I', v_parent)::regclass
    and a.attname <> 'merchant_id';

  if v_key is null then
    raise exception '% has no foreign key to %', p_table, v_parent;
  end if;

  execute format(
    'create trigger %I before insert or update or delete on public.%I for each row execute function private.guard_docstatus_child(%L, %L)',
    p_table || '_docstatus', p_table, v_parent, v_key
  );
end;
$$;


-- 3. The ledgers. Written only by the engine below; a bigint identity key, so rows read in the order they
-- were posted.

-- ERPNext's GL Entry: one debit or credit of one account, from one submitted document.
create table if not exists public.gl_entries (
  id bigint generated always as identity primary key,
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  posting_date date not null,
  account_id uuid not null,
  debit numeric not null default 0,
  credit numeric not null default 0,
  cost_center_id uuid,
  -- The document that posted it: its doctype, its id and its name.
  voucher_type text not null,
  voucher_id uuid not null,
  voucher_no text not null,
  remarks text,
  -- Set when the document is cancelled with Immutable Ledger off: the row leaves every balance.
  is_cancelled boolean not null default false,
  created_at timestamptz not null default now(),

  constraint gl_entries_amounts check (debit >= 0 and credit >= 0 and (debit = 0 or credit = 0)),
  -- Deleting an account or cost center with entries fails with 23503 ("in use").
  constraint gl_entries_account_fk foreign key (account_id, merchant_id) references public.accounts (id, merchant_id),
  constraint gl_entries_cost_center_fk foreign key (cost_center_id, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.gl_entries enable row level security;
create index if not exists gl_entries_posting_idx on public.gl_entries (merchant_id, posting_date desc, id desc);
create index if not exists gl_entries_account_idx on public.gl_entries (account_id, merchant_id);
create index if not exists gl_entries_cost_center_idx on public.gl_entries (cost_center_id, merchant_id);
create index if not exists gl_entries_voucher_idx on public.gl_entries (voucher_id);

-- ERPNext's Stock Ledger Entry: one movement of one item in one warehouse, and what the bin held after it.
create table if not exists public.stock_ledger_entries (
  id bigint generated always as identity primary key,
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  posting_date date not null,
  item_id uuid not null,
  warehouse_id uuid not null,
  -- In above zero, out below.
  actual_qty numeric not null,
  -- "The actual value of the stock at which it was brought under your inventory"; 0 on the way out.
  incoming_rate numeric not null default 0,
  valuation_rate numeric not null default 0,
  qty_after_transaction numeric not null,
  -- Balance Value.
  stock_value numeric not null,
  stock_value_difference numeric not null,
  voucher_type text not null,
  voucher_id uuid not null,
  voucher_no text not null,
  -- The row, or its reversal, of a cancelled document. Stock rows stay in the report either way.
  is_cancelled boolean not null default false,
  created_at timestamptz not null default now(),

  -- Deleting an item or warehouse with movements fails with 23503 ("in use").
  constraint stock_ledger_entries_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id),
  constraint stock_ledger_entries_warehouse_fk foreign key (warehouse_id, merchant_id) references public.warehouses (id, merchant_id)
);

alter table public.stock_ledger_entries enable row level security;
create index if not exists stock_ledger_entries_posting_idx on public.stock_ledger_entries (merchant_id, posting_date desc, id desc);
create index if not exists stock_ledger_entries_item_idx on public.stock_ledger_entries (item_id, merchant_id);
create index if not exists stock_ledger_entries_warehouse_idx on public.stock_ledger_entries (warehouse_id, merchant_id);
create index if not exists stock_ledger_entries_voucher_idx on public.stock_ledger_entries (voucher_id);

-- ERPNext's Bin: what one warehouse holds of one item now — Stock Balance.
create table if not exists public.bins (
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  item_id uuid not null,
  warehouse_id uuid not null,
  actual_qty numeric not null default 0,
  valuation_rate numeric not null default 0,
  -- What the stock is worth: the figure the warehouse's inventory account follows.
  stock_value numeric not null default 0,
  -- FIFO layers, oldest first, each [quantity, rate]. Empty under Moving Average and at or below zero.
  fifo_queue jsonb not null default '[]'::jsonb,
  -- The date of its last movement: nothing is posted before it.
  last_posting_date date,

  primary key (item_id, warehouse_id),
  constraint bins_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id),
  constraint bins_warehouse_fk foreign key (warehouse_id, merchant_id) references public.warehouses (id, merchant_id)
);

alter table public.bins enable row level security;
create index if not exists bins_merchant_idx on public.bins (merchant_id);
create index if not exists bins_item_idx on public.bins (item_id, merchant_id);
create index if not exists bins_warehouse_idx on public.bins (warehouse_id, merchant_id);

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('GL Entry', 'gl_entries', 'ledger', false),
  ('Stock Ledger Entry', 'stock_ledger_entries', 'ledger', false),
  ('Bin', 'bins', 'ledger', false)
on conflict (name) do nothing;

-- ERPNext's matrix for the reports: accounts read the General Ledger, stock and the Accounts Manager the
-- Stock Ledger, and whoever sells or keeps items sees what is on hand.
insert into public.standard_role_permissions (role_name, doctype, can_select, can_read)
values
  ('Accounts Manager', 'GL Entry', true, true),
  ('Accounts User', 'GL Entry', true, true),

  ('Stock Manager', 'Stock Ledger Entry', true, true),
  ('Stock User', 'Stock Ledger Entry', true, true),
  ('Accounts Manager', 'Stock Ledger Entry', true, true),

  ('Stock Manager', 'Bin', true, true),
  ('Stock User', 'Bin', true, true),
  ('Accounts Manager', 'Bin', true, true),
  ('Sales Manager', 'Bin', true, true),
  ('Sales User', 'Bin', true, true),
  ('Item Manager', 'Bin', true, true)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('gl_entries', 'GL Entry');
select private.apply_doctype_policies('stock_ledger_entries', 'Stock Ledger Entry');
select private.apply_doctype_policies('bins', 'Bin');


-- 4. The engine. Every function is security definer with search_path pinned and every name qualified
-- (CLAUDE.md §6.2), revoked from every role: only public.submit_document(), public.cancel_document() and
-- the posters they call reach it, and those check the caller first.

-- frappe's rounded(): Banker's sends an exact half to the even neighbour, Commercial away from zero. Must
-- agree with roundTo() in src/lib/money.ts.
create or replace function private.money_round(p_value numeric, p_precision integer, p_method text)
returns numeric
language sql
immutable
set search_path = ''
as $$
  select case
    when p_method = 'Commercial Rounding' then round(p_value, p_precision)
    when (abs(p_value) * power(10::numeric, p_precision)) % 1 = 0.5
      and trunc(abs(p_value) * power(10::numeric, p_precision)) % 2 = 0
      then sign(p_value) * trunc(abs(p_value) * power(10::numeric, p_precision)) / power(10::numeric, p_precision)
    else round(p_value, p_precision)
  end;
$$;

revoke execute on function private.money_round(numeric, integer, text) from public, anon, authenticated, service_role;

-- An amount at the system's Currency Precision and Rounding Method (System Settings).
create or replace function private.currency_round(p_merchant uuid, p_value numeric)
returns numeric
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select private.money_round(p_value, s.currency_precision, s.rounding_method) from public.system_settings s where s.merchant_id = p_merchant),
    round(p_value, 2)
  );
$$;

revoke execute on function private.currency_round(uuid, numeric) from public, anon, authenticated, service_role;

-- Today in the system's time zone (System Settings), as private.series_prefix() reads it. Invoker, and
-- granted: the save RPCs default a document's posting date with it, and every member may read System
-- Settings.
create or replace function private.merchant_today(p_merchant uuid)
returns date
language sql
stable
set search_path = ''
as $$
  select coalesce(
    (select (now() at time zone s.time_zone)::date from public.system_settings s where s.merchant_id = p_merchant),
    (now() at time zone 'UTC')::date
  );
$$;

revoke execute on function private.merchant_today(uuid) from public, anon, authenticated, service_role;
grant execute on function private.merchant_today(uuid) to authenticated;

-- "Posting is refused outside an enabled Fiscal Year and on or before Accounts Frozen Till." The owner and
-- the role Accounts Settings names may still post into a frozen period. A future date is refused too:
-- with no repost engine it would block every posting until that day came.
create or replace function private.assert_postable(p_merchant uuid, p_date date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_frozen date;
  v_role uuid;
begin
  if p_date is null or p_date > private.merchant_today(p_merchant) then
    raise exception 'posting_date_in_future' using errcode = '23514', detail = 'A posting date cannot be after today.';
  end if;

  if not exists (
    select 1 from public.fiscal_years f
    where f.merchant_id = p_merchant and not f.disabled and p_date between f.year_start_date and f.year_end_date
  ) then
    raise exception 'posting_outside_fiscal_year' using errcode = '23514',
      detail = format('No enabled fiscal year covers %s.', p_date);
  end if;

  select s.accounts_frozen_till_date, s.frozen_accounts_modifier into v_frozen, v_role
  from public.accounts_settings s where s.merchant_id = p_merchant;

  if v_frozen is not null and p_date <= v_frozen
    and not exists (select 1 from public.merchants m where m.id = p_merchant and m.owner_id = (select auth.uid()))
    and not exists (select 1 from private.effective_role_ids() e where e.merchant_id = p_merchant and e.role_id = v_role) then
    raise exception 'accounts_frozen' using errcode = '23514',
      detail = format('Accounts are frozen till %s.', v_frozen);
  end if;
end;
$$;

revoke execute on function private.assert_postable(uuid, date) from public, anon, authenticated, service_role;

-- Post a document's accounting entries. p_rows is [{account_id, amount, cost_center_id}]: an amount above
-- zero is a debit, below zero a credit. Each is rounded to the currency precision, rows of one account and
-- cost center are merged (so a transfer between warehouses that share an account posts nothing), and the
-- total must come to zero: "Every posting must balance." A difference no bigger than rounding can make
-- goes to the Company's Round Off Account; anything more is refused.
create or replace function private.post_gl(
  p_merchant uuid, p_voucher_type text, p_voucher_id uuid, p_voucher_no text, p_date date, p_rows jsonb, p_remarks text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_precision integer;
  v_method text;
  v_company public.merchants;
  v_rows jsonb;
  v_diff numeric;
  v_bad text;
begin
  select s.currency_precision, s.rounding_method into v_precision, v_method
  from public.system_settings s where s.merchant_id = p_merchant;
  v_precision := coalesce(v_precision, 2);

  select * into v_company from public.merchants m where m.id = p_merchant;

  select
    coalesce(jsonb_agg(jsonb_build_object('account_id', t.account_id, 'cost_center_id', t.cost_center_id, 'amount', t.amount)), '[]'::jsonb),
    coalesce(sum(t.amount), 0)
  into v_rows, v_diff
  from (
    select
      r.account_id,
      -- "Cost Center is required for a Profit and Loss account": the row's, else the Company's.
      case when a.root_type in ('Income', 'Expense') then coalesce(r.cost_center_id, v_company.cost_center) end as cost_center_id,
      sum(private.money_round(r.amount, v_precision, coalesce(v_method, 'Banker''s Rounding'))) as amount
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb)) as r (account_id uuid, cost_center_id uuid, amount numeric)
    left join public.accounts a on a.id = r.account_id and a.merchant_id = p_merchant
    group by 1, 2
    having sum(private.money_round(r.amount, v_precision, coalesce(v_method, 'Banker''s Rounding'))) <> 0
  ) t;

  if v_rows = '[]'::jsonb then
    return;
  end if;

  perform private.assert_postable(p_merchant, p_date);

  select coalesce(a.account_name, 'An account') into v_bad
  from jsonb_to_recordset(v_rows) as r (account_id uuid, cost_center_id uuid, amount numeric)
  left join public.accounts a on a.id = r.account_id and a.merchant_id = p_merchant
  where a.id is null or a.is_group or a.disabled
  limit 1;
  if found then
    raise exception 'account_unusable' using errcode = '23514', detail = format('%s is missing, a group or disabled.', v_bad);
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_rows) as r (account_id uuid, cost_center_id uuid, amount numeric)
    join public.accounts a on a.id = r.account_id
    left join public.cost_centers c on c.id = r.cost_center_id and c.merchant_id = p_merchant
    where (a.root_type in ('Income', 'Expense') and r.cost_center_id is null)
      or (r.cost_center_id is not null and (c.id is null or c.is_group or c.disabled))
  ) then
    raise exception 'cost_center_unusable' using errcode = '23514',
      detail = 'An income or expense entry needs an enabled cost center that is not a group.';
  end if;

  if v_diff <> 0 then
    if abs(v_diff) > 5 / power(10::numeric, v_precision) or v_company.round_off_account is null then
      raise exception 'gl_unbalanced' using errcode = '23514', detail = format('Debits and credits differ by %s.', v_diff);
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'account_id', v_company.round_off_account,
      'cost_center_id', coalesce(v_company.round_off_cost_center, v_company.cost_center),
      'amount', -v_diff
    ));
  end if;

  insert into public.gl_entries (merchant_id, posting_date, account_id, debit, credit, cost_center_id, voucher_type, voucher_id, voucher_no, remarks)
  select p_merchant, p_date, r.account_id, greatest(r.amount, 0), greatest(-r.amount, 0), r.cost_center_id,
    p_voucher_type, p_voucher_id, p_voucher_no, p_remarks
  from jsonb_to_recordset(v_rows) as r (account_id uuid, cost_center_id uuid, amount numeric);
end;
$$;

revoke execute on function private.post_gl(uuid, text, uuid, text, date, jsonb, text) from public, anon, authenticated, service_role;

-- Cancel a document's accounting entries, as Accounts Settings say (docs.frappe.io/erpnext/immutable-ledger-in-erpnext).
-- Immutable Ledger on: the entries stay and opposite ones are posted on the day of the cancellation. Off: the
-- entries are marked cancelled and leave every balance.
create or replace function private.cancel_gl(p_merchant uuid, p_voucher_type text, p_voucher_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_immutable boolean;
  v_today date := private.merchant_today(p_merchant);
  v_date date;
begin
  select min(g.posting_date) into v_date
  from public.gl_entries g
  where g.merchant_id = p_merchant and g.voucher_type = p_voucher_type and g.voucher_id = p_voucher_id and not g.is_cancelled;

  if v_date is null then
    return;
  end if;

  select s.enable_immutable_ledger into v_immutable from public.accounts_settings s where s.merchant_id = p_merchant;

  if coalesce(v_immutable, true) then
    perform private.assert_postable(p_merchant, v_today);

    insert into public.gl_entries (merchant_id, posting_date, account_id, debit, credit, cost_center_id, voucher_type, voucher_id, voucher_no, remarks)
    select g.merchant_id, v_today, g.account_id, g.credit, g.debit, g.cost_center_id, g.voucher_type, g.voucher_id, g.voucher_no,
      'On cancellation of ' || g.voucher_no
    from public.gl_entries g
    where g.merchant_id = p_merchant and g.voucher_type = p_voucher_type and g.voucher_id = p_voucher_id and not g.is_cancelled
    order by g.id;
  else
    -- Rewriting entries of a day that is frozen, or outside every fiscal year, is refused like a posting.
    perform private.assert_postable(p_merchant, v_date);

    update public.gl_entries g set is_cancelled = true
    where g.merchant_id = p_merchant and g.voucher_type = p_voucher_type and g.voucher_id = p_voucher_id and not g.is_cancelled;
  end if;
end;
$$;

revoke execute on function private.cancel_gl(uuid, text, uuid) from public, anon, authenticated, service_role;

-- The inventory account a warehouse's stock value posts to: its own, else its nearest parent's, else the
-- Company's Default Inventory Account (docs.frappe.io/erpnext/perpetual-inventory 1.4). Null: none of them.
-- The same walk as inventoryAccount() in src/features/warehouses/queries.ts.
create or replace function private.warehouse_account(p_warehouse uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  with recursive up as (
    select w.id, w.parent_id, w.account, w.merchant_id, 0 as depth
    from public.warehouses w where w.id = p_warehouse
    union all
    select w.id, w.parent_id, w.account, w.merchant_id, up.depth + 1
    from public.warehouses w join up on w.id = up.parent_id
  )
  select coalesce(
    (select up.account from up where up.account is not null order by up.depth limit 1),
    (select m.default_inventory_account from public.merchants m join up on up.merchant_id = m.id where up.depth = 0)
  );
$$;

revoke execute on function private.warehouse_account(uuid) from public, anon, authenticated, service_role;

-- The bin of one item in one warehouse, created when missing and locked until the transaction ends, so two
-- postings cannot value the same stock at once. p_check: a new posting needs an enabled item that maintains
-- stock and an enabled warehouse that is not a group; a reversal does not.
--
-- ponytail: no repost engine. A posting dated before the bin's last movement would change every later
-- valuation, so it is refused. Upgrade path: ERPNext's Repost Item Valuation.
create or replace function private.lock_bin(p_merchant uuid, p_item uuid, p_warehouse uuid, p_date date, p_check boolean default true)
returns public.bins
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_bin public.bins;
begin
  perform private.assert_postable(p_merchant, p_date);

  if p_check then
    if not exists (
      select 1 from public.items i where i.id = p_item and i.merchant_id = p_merchant and i.is_stock_item and not i.disabled
    ) then
      raise exception 'item_unusable' using errcode = '23514', detail = 'Stock moves only for an enabled item that maintains stock.';
    end if;
    if not exists (
      select 1 from public.warehouses w where w.id = p_warehouse and w.merchant_id = p_merchant and not w.is_group and not w.disabled
    ) then
      raise exception 'warehouse_unusable' using errcode = '23514', detail = 'Stock is kept in an enabled warehouse that is not a group.';
    end if;
  end if;

  insert into public.bins (merchant_id, item_id, warehouse_id)
  values (p_merchant, p_item, p_warehouse)
  on conflict (item_id, warehouse_id) do nothing;

  select * into v_bin from public.bins b where b.item_id = p_item and b.warehouse_id = p_warehouse for update;

  if v_bin.last_posting_date is not null and p_date < v_bin.last_posting_date then
    raise exception 'stock_backdated' using errcode = '23514',
      detail = format('This item last moved in that warehouse on %s; a posting cannot be dated before it.', v_bin.last_posting_date);
  end if;

  return v_bin;
end;
$$;

revoke execute on function private.lock_bin(uuid, uuid, uuid, date, boolean) from public, anon, authenticated, service_role;

-- Write one Stock Ledger Entry and bring its bin to what it holds afterwards. Returns the value difference,
-- which is what the warehouse's inventory account moves by. The valuation rate is the stock's value over its
-- quantity; at or below zero the bin keeps its last rate, which is what stock sold from nothing is costed at.
create or replace function private.write_sle(
  p_bin public.bins, p_voucher_type text, p_voucher_id uuid, p_voucher_no text, p_date date,
  p_qty numeric, p_incoming_rate numeric, p_qty_after numeric, p_value_after numeric, p_queue jsonb, p_cancelled boolean default false
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_rate numeric := case when p_qty_after > 0 then p_value_after / p_qty_after else p_bin.valuation_rate end;
begin
  update public.bins b set
    actual_qty = p_qty_after,
    stock_value = p_value_after,
    valuation_rate = v_rate,
    fifo_queue = p_queue,
    last_posting_date = p_date
  where b.item_id = p_bin.item_id and b.warehouse_id = p_bin.warehouse_id;

  insert into public.stock_ledger_entries (
    merchant_id, posting_date, item_id, warehouse_id, actual_qty, incoming_rate, valuation_rate,
    qty_after_transaction, stock_value, stock_value_difference, voucher_type, voucher_id, voucher_no, is_cancelled
  )
  values (
    p_bin.merchant_id, p_date, p_bin.item_id, p_bin.warehouse_id, p_qty, coalesce(p_incoming_rate, 0), v_rate,
    p_qty_after, p_value_after, p_value_after - p_bin.stock_value, p_voucher_type, p_voucher_id, p_voucher_no, p_cancelled
  );

  return p_value_after - p_bin.stock_value;
end;
$$;

revoke execute on function private.write_sle(public.bins, text, uuid, text, date, numeric, numeric, numeric, numeric, jsonb, boolean) from public, anon, authenticated, service_role;

-- One stock movement: p_qty above zero comes in at p_rate, below zero goes out at the item's valuation.
-- Returns the value difference (docs.frappe.io/erpnext/fifo-and-moving-average).
--
-- The valuation method is the item's, else Stock Settings'. FIFO takes the oldest layers first; Moving
-- Average takes the bin's rate. Stock may go below zero only when the item or Stock Settings allow it, and
-- then it is costed at the bin's last rate; stock coming in fills that hole at the same rate before the
-- rest enters at its own (docs.frappe.io/erpnext/stock-adjustment-cogs-with-negative-stock). A bin emptied
-- to exactly zero keeps no value.
create or replace function private.post_sle(
  p_merchant uuid, p_voucher_type text, p_voucher_id uuid, p_voucher_no text, p_date date,
  p_item uuid, p_warehouse uuid, p_qty numeric, p_rate numeric default null
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_bin public.bins;
  v_method text;
  v_allow_negative boolean;
  v_whole boolean;
  v_queue jsonb;
  v_layer jsonb;
  v_left numeric;
  v_take numeric;
  v_hole numeric;
  v_value numeric := 0;
  v_qty_after numeric;
begin
  if coalesce(p_qty, 0) = 0 then
    return 0;
  end if;

  v_bin := private.lock_bin(p_merchant, p_item, p_warehouse, p_date);

  select
    coalesce(i.valuation_method, s.valuation_method, 'FIFO'),
    i.allow_negative_stock or coalesce(s.allow_negative_stock, false),
    u.must_be_whole_number
  into v_method, v_allow_negative, v_whole
  from public.items i
  join public.uoms u on u.id = i.stock_uom
  left join public.stock_settings s on s.merchant_id = i.merchant_id
  where i.id = p_item and i.merchant_id = p_merchant;

  if v_whole and p_qty <> trunc(p_qty) then
    raise exception 'whole_number_required' using errcode = '23514', detail = 'This item is counted in a unit that takes whole numbers only.';
  end if;

  v_qty_after := v_bin.actual_qty + p_qty;

  if p_qty > 0 then
    if p_rate is null or p_rate < 0 then
      raise exception 'rate_required' using errcode = '23514', detail = 'Stock comes in at a rate.';
    end if;

    v_hole := least(greatest(-v_bin.actual_qty, 0), p_qty);
    v_value := private.currency_round(p_merchant, v_hole * v_bin.valuation_rate + (p_qty - v_hole) * p_rate);

    v_queue := case
      when v_qty_after <= 0 or v_method <> 'FIFO' then '[]'::jsonb
      when v_bin.actual_qty <= 0 then jsonb_build_array(jsonb_build_array(v_qty_after, p_rate))
      else v_bin.fifo_queue || jsonb_build_array(jsonb_build_array(p_qty, p_rate))
    end;
  else
    if v_qty_after < 0 and not v_allow_negative then
      raise exception 'insufficient_stock' using errcode = '23514',
        detail = format('%s on hand, %s needed.', v_bin.actual_qty, -p_qty);
    end if;

    v_left := -p_qty;
    v_queue := '[]'::jsonb;

    if v_method = 'FIFO' then
      for v_layer in select q.value from jsonb_array_elements(v_bin.fifo_queue) as q (value) loop
        v_take := least((v_layer ->> 0)::numeric, v_left);
        v_value := v_value + v_take * (v_layer ->> 1)::numeric;
        v_left := v_left - v_take;
        if (v_layer ->> 0)::numeric > v_take then
          v_queue := v_queue || jsonb_build_array(jsonb_build_array((v_layer ->> 0)::numeric - v_take, (v_layer ->> 1)::numeric));
        end if;
      end loop;
    end if;

    -- Moving Average, and whatever the FIFO layers could not cover: the bin's rate.
    v_value := -private.currency_round(p_merchant, v_value + v_left * v_bin.valuation_rate);

    if v_qty_after <= 0 then
      v_queue := '[]'::jsonb;
    end if;
  end if;

  if v_qty_after = 0 then
    v_value := -v_bin.stock_value;
  end if;

  return private.write_sle(
    v_bin, p_voucher_type, p_voucher_id, p_voucher_no, p_date,
    p_qty, case when p_qty > 0 then p_rate end, v_qty_after, v_bin.stock_value + v_value, v_queue
  );
end;
$$;

revoke execute on function private.post_sle(uuid, text, uuid, text, date, uuid, uuid, numeric, numeric) from public, anon, authenticated, service_role;

-- A count: the bin is set to p_qty at p_rate, as Stock Reconciliation does ("sets Quantity and Valuation
-- Rate per Item and Warehouse"). Returns the value difference, or null when the bin already holds exactly
-- that — "None of the items have any change in quantity or value".
create or replace function private.reconcile_sle(
  p_merchant uuid, p_voucher_type text, p_voucher_id uuid, p_voucher_no text, p_date date,
  p_item uuid, p_warehouse uuid, p_qty numeric, p_rate numeric
)
returns numeric
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_bin public.bins;
  v_value_after numeric;
begin
  v_bin := private.lock_bin(p_merchant, p_item, p_warehouse, p_date);

  if p_qty <> trunc(p_qty) and (
    select u.must_be_whole_number from public.items i join public.uoms u on u.id = i.stock_uom where i.id = p_item
  ) then
    raise exception 'whole_number_required' using errcode = '23514', detail = 'This item is counted in a unit that takes whole numbers only.';
  end if;

  v_value_after := private.currency_round(p_merchant, p_qty * p_rate);

  if p_qty = v_bin.actual_qty and v_value_after = v_bin.stock_value then
    return null;
  end if;

  return private.write_sle(
    v_bin, p_voucher_type, p_voucher_id, p_voucher_no, p_date,
    p_qty - v_bin.actual_qty, p_rate, p_qty, v_value_after,
    case when p_qty > 0 then jsonb_build_array(jsonb_build_array(p_qty, p_rate)) else '[]'::jsonb end
  );
end;
$$;

revoke execute on function private.reconcile_sle(uuid, text, uuid, text, date, uuid, uuid, numeric, numeric) from public, anon, authenticated, service_role;

-- Undo one Stock Ledger Entry on p_date: the opposite quantity at the value it moved.
--
-- ponytail: no repost engine, so the reversal is exact or refused. It is refused when the stock is no
-- longer there (insufficient_stock, unless negative stock is allowed) and when taking that value back would
-- leave the bin with value and no stock, or stock worth less than nothing (cancel_blocked) — the stock was
-- issued, sold or revalued since. What is left collapses to one FIFO layer at its average rate.
create or replace function private.reverse_sle(p_entry bigint, p_date date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_sle public.stock_ledger_entries;
  v_bin public.bins;
  v_qty_after numeric;
  v_value_after numeric;
begin
  select * into v_sle from public.stock_ledger_entries s where s.id = p_entry;

  v_bin := private.lock_bin(v_sle.merchant_id, v_sle.item_id, v_sle.warehouse_id, p_date, false);
  v_qty_after := v_bin.actual_qty - v_sle.actual_qty;
  v_value_after := v_bin.stock_value - v_sle.stock_value_difference;

  if v_qty_after < 0 and not coalesce((
    select i.allow_negative_stock or coalesce(s.allow_negative_stock, false)
    from public.items i
    left join public.stock_settings s on s.merchant_id = i.merchant_id
    where i.id = v_sle.item_id
  ), false) then
    raise exception 'insufficient_stock' using errcode = '23514',
      detail = format('%s on hand, %s needed.', v_bin.actual_qty, v_sle.actual_qty);
  end if;

  if (v_qty_after >= 0 and v_value_after < 0) or (v_qty_after = 0 and v_value_after <> 0) or (v_qty_after < 0 and v_value_after > 0) then
    raise exception 'cancel_blocked' using errcode = '23514',
      detail = 'This stock has been issued, sold or counted again since; its value can no longer be taken back.';
  end if;

  perform private.write_sle(
    v_bin, v_sle.voucher_type, v_sle.voucher_id, v_sle.voucher_no, p_date,
    -v_sle.actual_qty, null, v_qty_after, v_value_after,
    case when v_qty_after > 0 then jsonb_build_array(jsonb_build_array(v_qty_after, v_value_after / v_qty_after)) else '[]'::jsonb end,
    true
  );
end;
$$;

revoke execute on function private.reverse_sle(bigint, date) from public, anon, authenticated, service_role;

-- Cancel a document's stock movements: each is reversed today, newest first, and both rows are marked
-- cancelled. Unlike the General Ledger they stay in the Stock Ledger whatever Accounts Settings say — a
-- movement of goods happened, and so did its undoing.
create or replace function private.cancel_sle(p_merchant uuid, p_voucher_type text, p_voucher_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entry bigint;
  v_today date := private.merchant_today(p_merchant);
begin
  for v_entry in
    select s.id from public.stock_ledger_entries s
    where s.merchant_id = p_merchant and s.voucher_type = p_voucher_type and s.voucher_id = p_voucher_id and not s.is_cancelled
    order by s.id desc
  loop
    perform private.reverse_sle(v_entry, v_today);
  end loop;

  update public.stock_ledger_entries s set is_cancelled = true
  where s.merchant_id = p_merchant and s.voucher_type = p_voucher_type and s.voucher_id = p_voucher_id and not s.is_cancelled;
end;
$$;

revoke execute on function private.cancel_sle(uuid, text, uuid) from public, anon, authenticated, service_role;


-- 5. The two doors. Security definer in `public`, so PostgREST serves them — the three rules of
-- CLAUDE.md §6.2: revoked from every role and granted to `authenticated` alone, search_path pinned with
-- every name qualified, and the caller checked inside: signed in, and holding Submit or Cancel on that
-- document type in that system (private.permitted_merchant_ids). The row is locked first, so a second tap
-- waits and then finds the document no longer a draft: one tap, one posting.
--
-- What a document posts is its own function, private.submit_<table>(id), found through the registry
-- (public.doctypes.table_name — written by migrations only, and quoted with %I): a later document adds its
-- function and its doctypes row, and these two stay as they are. A cancel is the same for every document:
-- its stock movements reversed, its accounting entries cancelled.

create or replace function public.submit_document(p_doctype text, p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_table text;
  v_merchant uuid;
  v_status smallint;
begin
  if (select auth.uid()) is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select d.table_name into v_table from public.doctypes d where d.name = p_doctype and d.kind = 'document';
  if v_table is null then
    raise exception 'not_a_document' using errcode = '22023';
  end if;

  execute format('select d.merchant_id, d.docstatus from public.%I d where d.id = $1 for update', v_table)
    into v_merchant, v_status using p_id;

  -- One answer for a document that is not there and one the caller may not submit.
  if v_merchant is null or v_merchant not in (select private.permitted_merchant_ids(p_doctype, 'submit')) then
    raise exception 'not_permitted' using errcode = '42501';
  end if;

  if v_status <> 0 then
    raise exception 'not_a_draft' using errcode = '23514', detail = 'Only a draft can be submitted.';
  end if;

  execute format('select private.%I($1)', 'submit_' || v_table) using p_id;
  execute format('update public.%I set docstatus = 1 where id = $1', v_table) using p_id;
end;
$$;

revoke execute on function public.submit_document(text, uuid) from public, anon, authenticated, service_role;
grant execute on function public.submit_document(text, uuid) to authenticated;

create or replace function public.cancel_document(p_doctype text, p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_table text;
  v_merchant uuid;
  v_status smallint;
begin
  if (select auth.uid()) is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select d.table_name into v_table from public.doctypes d where d.name = p_doctype and d.kind = 'document';
  if v_table is null then
    raise exception 'not_a_document' using errcode = '22023';
  end if;

  execute format('select d.merchant_id, d.docstatus from public.%I d where d.id = $1 for update', v_table)
    into v_merchant, v_status using p_id;

  if v_merchant is null or v_merchant not in (select private.permitted_merchant_ids(p_doctype, 'cancel')) then
    raise exception 'not_permitted' using errcode = '42501';
  end if;

  if v_status <> 1 then
    raise exception 'not_submitted' using errcode = '23514', detail = 'Only a submitted document can be cancelled.';
  end if;

  perform private.cancel_sle(v_merchant, p_doctype, p_id);
  perform private.cancel_gl(v_merchant, p_doctype, p_id);
  execute format('update public.%I set docstatus = 2 where id = $1', v_table) using p_id;
end;
$$;

revoke execute on function public.cancel_document(text, uuid) from public, anon, authenticated, service_role;
grant execute on function public.cancel_document(text, uuid) to authenticated;


-- ===== 20261011170112_stock_in_and_adjustments.sql =====

-- Step 16 of the POS system, on ERPNext's model: Stock In & Adjustments
-- (.claude/erpnext-docs/POS-System-Added-Features.md 16.1–16.3, and 13.2's Opening Stock;
-- docs.frappe.io/erpnext/opening-stock, /stock-reconciliation, /stock-entry, /stock-entry-purpose,
-- /perpetual-inventory 2.6–2.8).
--
-- 1. Their naming series join Document Naming Settings.
-- 2. stock_reconciliations (+ rows): Opening Stock, and the count against the books.
-- 3. stock_entries (+ rows): Material Receipt, Material Issue, Material Transfer.
-- 4. public.save_stock_reconciliation() and public.save_stock_entry(): a draft and its rows.
-- 5. private.submit_stock_reconciliations() and private.submit_stock_entries(): what public.submit_document()
--    posts for each (20261011165554_ledgers.sql). A cancel needs nothing of its own.
-- 6. public.save_item_with_opening_stock(): a new item's Opening Stock and Valuation Rate.
-- 7. The doctypes, their permissions and policies.
--
-- Both documents count in the item's stock unit and name their warehouses once, on the document.
--
-- Out of scope, so absent: the manufacturing, repack and subcontracting purposes, Add to Transit, additional
-- costs, per-row units and warehouses, batches and serial numbers, the spreadsheet upload, barcode scanning,
-- Allow Zero Valuation Rate. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Naming series (20261010064803_naming_series.sql). ERPNext ships MAT-RECO-.YYYY.- and MAT-STE-.YYYY.-.

alter table public.naming_series drop constraint if exists naming_series_document_type;
alter table public.naming_series add constraint naming_series_document_type
  check (document_type in ('POS Invoice', 'Sales Invoice', 'Item', 'Stock Reconciliation', 'Stock Entry'));

-- merchants_seed_94_naming calls this for every new system.
create or replace function private.seed_naming_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.naming_series (merchant_id, document_type, options)
  values
    (p_merchant, 'POS Invoice', array['ACC-PSINV-.YYYY.-']),
    (p_merchant, 'Sales Invoice', array['ACC-SINV-.YYYY.-']),
    (p_merchant, 'Item', array['STO-ITEM-.YYYY.-']),
    (p_merchant, 'Stock Reconciliation', array['MAT-RECO-.YYYY.-']),
    (p_merchant, 'Stock Entry', array['MAT-STE-.YYYY.-'])
  on conflict (merchant_id, document_type) do nothing;
$$;

-- The systems that already exist.
select private.seed_naming_for(m.id) from public.merchants m;


-- The links both documents carry. On a new document an empty Difference Account and Cost Center are filled
-- as ERPNext fills them: the Company's Stock Adjustment Account — or, for Opening Stock, the Temporary
-- ledger ("The Difference Account will be set as 'Temporary Opening'") — and the Company's cost center.
-- Then each changed link must be a record its field takes: a warehouse an enabled one that is not a group,
-- the account and the cost center enabled ledgers; and an Opening Stock's difference never goes to income
-- or expense ("Difference Account must be a Asset/Liability type account, since this Stock Reconciliation
-- is an Opening Entry"). Columns are read through to_jsonb, so the table without warehouses skips them.
-- Security definer, as private.validate_defaults: a User Permission must not hide the record from the check.
create or replace function private.validate_stock_document()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb;
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_column text;
  v_id uuid;
  v_ok boolean;
begin
  if tg_op = 'INSERT' then
    if new.difference_account is null then
      new.difference_account := case
        when to_jsonb(new) ->> 'purpose' = 'Opening Stock' then (
          select a.id from public.accounts a
          where a.merchant_id = new.merchant_id and a.account_type = 'Temporary' and not a.is_group and not a.disabled
          order by a.account_name limit 1
        )
        else (select m.stock_adjustment_account from public.merchants m where m.id = new.merchant_id)
      end;
    end if;
    if new.cost_center is null then
      new.cost_center := (select m.cost_center from public.merchants m where m.id = new.merchant_id);
    end if;
  end if;

  v_new := to_jsonb(new);

  foreach v_column in array array['from_warehouse', 'to_warehouse', 'difference_account', 'cost_center'] loop
    v_id := (v_new ->> v_column)::uuid;
    continue when v_id is null or (v_new ->> v_column) is not distinct from (v_old ->> v_column);

    v_ok := case
      when v_column in ('from_warehouse', 'to_warehouse') then
        (select not w.is_group and not w.disabled from public.warehouses w where w.id = v_id and w.merchant_id = new.merchant_id)
      when v_column = 'difference_account' then
        (select not a.is_group and not a.disabled from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      else
        (select not c.is_group and not c.disabled from public.cost_centers c where c.id = v_id and c.merchant_id = new.merchant_id)
    end;

    if not coalesce(v_ok, false) then
      raise exception 'document_link_invalid' using errcode = '23514', detail = format('%s cannot name that record.', v_column);
    end if;
  end loop;

  if v_new ->> 'purpose' = 'Opening Stock' and (
    select a.root_type in ('Income', 'Expense') from public.accounts a where a.id = new.difference_account
  ) then
    raise exception 'opening_account_invalid' using errcode = '23514',
      detail = 'An Opening Stock''s Difference Account is an asset or liability account.';
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_stock_document() from public, anon, authenticated, service_role;


-- 2. Stock Reconciliation: "the process of counting and evaluating" — each row sets one item's quantity and
-- valuation rate in one warehouse.

create table if not exists public.stock_reconciliations (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  -- From the Stock Reconciliation series, when the draft is first saved (private.name_document).
  name text not null,
  posting_date date not null,
  purpose text not null default 'Stock Reconciliation',
  -- Where the change in stock value goes. Needed only while Perpetual Inventory is on.
  difference_account uuid,
  cost_center uuid,
  -- 0 draft, 1 submitted, 2 cancelled. Moved only by public.submit_document() and public.cancel_document().
  docstatus smallint not null default 0,
  created_at timestamptz not null default now(),

  constraint stock_reconciliations_id_merchant unique (id, merchant_id),
  constraint stock_reconciliations_name_unique unique (merchant_id, name),
  constraint stock_reconciliations_purpose check (purpose in ('Opening Stock', 'Stock Reconciliation')),
  constraint stock_reconciliations_docstatus check (docstatus in (0, 1, 2)),
  -- Deleting an account or cost center a document names fails with 23503 ("in use").
  constraint stock_reconciliations_account_fk foreign key (difference_account, merchant_id) references public.accounts (id, merchant_id),
  constraint stock_reconciliations_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.stock_reconciliations enable row level security;
create index if not exists stock_reconciliations_account_idx on public.stock_reconciliations (difference_account, merchant_id);
create index if not exists stock_reconciliations_cost_center_idx on public.stock_reconciliations (cost_center, merchant_id);

drop trigger if exists stock_reconciliations_name on public.stock_reconciliations;
create trigger stock_reconciliations_name
  before insert on public.stock_reconciliations
  for each row execute function private.name_document('Stock Reconciliation');

drop trigger if exists stock_reconciliations_validate on public.stock_reconciliations;
create trigger stock_reconciliations_validate
  before insert or update on public.stock_reconciliations
  for each row execute function private.validate_stock_document();

create table if not exists public.stock_reconciliation_items (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  stock_reconciliation_id uuid not null,
  idx integer not null,
  item_id uuid not null,
  warehouse_id uuid not null,
  -- What the count found, and what each unit is worth.
  qty numeric not null,
  valuation_rate numeric not null,
  -- Written on submit: what the books held, and the value the count changed.
  current_qty numeric,
  current_valuation_rate numeric,
  amount_difference numeric,

  constraint stock_reconciliation_items_qty check (qty >= 0),
  constraint stock_reconciliation_items_rate check (valuation_rate >= 0),
  -- One count of one item in one warehouse per document.
  constraint stock_reconciliation_items_unique unique (stock_reconciliation_id, item_id, warehouse_id),
  constraint stock_reconciliation_items_parent_fk foreign key (stock_reconciliation_id, merchant_id)
    references public.stock_reconciliations (id, merchant_id) on delete cascade,
  -- Deleting an item or warehouse a document names fails with 23503 ("in use").
  constraint stock_reconciliation_items_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id),
  constraint stock_reconciliation_items_warehouse_fk foreign key (warehouse_id, merchant_id) references public.warehouses (id, merchant_id)
);

alter table public.stock_reconciliation_items enable row level security;
create index if not exists stock_reconciliation_items_parent_idx on public.stock_reconciliation_items (stock_reconciliation_id, merchant_id);
create index if not exists stock_reconciliation_items_item_idx on public.stock_reconciliation_items (item_id, merchant_id);
create index if not exists stock_reconciliation_items_warehouse_idx on public.stock_reconciliation_items (warehouse_id, merchant_id);


-- 3. Stock Entry: stock received (Material Receipt), issued — damage, wastage, own use (Material Issue) —
-- or moved between two warehouses (Material Transfer).

create table if not exists public.stock_entries (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  posting_date date not null,
  purpose text not null,
  -- Source and Target Warehouse: a receipt has only a target, an issue only a source, a transfer both.
  from_warehouse uuid,
  to_warehouse uuid,
  difference_account uuid,
  cost_center uuid,
  docstatus smallint not null default 0,
  created_at timestamptz not null default now(),

  constraint stock_entries_id_merchant unique (id, merchant_id),
  constraint stock_entries_name_unique unique (merchant_id, name),
  constraint stock_entries_purpose check (purpose in ('Material Receipt', 'Material Issue', 'Material Transfer')),
  constraint stock_entries_docstatus check (docstatus in (0, 1, 2)),
  constraint stock_entries_warehouses check (case purpose
    when 'Material Receipt' then from_warehouse is null and to_warehouse is not null
    when 'Material Issue' then from_warehouse is not null and to_warehouse is null
    else from_warehouse is not null and to_warehouse is not null and from_warehouse <> to_warehouse
  end),
  constraint stock_entries_from_warehouse_fk foreign key (from_warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint stock_entries_to_warehouse_fk foreign key (to_warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint stock_entries_account_fk foreign key (difference_account, merchant_id) references public.accounts (id, merchant_id),
  constraint stock_entries_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.stock_entries enable row level security;
create index if not exists stock_entries_from_warehouse_idx on public.stock_entries (from_warehouse, merchant_id);
create index if not exists stock_entries_to_warehouse_idx on public.stock_entries (to_warehouse, merchant_id);
create index if not exists stock_entries_account_idx on public.stock_entries (difference_account, merchant_id);
create index if not exists stock_entries_cost_center_idx on public.stock_entries (cost_center, merchant_id);

drop trigger if exists stock_entries_name on public.stock_entries;
create trigger stock_entries_name
  before insert on public.stock_entries
  for each row execute function private.name_document('Stock Entry');

drop trigger if exists stock_entries_validate on public.stock_entries;
create trigger stock_entries_validate
  before insert or update on public.stock_entries
  for each row execute function private.validate_stock_document();

create table if not exists public.stock_entry_items (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  stock_entry_id uuid not null,
  idx integer not null,
  item_id uuid not null,
  qty numeric not null,
  -- Typed on a receipt ("Item Valuation becomes a mandatory field in the Material Receipt entry"); on an
  -- issue or a transfer, the valuation it left at, written on submit.
  basic_rate numeric,
  -- Written on submit: the value the row moved.
  amount numeric,

  constraint stock_entry_items_qty check (qty > 0),
  constraint stock_entry_items_rate check (basic_rate >= 0),
  constraint stock_entry_items_parent_fk foreign key (stock_entry_id, merchant_id)
    references public.stock_entries (id, merchant_id) on delete cascade,
  constraint stock_entry_items_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id)
);

alter table public.stock_entry_items enable row level security;
create index if not exists stock_entry_items_parent_idx on public.stock_entry_items (stock_entry_id, merchant_id);
create index if not exists stock_entry_items_item_idx on public.stock_entry_items (item_id, merchant_id);


-- 4. Saving a draft with its rows. Security invoker, like public.save_item: the caller's own policies decide
-- every row, and private.guard_docstatus() refuses anything but a draft. The rows are replaced as a set; idx
-- is their order in the payload. An empty posting date is today in the system's time zone.

create or replace function public.save_stock_reconciliation(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_date date := coalesce(nullif(payload ->> 'posting_date', '')::date, private.merchant_today(v_merchant));
begin
  if v_id is null then
    insert into public.stock_reconciliations (merchant_id, posting_date, purpose, difference_account, cost_center)
    values (
      v_merchant,
      v_date,
      coalesce(nullif(payload ->> 'purpose', ''), 'Stock Reconciliation'),
      nullif(payload ->> 'difference_account', '')::uuid,
      nullif(payload ->> 'cost_center', '')::uuid
    )
    returning id into v_id;
  else
    update public.stock_reconciliations set
      posting_date = v_date,
      purpose = coalesce(nullif(payload ->> 'purpose', ''), 'Stock Reconciliation'),
      difference_account = nullif(payload ->> 'difference_account', '')::uuid,
      cost_center = nullif(payload ->> 'cost_center', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    -- RLS filters an UPDATE rather than refusing it.
    if v_id is null then
      raise exception 'stock_reconciliation_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.stock_reconciliation_items where stock_reconciliation_id = v_id;

  insert into public.stock_reconciliation_items (merchant_id, stock_reconciliation_id, idx, item_id, warehouse_id, qty, valuation_rate)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_id')::uuid,
    (r.value ->> 'warehouse_id')::uuid,
    (r.value ->> 'qty')::numeric,
    coalesce(nullif(r.value ->> 'valuation_rate', '')::numeric, 0)
  from jsonb_array_elements(coalesce(payload -> 'items', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_stock_reconciliation(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_stock_reconciliation(jsonb) to authenticated;

create or replace function public.save_stock_entry(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_date date := coalesce(nullif(payload ->> 'posting_date', '')::date, private.merchant_today(v_merchant));
begin
  if v_id is null then
    insert into public.stock_entries (merchant_id, posting_date, purpose, from_warehouse, to_warehouse, difference_account, cost_center)
    values (
      v_merchant,
      v_date,
      payload ->> 'purpose',
      nullif(payload ->> 'from_warehouse', '')::uuid,
      nullif(payload ->> 'to_warehouse', '')::uuid,
      nullif(payload ->> 'difference_account', '')::uuid,
      nullif(payload ->> 'cost_center', '')::uuid
    )
    returning id into v_id;
  else
    update public.stock_entries set
      posting_date = v_date,
      purpose = payload ->> 'purpose',
      from_warehouse = nullif(payload ->> 'from_warehouse', '')::uuid,
      to_warehouse = nullif(payload ->> 'to_warehouse', '')::uuid,
      difference_account = nullif(payload ->> 'difference_account', '')::uuid,
      cost_center = nullif(payload ->> 'cost_center', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'stock_entry_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.stock_entry_items where stock_entry_id = v_id;

  insert into public.stock_entry_items (merchant_id, stock_entry_id, idx, item_id, qty, basic_rate)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_id')::uuid,
    (r.value ->> 'qty')::numeric,
    nullif(r.value ->> 'basic_rate', '')::numeric
  from jsonb_array_elements(coalesce(payload -> 'items', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_stock_entry(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_stock_entry(jsonb) to authenticated;


-- 5. What each document posts. Called only by public.submit_document(), which has checked the caller and
-- locked the draft. Security definer, search_path pinned, out of every role's reach.
--
-- With Perpetual Inventory, each change in stock value moves the warehouse's inventory account, and the
-- other side is the document's Difference Account (docs.frappe.io/erpnext/perpetual-inventory). Off, only
-- the stock ledger is written.

-- Each row sets its bin; a row that changes nothing posts nothing, and a document of such rows is refused.
create or replace function private.submit_stock_reconciliations(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.stock_reconciliations;
  v_row public.stock_reconciliation_items;
  v_perpetual boolean;
  v_account uuid;
  v_bin record;
  v_value numeric;
  v_gl jsonb := '[]'::jsonb;
  v_changed boolean := false;
begin
  select * into v_doc from public.stock_reconciliations d where d.id = p_id;
  select m.enable_perpetual_inventory into v_perpetual from public.merchants m where m.id = v_doc.merchant_id;

  if v_perpetual and v_doc.difference_account is null then
    raise exception 'difference_account_required' using errcode = '23514',
      detail = 'With Perpetual Inventory on, the change in stock value needs a Difference Account.';
  end if;

  for v_row in
    select * from public.stock_reconciliation_items r where r.stock_reconciliation_id = p_id order by r.idx
  loop
    if v_row.qty > 0 and v_row.valuation_rate <= 0 then
      raise exception 'valuation_rate_required' using errcode = '23514', detail = 'Stock on hand needs a valuation rate above zero.';
    end if;

    select b.actual_qty, b.valuation_rate into v_bin
    from public.bins b where b.item_id = v_row.item_id and b.warehouse_id = v_row.warehouse_id;

    v_value := private.reconcile_sle(
      v_doc.merchant_id, 'Stock Reconciliation', p_id, v_doc.name, v_doc.posting_date,
      v_row.item_id, v_row.warehouse_id, v_row.qty, v_row.valuation_rate
    );

    update public.stock_reconciliation_items r set
      current_qty = coalesce(v_bin.actual_qty, 0),
      current_valuation_rate = coalesce(v_bin.valuation_rate, 0),
      amount_difference = coalesce(v_value, 0)
    where r.id = v_row.id;

    continue when v_value is null;
    v_changed := true;

    if v_perpetual then
      v_account := private.warehouse_account(v_row.warehouse_id);
      if v_account is null then
        raise exception 'no_inventory_account' using errcode = '23514',
          detail = 'Neither the warehouse, its parents nor the Company names an inventory account.';
      end if;

      v_gl := v_gl || jsonb_build_array(
        jsonb_build_object('account_id', v_account, 'amount', v_value),
        jsonb_build_object('account_id', v_doc.difference_account, 'amount', -v_value, 'cost_center_id', v_doc.cost_center)
      );
    end if;
  end loop;

  if not v_changed then
    raise exception 'nothing_to_reconcile' using errcode = '23514', detail = 'None of the items have any change in quantity or value.';
  end if;

  perform private.post_gl(v_doc.merchant_id, 'Stock Reconciliation', p_id, v_doc.name, v_doc.posting_date, v_gl);
end;
$$;

revoke execute on function private.submit_stock_reconciliations(uuid) from public, anon, authenticated, service_role;

-- A receipt brings each row in at its rate; an issue takes it out at its valuation; a transfer takes it
-- out of the source and into the target at that same value. Two warehouses that share an inventory account
-- net to nothing in the books (private.post_gl merges an account's rows).
create or replace function private.submit_stock_entries(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.stock_entries;
  v_row public.stock_entry_items;
  v_perpetual boolean;
  v_from uuid;
  v_to uuid;
  v_out numeric;
  v_in numeric;
  v_gl jsonb := '[]'::jsonb;
  v_rows integer := 0;
begin
  select * into v_doc from public.stock_entries d where d.id = p_id;
  select m.enable_perpetual_inventory into v_perpetual from public.merchants m where m.id = v_doc.merchant_id;

  if v_perpetual then
    v_from := private.warehouse_account(v_doc.from_warehouse);
    v_to := private.warehouse_account(v_doc.to_warehouse);

    if (v_doc.from_warehouse is not null and v_from is null) or (v_doc.to_warehouse is not null and v_to is null) then
      raise exception 'no_inventory_account' using errcode = '23514',
        detail = 'Neither the warehouse, its parents nor the Company names an inventory account.';
    end if;
    if v_doc.difference_account is null then
      raise exception 'difference_account_required' using errcode = '23514',
        detail = 'With Perpetual Inventory on, the change in stock value needs a Difference Account.';
    end if;
  end if;

  for v_row in
    select * from public.stock_entry_items r where r.stock_entry_id = p_id order by r.idx
  loop
    v_rows := v_rows + 1;
    v_out := 0;
    v_in := 0;

    if v_doc.purpose = 'Material Receipt' then
      if coalesce(v_row.basic_rate, 0) <= 0 then
        raise exception 'rate_required' using errcode = '23514', detail = 'A receipt needs each row''s rate.';
      end if;
      v_in := private.post_sle(
        v_doc.merchant_id, 'Stock Entry', p_id, v_doc.name, v_doc.posting_date, v_row.item_id, v_doc.to_warehouse, v_row.qty, v_row.basic_rate
      );
    else
      v_out := private.post_sle(
        v_doc.merchant_id, 'Stock Entry', p_id, v_doc.name, v_doc.posting_date, v_row.item_id, v_doc.from_warehouse, -v_row.qty
      );
      if v_doc.purpose = 'Material Transfer' then
        v_in := private.post_sle(
          v_doc.merchant_id, 'Stock Entry', p_id, v_doc.name, v_doc.posting_date, v_row.item_id, v_doc.to_warehouse, v_row.qty, -v_out / v_row.qty
        );
      end if;
    end if;

    -- What the row moved, for the page: the rate it came in at, or the valuation it left at.
    update public.stock_entry_items r set
      basic_rate = case when v_doc.purpose = 'Material Receipt' then r.basic_rate else -v_out / r.qty end,
      amount = case when v_doc.purpose = 'Material Receipt' then v_in else -v_out end
    where r.id = v_row.id;

    v_gl := v_gl || jsonb_build_array(
      jsonb_build_object('account_id', v_from, 'amount', v_out),
      jsonb_build_object('account_id', v_to, 'amount', v_in),
      -- The stock value that came or went with no warehouse on the other side.
      jsonb_build_object('account_id', v_doc.difference_account, 'amount', -(v_out + v_in), 'cost_center_id', v_doc.cost_center)
    );
  end loop;

  if v_rows = 0 then
    raise exception 'no_rows' using errcode = '23514', detail = 'A stock entry needs at least one item.';
  end if;

  if v_perpetual then
    perform private.post_gl(v_doc.merchant_id, 'Stock Entry', p_id, v_doc.name, v_doc.posting_date, v_gl);
  end if;
end;
$$;

revoke execute on function private.submit_stock_entries(uuid) from public, anon, authenticated, service_role;


-- 6. A new item's Opening Stock (docs.frappe.io/erpnext/item 2.2; POS-System-Added-Features 13.2 and 16.1):
-- public.save_item(), then an Opening Stock reconciliation of that quantity in the item's Default Warehouse,
-- else Stock Settings', submitted in the same transaction. "Valuation Rate is mandatory if Opening Stock
-- entered"; ERPNext falls back to the Standard Selling Rate, and so does this. Read on creation only, and
-- only for an item that maintains stock.
--
-- Security invoker: the creator needs Stock Reconciliation create and submit, as the Standard Selling Rate
-- needs Item Price create. A wrapper rather than a third copy of save_item's body.
create or replace function public.save_item_with_opening_stock(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_new boolean := nullif(payload ->> 'id', '') is null;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_opening numeric := nullif(payload ->> 'opening_stock', '')::numeric;
  v_rate numeric := coalesce(nullif(payload ->> 'valuation_rate', '')::numeric, nullif(payload ->> 'standard_rate', '')::numeric);
  v_id uuid;
  v_warehouse uuid;
  v_reconciliation uuid;
begin
  v_id := public.save_item(payload);

  if not v_new or coalesce(v_opening, 0) <= 0 or not coalesce((payload ->> 'is_stock_item')::boolean, true) then
    return v_id;
  end if;

  if coalesce(v_rate, 0) <= 0 then
    raise exception 'valuation_rate_required' using errcode = '23514', detail = 'Valuation Rate is mandatory if Opening Stock is entered.';
  end if;

  v_warehouse := coalesce(
    nullif(payload ->> 'default_warehouse', '')::uuid,
    (select s.default_warehouse from public.stock_settings s where s.merchant_id = v_merchant)
  );
  if v_warehouse is null then
    raise exception 'no_default_warehouse' using errcode = '23514',
      detail = 'Neither the item nor Stock Settings names a warehouse for the opening stock.';
  end if;

  v_reconciliation := public.save_stock_reconciliation(jsonb_build_object(
    'merchant_id', v_merchant,
    'purpose', 'Opening Stock',
    'items', jsonb_build_array(jsonb_build_object(
      'item_id', v_id, 'warehouse_id', v_warehouse, 'qty', v_opening, 'valuation_rate', v_rate
    ))
  ));
  perform public.submit_document('Stock Reconciliation', v_reconciliation);

  return v_id;
end;
$$;

revoke execute on function public.save_item_with_opening_stock(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item_with_opening_stock(jsonb) to authenticated;


-- 7. Doctypes, permissions, policies (20261008145056_users_and_access.sql, 20261011165554_ledgers.sql).
-- ERPNext gives Stock Reconciliation to the Stock Manager alone; a Stock User keeps and submits Stock
-- Entries, and only the Stock Manager cancels or deletes one.

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('Stock Reconciliation', 'stock_reconciliations', 'document', false),
  ('Stock Entry', 'stock_entries', 'document', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete, can_submit, can_cancel)
values
  ('Stock Manager', 'Stock Reconciliation', true, true, true, true, true, true, true),
  ('Stock Manager', 'Stock Entry', true, true, true, true, true, true, true),
  ('Stock User', 'Stock Entry', true, true, true, true, false, true, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('stock_reconciliations', 'Stock Reconciliation');
select private.apply_doctype_policies('stock_reconciliation_items', 'Stock Reconciliation', true);
select private.apply_doctype_policies('stock_entries', 'Stock Entry');
select private.apply_doctype_policies('stock_entry_items', 'Stock Entry', true);


-- ===== 20261011233916_pos_profiles.sql =====

-- Step 17 of the POS batch, on ERPNext's model: the POS Profile — one register's settings
-- (.claude/erpnext-docs/POS-System-Added-Features.md 17.1–17.3; docs.frappe.io/erpnext/pos-profile).
--
-- 1. pos_profiles: the warehouse a register sells from, its price list, taxes and charges, tax category,
--    print format and letter head (17.1); the accounts that win over an item's and the Company's (17.2);
--    the four switches of the Configurations section (17.3).
-- 2. pos_profile_users: Applicable for Users — with one listed, nobody else may use the profile; a member's
--    default profile. pos_profile_payments: the modes offered at checkout, the default one, Allow in Returns.
--    pos_profile_item_groups: the item groups the register lists.
-- 3. private.validate_pos_profile(): each link an enabled record of the kind its field takes.
--    private.validate_pos_profile_payments(): at least one payment method, exactly one default, each mode
--    enabled with a default account — deferred, so a save that replaces the rows is checked once.
-- 4. public.save_pos_profile(): the profile and its three child tables in one transaction.
-- 5. The doctype, its permissions and policies. No seed: ERPNext makes no POS Profile.
--
-- Out of scope, so absent: Company and Currency (a system is one company in one currency), Customer and
-- Customer Group, Print Heading and Terms, Hide Images, Automatically Add Filtered Item To Cart, Validate
-- Stock on Save, Allow Partial Payment, Action on New Invoice. Apply Discount On, Allow User to Edit Discount,
-- Ignore Pricing Rule and the Discount Account arrive with Step 20. Re-runnable, like the rest of
-- supabase/migrations.

create schema if not exists private;


-- 1. The profile. Every link is a composite foreign key, NO ACTION: deleting a record a profile still names
-- fails with 23503 ("in use"), and deleting a system takes its profiles in one statement.

create table if not exists public.pos_profiles (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_profile_name text not null,
  disabled boolean not null default false,
  -- "If both Item and POS Profile define a Warehouse, the POS profile warehouse gets priority."
  warehouse uuid not null,
  -- Empty: Selling Settings' Default Price List.
  selling_price_list uuid,
  -- Empty: a Tax Rule, else the default template, decides.
  taxes_and_charges uuid,
  tax_category uuid,
  -- Empty: the default print format, and the default letter head.
  print_format uuid,
  letter_head uuid,
  -- 17.2. Empty: the item's, its group's, its brand's, then the Company's.
  account_for_change_amount uuid,
  write_off_account uuid,
  write_off_cost_center uuid,
  -- The biggest shortfall a sale may leave unpaid and written off.
  write_off_limit numeric not null default 0,
  income_account uuid,
  expense_account uuid,
  cost_center uuid,
  -- 17.3.
  hide_unavailable_items boolean not null default false,
  allow_rate_change boolean not null default false,
  set_grand_total_to_default_mop boolean not null default true,
  print_receipt_on_order_complete boolean not null default false,
  created_at timestamptz not null default now(),

  constraint pos_profiles_id_merchant unique (id, merchant_id),
  constraint pos_profiles_name_unique unique (merchant_id, pos_profile_name),
  constraint pos_profiles_name_length check (length(btrim(pos_profile_name)) between 1 and 140),
  constraint pos_profiles_write_off_limit check (write_off_limit >= 0),
  constraint pos_profiles_warehouse_fk foreign key (warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint pos_profiles_price_list_fk foreign key (selling_price_list, merchant_id) references public.price_lists (id, merchant_id),
  constraint pos_profiles_template_fk foreign key (taxes_and_charges, merchant_id) references public.sales_tax_templates (id, merchant_id),
  constraint pos_profiles_tax_category_fk foreign key (tax_category, merchant_id) references public.tax_categories (id, merchant_id),
  constraint pos_profiles_print_format_fk foreign key (print_format, merchant_id) references public.print_formats (id, merchant_id),
  constraint pos_profiles_letter_head_fk foreign key (letter_head, merchant_id) references public.letter_heads (id, merchant_id),
  constraint pos_profiles_change_account_fk foreign key (account_for_change_amount, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_profiles_write_off_account_fk foreign key (write_off_account, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_profiles_write_off_cost_center_fk foreign key (write_off_cost_center, merchant_id) references public.cost_centers (id, merchant_id),
  constraint pos_profiles_income_account_fk foreign key (income_account, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_profiles_expense_account_fk foreign key (expense_account, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_profiles_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.pos_profiles enable row level security;
create index if not exists pos_profiles_warehouse_idx on public.pos_profiles (warehouse, merchant_id);
create index if not exists pos_profiles_price_list_idx on public.pos_profiles (selling_price_list, merchant_id);
create index if not exists pos_profiles_template_idx on public.pos_profiles (taxes_and_charges, merchant_id);
create index if not exists pos_profiles_tax_category_idx on public.pos_profiles (tax_category, merchant_id);
create index if not exists pos_profiles_print_format_idx on public.pos_profiles (print_format, merchant_id);
create index if not exists pos_profiles_letter_head_idx on public.pos_profiles (letter_head, merchant_id);
create index if not exists pos_profiles_change_account_idx on public.pos_profiles (account_for_change_amount, merchant_id);
create index if not exists pos_profiles_write_off_account_idx on public.pos_profiles (write_off_account, merchant_id);
create index if not exists pos_profiles_write_off_cost_center_idx on public.pos_profiles (write_off_cost_center, merchant_id);
create index if not exists pos_profiles_income_account_idx on public.pos_profiles (income_account, merchant_id);
create index if not exists pos_profiles_expense_account_idx on public.pos_profiles (expense_account, merchant_id);
create index if not exists pos_profiles_cost_center_idx on public.pos_profiles (cost_center, merchant_id);


-- 2. Its child tables. Each goes with its profile; the rows are replaced as a set, idx their order.

-- "Once even one User is set in the POS Profile, other Users cannot use this POS Profile." A member's row
-- goes with the member. The owner is no member row and may use every profile.
create table if not exists public.pos_profile_users (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_profile_id uuid not null,
  idx integer not null,
  member_id uuid not null,
  is_default boolean not null default false,

  constraint pos_profile_users_unique unique (pos_profile_id, member_id),
  constraint pos_profile_users_profile_fk foreign key (pos_profile_id, merchant_id) references public.pos_profiles (id, merchant_id) on delete cascade,
  constraint pos_profile_users_member_fk foreign key (member_id, merchant_id) references public.merchant_members (id, merchant_id) on delete cascade
);

alter table public.pos_profile_users enable row level security;
create index if not exists pos_profile_users_member_idx on public.pos_profile_users (member_id, merchant_id);
-- ERPNext's "Already set default in pos profile … for user …": one default profile per member (23505).
create unique index if not exists pos_profile_users_one_default on public.pos_profile_users (member_id) where is_default;

create table if not exists public.pos_profile_payments (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_profile_id uuid not null,
  idx integer not null,
  mode_of_payment_id uuid not null,
  is_default boolean not null default false,
  allow_in_returns boolean not null default false,

  constraint pos_profile_payments_unique unique (pos_profile_id, mode_of_payment_id),
  constraint pos_profile_payments_profile_fk foreign key (pos_profile_id, merchant_id) references public.pos_profiles (id, merchant_id) on delete cascade,
  -- Deleting a mode of payment a profile offers fails with 23503 ("in use").
  constraint pos_profile_payments_mode_fk foreign key (mode_of_payment_id, merchant_id) references public.modes_of_payment (id, merchant_id)
);

alter table public.pos_profile_payments enable row level security;
create index if not exists pos_profile_payments_mode_idx on public.pos_profile_payments (mode_of_payment_id, merchant_id);

create table if not exists public.pos_profile_item_groups (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_profile_id uuid not null,
  idx integer not null,
  item_group_id uuid not null,

  constraint pos_profile_item_groups_unique unique (pos_profile_id, item_group_id),
  constraint pos_profile_item_groups_profile_fk foreign key (pos_profile_id, merchant_id) references public.pos_profiles (id, merchant_id) on delete cascade,
  constraint pos_profile_item_groups_group_fk foreign key (item_group_id, merchant_id) references public.item_groups (id, merchant_id)
);

alter table public.pos_profile_item_groups enable row level security;
create index if not exists pos_profile_item_groups_group_idx on public.pos_profile_item_groups (item_group_id, merchant_id);


-- 3. The checks. Only a changed link is checked, as private.validate_defaults does: a record disabled later
-- does not block the profile's other edits. Security definer for that function's reason — a User Permission
-- must not hide the record from the check.

create or replace function private.validate_pos_profile()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_column text;
  v_id uuid;
  v_ok boolean;
begin
  foreach v_column in array array[
    'warehouse', 'selling_price_list', 'taxes_and_charges', 'tax_category', 'print_format', 'letter_head',
    'account_for_change_amount', 'write_off_account', 'write_off_cost_center', 'income_account', 'expense_account', 'cost_center'
  ] loop
    v_id := (v_new ->> v_column)::uuid;
    continue when v_id is null or (v_new ->> v_column) is not distinct from (v_old ->> v_column);

    v_ok := case v_column
      when 'warehouse' then
        (select not w.is_group and not w.disabled from public.warehouses w where w.id = v_id and w.merchant_id = new.merchant_id)
      when 'selling_price_list' then
        (select p.enabled from public.price_lists p where p.id = v_id and p.merchant_id = new.merchant_id)
      when 'taxes_and_charges' then
        (select not t.disabled from public.sales_tax_templates t where t.id = v_id and t.merchant_id = new.merchant_id)
      when 'tax_category' then
        (select not c.disabled from public.tax_categories c where c.id = v_id and c.merchant_id = new.merchant_id)
      when 'print_format' then
        (select not f.disabled from public.print_formats f where f.id = v_id and f.merchant_id = new.merchant_id)
      when 'letter_head' then
        (select not h.disabled from public.letter_heads h where h.id = v_id and h.merchant_id = new.merchant_id)
      -- Change is handed back out of a cash or bank ledger.
      when 'account_for_change_amount' then
        (select not a.is_group and not a.disabled and a.account_type in ('Cash', 'Bank')
         from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      when 'income_account' then
        (select not a.is_group and not a.disabled and a.root_type = 'Income' from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      when 'write_off_account' then
        (select not a.is_group and not a.disabled and a.root_type = 'Expense' from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      when 'expense_account' then
        (select not a.is_group and not a.disabled and a.root_type = 'Expense' from public.accounts a where a.id = v_id and a.merchant_id = new.merchant_id)
      else
        (select not c.is_group and not c.disabled from public.cost_centers c where c.id = v_id and c.merchant_id = new.merchant_id)
    end;

    if not coalesce(v_ok, false) then
      raise exception 'default_invalid' using errcode = '23514', detail = format('%s cannot name that record.', v_column);
    end if;
  end loop;

  return new;
end;
$$;

revoke execute on function private.validate_pos_profile() from public, anon, authenticated, service_role;

drop trigger if exists pos_profiles_validate on public.pos_profiles;
create trigger pos_profiles_validate
  before insert or update on public.pos_profiles
  for each row execute function private.validate_pos_profile();

-- The rules that read the profile's payment rows together ("Only the modes set here will be available when
-- using POS … set one of them as the default"). A deferred constraint trigger on the profile and on its
-- rows, as private.validate_tax_row_references: a save that replaces every row is checked at commit.
create or replace function private.validate_pos_profile_payments()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Through to_jsonb: the profile's own row has no pos_profile_id, and plpgsql resolves every field it reads.
  v_profile uuid := coalesce(to_jsonb(new) ->> 'pos_profile_id', to_jsonb(old) ->> 'pos_profile_id', to_jsonb(new) ->> 'id')::uuid;
  v_rows integer;
  v_defaults integer;
begin
  -- Deleted with its rows: nothing left to hold.
  if not exists (select 1 from public.pos_profiles p where p.id = v_profile) then
    return null;
  end if;

  select count(*), count(*) filter (where r.is_default) into v_rows, v_defaults
  from public.pos_profile_payments r where r.pos_profile_id = v_profile;

  if v_rows = 0 then
    raise exception 'payment_method_required' using errcode = '23514', detail = 'A POS Profile needs at least one payment method.';
  end if;
  if v_defaults <> 1 then
    raise exception 'payment_default_required' using errcode = '23514', detail = 'Exactly one payment method is the default.';
  end if;

  -- ERPNext's "Please set default Cash or Bank account in Mode of Payment".
  if exists (
    select 1 from public.pos_profile_payments r
    join public.modes_of_payment m on m.id = r.mode_of_payment_id
    where r.pos_profile_id = v_profile and (not m.enabled or m.default_account is null)
  ) then
    raise exception 'payment_mode_unusable' using errcode = '23514',
      detail = 'Each payment method is an enabled Mode of Payment with a default account.';
  end if;

  return null;
end;
$$;

revoke execute on function private.validate_pos_profile_payments() from public, anon, authenticated, service_role;

drop trigger if exists pos_profiles_validate_payments on public.pos_profiles;
create constraint trigger pos_profiles_validate_payments
  after insert on public.pos_profiles
  deferrable initially deferred
  for each row execute function private.validate_pos_profile_payments();

drop trigger if exists pos_profile_payments_validate on public.pos_profile_payments;
create constraint trigger pos_profile_payments_validate
  after insert or update or delete on public.pos_profile_payments
  deferrable initially deferred
  for each row execute function private.validate_pos_profile_payments();


-- 4. Saving a profile with its rows. Security invoker, like public.save_item_group: the caller's own policies
-- decide every row.

create or replace function public.save_pos_profile(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_row public.pos_profiles;
begin
  v_row := jsonb_populate_record(null::public.pos_profiles, jsonb_strip_nulls(jsonb_build_object(
    'pos_profile_name', btrim(payload ->> 'pos_profile_name'),
    'disabled', coalesce((payload ->> 'disabled')::boolean, false),
    'warehouse', nullif(payload ->> 'warehouse', ''),
    'selling_price_list', nullif(payload ->> 'selling_price_list', ''),
    'taxes_and_charges', nullif(payload ->> 'taxes_and_charges', ''),
    'tax_category', nullif(payload ->> 'tax_category', ''),
    'print_format', nullif(payload ->> 'print_format', ''),
    'letter_head', nullif(payload ->> 'letter_head', ''),
    'account_for_change_amount', nullif(payload ->> 'account_for_change_amount', ''),
    'write_off_account', nullif(payload ->> 'write_off_account', ''),
    'write_off_cost_center', nullif(payload ->> 'write_off_cost_center', ''),
    'write_off_limit', coalesce(nullif(payload ->> 'write_off_limit', '')::numeric, 0),
    'income_account', nullif(payload ->> 'income_account', ''),
    'expense_account', nullif(payload ->> 'expense_account', ''),
    'cost_center', nullif(payload ->> 'cost_center', ''),
    'hide_unavailable_items', coalesce((payload ->> 'hide_unavailable_items')::boolean, false),
    'allow_rate_change', coalesce((payload ->> 'allow_rate_change')::boolean, false),
    'set_grand_total_to_default_mop', coalesce((payload ->> 'set_grand_total_to_default_mop')::boolean, true),
    'print_receipt_on_order_complete', coalesce((payload ->> 'print_receipt_on_order_complete')::boolean, false)
  )));

  if v_id is null then
    insert into public.pos_profiles (
      merchant_id, pos_profile_name, disabled, warehouse, selling_price_list, taxes_and_charges, tax_category, print_format,
      letter_head, account_for_change_amount, write_off_account, write_off_cost_center, write_off_limit, income_account,
      expense_account, cost_center, hide_unavailable_items, allow_rate_change, set_grand_total_to_default_mop,
      print_receipt_on_order_complete
    )
    values (
      v_merchant, v_row.pos_profile_name, v_row.disabled, v_row.warehouse, v_row.selling_price_list, v_row.taxes_and_charges,
      v_row.tax_category, v_row.print_format, v_row.letter_head, v_row.account_for_change_amount, v_row.write_off_account,
      v_row.write_off_cost_center, v_row.write_off_limit, v_row.income_account, v_row.expense_account, v_row.cost_center,
      v_row.hide_unavailable_items, v_row.allow_rate_change, v_row.set_grand_total_to_default_mop,
      v_row.print_receipt_on_order_complete
    )
    returning id into v_id;
  else
    update public.pos_profiles set
      pos_profile_name = v_row.pos_profile_name,
      disabled = v_row.disabled,
      warehouse = v_row.warehouse,
      selling_price_list = v_row.selling_price_list,
      taxes_and_charges = v_row.taxes_and_charges,
      tax_category = v_row.tax_category,
      print_format = v_row.print_format,
      letter_head = v_row.letter_head,
      account_for_change_amount = v_row.account_for_change_amount,
      write_off_account = v_row.write_off_account,
      write_off_cost_center = v_row.write_off_cost_center,
      write_off_limit = v_row.write_off_limit,
      income_account = v_row.income_account,
      expense_account = v_row.expense_account,
      cost_center = v_row.cost_center,
      hide_unavailable_items = v_row.hide_unavailable_items,
      allow_rate_change = v_row.allow_rate_change,
      set_grand_total_to_default_mop = v_row.set_grand_total_to_default_mop,
      print_receipt_on_order_complete = v_row.print_receipt_on_order_complete
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'pos_profile_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.pos_profile_users where pos_profile_id = v_id;
  insert into public.pos_profile_users (merchant_id, pos_profile_id, idx, member_id, is_default)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'member_id')::uuid, coalesce((r.value ->> 'is_default')::boolean, false)
  from jsonb_array_elements(coalesce(payload -> 'users', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.pos_profile_payments where pos_profile_id = v_id;
  insert into public.pos_profile_payments (merchant_id, pos_profile_id, idx, mode_of_payment_id, is_default, allow_in_returns)
  select
    v_merchant, v_id, r.idx::integer, (r.value ->> 'mode_of_payment_id')::uuid,
    coalesce((r.value ->> 'is_default')::boolean, false), coalesce((r.value ->> 'allow_in_returns')::boolean, false)
  from jsonb_array_elements(coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.pos_profile_item_groups where pos_profile_id = v_id;
  insert into public.pos_profile_item_groups (merchant_id, pos_profile_id, idx, item_group_id)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'item_group_id')::uuid
  from jsonb_array_elements(coalesce(payload -> 'item_groups', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_pos_profile(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_pos_profile(jsonb) to authenticated;


-- 5. Doctype, permissions, policies (supabase/migrations/20261008145056_users_and_access.sql). ERPNext's
-- matrix: Sales Manager and Accounts Manager keep it; a cashier (Sales User) reads the register's settings.

insert into public.doctypes (name, table_name, kind, restrictable)
values ('POS Profile', 'pos_profiles', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Sales Manager', 'POS Profile', true, true, true, true, true),
  ('Accounts Manager', 'POS Profile', true, true, true, true, true),
  ('Sales User', 'POS Profile', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('pos_profiles', 'POS Profile');
select private.apply_doctype_policies('pos_profile_users', 'POS Profile', true);
select private.apply_doctype_policies('pos_profile_payments', 'POS Profile', true);
select private.apply_doctype_policies('pos_profile_item_groups', 'POS Profile', true);


-- ===== 20261012004616_pos_shift_and_sale.sql =====

-- Step 18 of the POS batch, on ERPNext's model: the cashier's shift and the sale
-- (.claude/erpnext-docs/POS-System-Added-Features.md 18.1–18.5; docs.frappe.io/erpnext/pos-workflows,
-- /point-of-sale, /sales-invoice).
--
-- 1. Naming: POS Opening Entry and POS Closing Entry join Document Naming Settings.
-- 2. pos_opening_entries (+ balances): a cashier's session on a POS Profile, with the opening amount per
--    mode of payment. One open session per cashier and profile.
-- 3. pos_invoices (+ items, taxes, payments): the submitted sale.
-- 4. pos_closing_entries (+ payments): the end of the session — per mode the opening, expected and counted
--    amount and the difference.
-- 5. The posters public.submit_document() dispatches to: private.submit_pos_opening_entries(),
--    submit_pos_invoices(), submit_pos_closing_entries().
-- 6. public.open_pos_session(), pos_checkout(), close_pos_session(): security invoker — the caller's own
--    policies decide every row, then the document is submitted in the same transaction.
-- 7. Doctypes, permissions, policies.
--
-- The app calculates, the database checks (the human's decision, 2026-10-11): the cart's prices, taxes and
-- totals come from the app's one engine (src/features/pos-invoices/cart.ts), and the poster refuses what it
-- can check without a second one — the session, the items and their units, each line's amount, that the
-- totals add up, what was paid — then posts what only it knows: the name, the valuation, Cost of Goods Sold
-- and the ledger rows.
--
-- Out of scope, so absent: Customer, held (draft) sales, partial payment, loyalty, POS Invoice
-- Consolidation — every sale posts at once. Returns and voids are Step 19, discounts Step 20. Re-runnable,
-- like the rest of supabase/migrations.

create schema if not exists private;


-- 1. Naming series (20261010064803_naming_series.sql). ERPNext ships POS-OPE-.YYYY.- and POS-CLE-.YYYY.-;
-- the POS Invoice has had ACC-PSINV-.YYYY.- since that migration.

alter table public.naming_series drop constraint if exists naming_series_document_type;
alter table public.naming_series add constraint naming_series_document_type
  check (document_type in (
    'POS Invoice', 'Sales Invoice', 'Item', 'Stock Reconciliation', 'Stock Entry', 'POS Opening Entry', 'POS Closing Entry'
  ));

-- merchants_seed_94_naming calls this for every new system.
create or replace function private.seed_naming_for(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  insert into public.naming_series (merchant_id, document_type, options)
  values
    (p_merchant, 'POS Invoice', array['ACC-PSINV-.YYYY.-']),
    (p_merchant, 'Sales Invoice', array['ACC-SINV-.YYYY.-']),
    (p_merchant, 'Item', array['STO-ITEM-.YYYY.-']),
    (p_merchant, 'Stock Reconciliation', array['MAT-RECO-.YYYY.-']),
    (p_merchant, 'Stock Entry', array['MAT-STE-.YYYY.-']),
    (p_merchant, 'POS Opening Entry', array['POS-OPE-.YYYY.-']),
    (p_merchant, 'POS Closing Entry', array['POS-CLE-.YYYY.-'])
  on conflict (merchant_id, document_type) do nothing;
$$;

-- The systems that already exist.
select private.seed_naming_for(m.id) from public.merchants m;


-- 2. POS Opening Entry (18.1): "Before selling, open a session with an Opening Entry. This sets the session
-- start and can capture opening cash." user_id is the cashier — no foreign key to auth.users, so deleting an
-- account neither fails on its sessions nor takes a shop's records with it.

create table if not exists public.pos_opening_entries (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  posting_date date not null,
  pos_profile_id uuid not null,
  user_id uuid not null default auth.uid(),
  period_start timestamptz not null default now(),
  -- Open until its POS Closing Entry is submitted.
  status text not null default 'Open',
  docstatus smallint not null default 0,
  created_at timestamptz not null default now(),

  constraint pos_opening_entries_id_merchant unique (id, merchant_id),
  constraint pos_opening_entries_name_unique unique (merchant_id, name),
  constraint pos_opening_entries_status check (status in ('Open', 'Closed')),
  constraint pos_opening_entries_docstatus check (docstatus in (0, 1, 2)),
  constraint pos_opening_entries_profile_fk foreign key (pos_profile_id, merchant_id) references public.pos_profiles (id, merchant_id)
);

alter table public.pos_opening_entries enable row level security;
create index if not exists pos_opening_entries_profile_idx on public.pos_opening_entries (pos_profile_id, merchant_id);
create index if not exists pos_opening_entries_user_idx on public.pos_opening_entries (user_id);
-- "One open session per cashier and profile": a second one fails with 23505.
create unique index if not exists pos_opening_entries_one_open
  on public.pos_opening_entries (pos_profile_id, user_id) where docstatus = 1 and status = 'Open';

drop trigger if exists pos_opening_entries_name on public.pos_opening_entries;
create trigger pos_opening_entries_name
  before insert on public.pos_opening_entries
  for each row execute function private.name_document('POS Opening Entry');

create table if not exists public.pos_opening_entry_balances (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_opening_entry_id uuid not null,
  idx integer not null,
  mode_of_payment_id uuid not null,
  opening_amount numeric not null default 0,

  constraint pos_opening_entry_balances_unique unique (pos_opening_entry_id, mode_of_payment_id),
  constraint pos_opening_entry_balances_amount check (opening_amount >= 0),
  constraint pos_opening_entry_balances_parent_fk foreign key (pos_opening_entry_id, merchant_id)
    references public.pos_opening_entries (id, merchant_id) on delete cascade,
  constraint pos_opening_entry_balances_mode_fk foreign key (mode_of_payment_id, merchant_id) references public.modes_of_payment (id, merchant_id)
);

alter table public.pos_opening_entry_balances enable row level security;
create index if not exists pos_opening_entry_balances_mode_idx on public.pos_opening_entry_balances (mode_of_payment_id, merchant_id);


-- 3. POS Invoice (18.3). The app sends what it calculated; the poster fills what only the database knows —
-- the date, the warehouse, the price list and tax category of the profile, and on each line its name as
-- sold, the accounts it posted to and the valuation it left at.

create table if not exists public.pos_invoices (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  posting_date date not null,
  pos_profile_id uuid not null,
  pos_opening_entry_id uuid not null,
  user_id uuid not null default auth.uid(),
  warehouse uuid,
  selling_price_list uuid,
  -- The Sales Taxes and Charges Template the cart applied; its rows as applied are pos_invoice_taxes.
  taxes_and_charges uuid,
  tax_category uuid,
  net_total numeric not null default 0,
  total_taxes_and_charges numeric not null default 0,
  grand_total numeric not null default 0,
  -- Rounded Total less Grand Total (Global Defaults: Disable Rounded Total leaves it 0).
  rounding_adjustment numeric not null default 0,
  rounded_total numeric not null default 0,
  paid_amount numeric not null default 0,
  change_amount numeric not null default 0,
  write_off_amount numeric not null default 0,
  docstatus smallint not null default 0,
  created_at timestamptz not null default now(),

  constraint pos_invoices_id_merchant unique (id, merchant_id),
  constraint pos_invoices_name_unique unique (merchant_id, name),
  constraint pos_invoices_docstatus check (docstatus in (0, 1, 2)),
  constraint pos_invoices_profile_fk foreign key (pos_profile_id, merchant_id) references public.pos_profiles (id, merchant_id),
  constraint pos_invoices_session_fk foreign key (pos_opening_entry_id, merchant_id) references public.pos_opening_entries (id, merchant_id),
  constraint pos_invoices_warehouse_fk foreign key (warehouse, merchant_id) references public.warehouses (id, merchant_id),
  constraint pos_invoices_price_list_fk foreign key (selling_price_list, merchant_id) references public.price_lists (id, merchant_id),
  constraint pos_invoices_template_fk foreign key (taxes_and_charges, merchant_id) references public.sales_tax_templates (id, merchant_id),
  constraint pos_invoices_tax_category_fk foreign key (tax_category, merchant_id) references public.tax_categories (id, merchant_id)
);

alter table public.pos_invoices enable row level security;
create index if not exists pos_invoices_profile_idx on public.pos_invoices (pos_profile_id, merchant_id);
create index if not exists pos_invoices_session_idx on public.pos_invoices (pos_opening_entry_id, merchant_id);
create index if not exists pos_invoices_warehouse_idx on public.pos_invoices (warehouse, merchant_id);
create index if not exists pos_invoices_price_list_idx on public.pos_invoices (selling_price_list, merchant_id);
create index if not exists pos_invoices_template_idx on public.pos_invoices (taxes_and_charges, merchant_id);
create index if not exists pos_invoices_tax_category_idx on public.pos_invoices (tax_category, merchant_id);
-- Orders and the dashboard read the newest first.
create index if not exists pos_invoices_date_idx on public.pos_invoices (merchant_id, posting_date desc, created_at desc);

drop trigger if exists pos_invoices_name on public.pos_invoices;
create trigger pos_invoices_name
  before insert on public.pos_invoices
  for each row execute function private.name_document('POS Invoice');

create table if not exists public.pos_invoice_items (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_invoice_id uuid not null,
  idx integer not null,
  item_id uuid not null,
  -- The item's name on the day it was sold, written on submit: a receipt reopened later prints it.
  item_name text,
  qty numeric not null,
  uom_id uuid not null,
  -- Stock units in one of the unit sold in; stock_qty is what leaves the warehouse.
  conversion_factor numeric not null default 1,
  stock_qty numeric not null,
  price_list_rate numeric not null default 0,
  -- As entered: tax-inclusive when an inclusive tax row applies. net_rate and net_amount leave that tax out.
  rate numeric not null,
  amount numeric not null,
  net_rate numeric not null,
  net_amount numeric not null,
  item_tax_template_id uuid,
  -- Written on submit: where the line posted, and the valuation per stock unit it left at.
  income_account uuid,
  expense_account uuid,
  cost_center uuid,
  valuation_rate numeric,

  constraint pos_invoice_items_qty check (qty > 0 and stock_qty > 0 and conversion_factor > 0),
  constraint pos_invoice_items_rate check (rate >= 0 and price_list_rate >= 0),
  constraint pos_invoice_items_parent_fk foreign key (pos_invoice_id, merchant_id) references public.pos_invoices (id, merchant_id) on delete cascade,
  constraint pos_invoice_items_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id),
  constraint pos_invoice_items_uom_fk foreign key (uom_id, merchant_id) references public.uoms (id, merchant_id),
  constraint pos_invoice_items_template_fk foreign key (item_tax_template_id, merchant_id) references public.item_tax_templates (id, merchant_id),
  constraint pos_invoice_items_income_fk foreign key (income_account, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_invoice_items_expense_fk foreign key (expense_account, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_invoice_items_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.pos_invoice_items enable row level security;
create index if not exists pos_invoice_items_parent_idx on public.pos_invoice_items (pos_invoice_id, merchant_id);
create index if not exists pos_invoice_items_item_idx on public.pos_invoice_items (item_id, merchant_id);
create index if not exists pos_invoice_items_uom_idx on public.pos_invoice_items (uom_id, merchant_id);
create index if not exists pos_invoice_items_template_idx on public.pos_invoice_items (item_tax_template_id, merchant_id);
create index if not exists pos_invoice_items_income_idx on public.pos_invoice_items (income_account, merchant_id);
create index if not exists pos_invoice_items_expense_idx on public.pos_invoice_items (expense_account, merchant_id);
create index if not exists pos_invoice_items_cost_center_idx on public.pos_invoice_items (cost_center, merchant_id);

-- The tax rows as the sale applied them: a template edited afterwards changes no receipt.
create table if not exists public.pos_invoice_taxes (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_invoice_id uuid not null,
  idx integer not null,
  charge_type text not null,
  account_head uuid not null,
  description text not null,
  rate numeric not null default 0,
  row_id integer,
  included_in_print_rate boolean not null default false,
  cost_center uuid,
  tax_amount numeric not null default 0,
  -- The running total after this row.
  total numeric not null default 0,

  constraint pos_invoice_taxes_charge_type
    check (charge_type in ('On Net Total', 'Actual', 'On Previous Row Amount', 'On Previous Row Total', 'On Item Quantity')),
  constraint pos_invoice_taxes_parent_fk foreign key (pos_invoice_id, merchant_id) references public.pos_invoices (id, merchant_id) on delete cascade,
  constraint pos_invoice_taxes_account_fk foreign key (account_head, merchant_id) references public.accounts (id, merchant_id),
  constraint pos_invoice_taxes_cost_center_fk foreign key (cost_center, merchant_id) references public.cost_centers (id, merchant_id)
);

alter table public.pos_invoice_taxes enable row level security;
create index if not exists pos_invoice_taxes_parent_idx on public.pos_invoice_taxes (pos_invoice_id, merchant_id);
create index if not exists pos_invoice_taxes_account_idx on public.pos_invoice_taxes (account_head, merchant_id);
create index if not exists pos_invoice_taxes_cost_center_idx on public.pos_invoice_taxes (cost_center, merchant_id);

-- What the customer handed over, per mode; the change is the invoice's change_amount.
create table if not exists public.pos_invoice_payments (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_invoice_id uuid not null,
  idx integer not null,
  mode_of_payment_id uuid not null,
  amount numeric not null,
  -- Written on submit: the mode's account that day.
  account uuid,

  constraint pos_invoice_payments_amount check (amount > 0),
  constraint pos_invoice_payments_parent_fk foreign key (pos_invoice_id, merchant_id) references public.pos_invoices (id, merchant_id) on delete cascade,
  constraint pos_invoice_payments_mode_fk foreign key (mode_of_payment_id, merchant_id) references public.modes_of_payment (id, merchant_id),
  constraint pos_invoice_payments_account_fk foreign key (account, merchant_id) references public.accounts (id, merchant_id)
);

alter table public.pos_invoice_payments enable row level security;
create index if not exists pos_invoice_payments_parent_idx on public.pos_invoice_payments (pos_invoice_id, merchant_id);
create index if not exists pos_invoice_payments_mode_idx on public.pos_invoice_payments (mode_of_payment_id, merchant_id);
create index if not exists pos_invoice_payments_account_idx on public.pos_invoice_payments (account, merchant_id);


-- 4. POS Closing Entry (18.5). The session's invoices are read through pos_invoices.pos_opening_entry_id,
-- not copied into a child table.

create table if not exists public.pos_closing_entries (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  name text not null,
  posting_date date not null,
  pos_opening_entry_id uuid not null,
  -- Who closed it: the cashier, or a manager closing a session left open.
  user_id uuid not null default auth.uid(),
  period_end timestamptz not null default now(),
  -- Written on submit, from the session's submitted invoices.
  grand_total numeric not null default 0,
  net_total numeric not null default 0,
  total_quantity numeric not null default 0,
  docstatus smallint not null default 0,
  created_at timestamptz not null default now(),

  constraint pos_closing_entries_id_merchant unique (id, merchant_id),
  constraint pos_closing_entries_name_unique unique (merchant_id, name),
  constraint pos_closing_entries_docstatus check (docstatus in (0, 1, 2)),
  constraint pos_closing_entries_session_fk foreign key (pos_opening_entry_id, merchant_id) references public.pos_opening_entries (id, merchant_id)
);

alter table public.pos_closing_entries enable row level security;
create index if not exists pos_closing_entries_session_idx on public.pos_closing_entries (pos_opening_entry_id, merchant_id);
-- A session is closed once.
create unique index if not exists pos_closing_entries_one_per_session on public.pos_closing_entries (pos_opening_entry_id) where docstatus = 1;

drop trigger if exists pos_closing_entries_name on public.pos_closing_entries;
create trigger pos_closing_entries_name
  before insert on public.pos_closing_entries
  for each row execute function private.name_document('POS Closing Entry');

create table if not exists public.pos_closing_entry_payments (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pos_closing_entry_id uuid not null,
  idx integer not null,
  mode_of_payment_id uuid not null,
  -- Counted by the cashier. The other three are written on submit.
  closing_amount numeric not null default 0,
  opening_amount numeric not null default 0,
  expected_amount numeric not null default 0,
  difference numeric not null default 0,

  constraint pos_closing_entry_payments_unique unique (pos_closing_entry_id, mode_of_payment_id),
  constraint pos_closing_entry_payments_amount check (closing_amount >= 0),
  constraint pos_closing_entry_payments_parent_fk foreign key (pos_closing_entry_id, merchant_id)
    references public.pos_closing_entries (id, merchant_id) on delete cascade,
  constraint pos_closing_entry_payments_mode_fk foreign key (mode_of_payment_id, merchant_id) references public.modes_of_payment (id, merchant_id)
);

alter table public.pos_closing_entry_payments enable row level security;
create index if not exists pos_closing_entry_payments_mode_idx on public.pos_closing_entry_payments (mode_of_payment_id, merchant_id);

-- A session is closed, not voided: public.cancel_document() would leave its sales without one.
create or replace function private.keep_pos_entry()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.docstatus = 2 then
    raise exception 'not_cancellable' using errcode = '23514', detail = 'A POS session is closed with a POS Closing Entry, not cancelled.';
  end if;
  return new;
end;
$$;

revoke execute on function private.keep_pos_entry() from public, anon, authenticated, service_role;

drop trigger if exists pos_opening_entries_keep on public.pos_opening_entries;
create trigger pos_opening_entries_keep
  before update of docstatus on public.pos_opening_entries
  for each row execute function private.keep_pos_entry();

drop trigger if exists pos_closing_entries_keep on public.pos_closing_entries;
create trigger pos_closing_entries_keep
  before update of docstatus on public.pos_closing_entries
  for each row execute function private.keep_pos_entry();


-- 5. The posters. Called only by public.submit_document(), which has checked the caller's Submit permission
-- and locked the draft. Security definer, search_path pinned, out of every role's reach; each still holds
-- the caller to their own session ((select auth.uid())).

-- "Once even one User is set in the POS Profile, other Users cannot use this POS Profile." The owner is the
-- Administrator and may use any.
create or replace function private.pos_profile_usable(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((
    select not p.disabled and (
      m.owner_id = (select auth.uid())
      or not exists (select 1 from public.pos_profile_users u where u.pos_profile_id = p.id)
      or exists (
        select 1 from public.pos_profile_users u
        join public.merchant_members mm on mm.id = u.member_id
        where u.pos_profile_id = p.id and mm.user_id = (select auth.uid()) and mm.enabled
      )
    )
    from public.pos_profiles p
    join public.merchants m on m.id = p.merchant_id
    where p.id = p_profile
  ), false);
$$;

revoke execute on function private.pos_profile_usable(uuid) from public, anon, authenticated, service_role;

create or replace function private.submit_pos_opening_entries(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.pos_opening_entries;
begin
  select * into v_doc from public.pos_opening_entries d where d.id = p_id;

  if v_doc.user_id is distinct from (select auth.uid()) then
    raise exception 'not_your_session' using errcode = '42501', detail = 'A session is opened by its own cashier.';
  end if;
  if not private.pos_profile_usable(v_doc.pos_profile_id) then
    raise exception 'pos_profile_unusable' using errcode = '23514', detail = 'The POS Profile is disabled, or not applicable for this user.';
  end if;

  if exists (
    select 1 from public.pos_opening_entry_balances b
    where b.pos_opening_entry_id = p_id and not exists (
      select 1 from public.pos_profile_payments pp
      where pp.pos_profile_id = v_doc.pos_profile_id and pp.mode_of_payment_id = b.mode_of_payment_id
    )
  ) then
    raise exception 'payment_method_not_offered' using errcode = '23514', detail = 'An opening amount names a mode of payment the POS Profile does not offer.';
  end if;

  -- The day the database posts by, whatever the device's clock says.
  update public.pos_opening_entries set posting_date = private.merchant_today(v_doc.merchant_id), period_start = now() where id = p_id;
end;
$$;

revoke execute on function private.submit_pos_opening_entries(uuid) from public, anon, authenticated, service_role;

-- The sale. ponytail: the tax amounts, each line's net amount and its Price List Rate are trusted from the
-- app — the invoice stores the template and its rows as applied, so a query can re-run them. Upgrade path:
-- port taxes_and_totals and the price lookup to SQL.
create or replace function private.submit_pos_invoices(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.pos_invoices;
  v_profile public.pos_profiles;
  v_company public.merchants;
  v_session public.pos_opening_entries;
  v_row record;
  v_today date;
  -- One unit of the currency's smallest decimal: what two roundings of the same figure may differ by.
  v_unit numeric;
  v_price_list uuid;
  v_auto_price boolean;
  v_inventory uuid;
  v_income uuid;
  v_expense uuid;
  v_center uuid;
  v_cost numeric;
  v_rows integer := 0;
  v_net numeric := 0;
  v_tax numeric := 0;
  v_paid numeric := 0;
  v_change numeric;
  v_write_off numeric;
  v_gl jsonb := '[]'::jsonb;
begin
  select * into v_doc from public.pos_invoices d where d.id = p_id;
  select * into v_profile from public.pos_profiles p where p.id = v_doc.pos_profile_id;
  select * into v_company from public.merchants m where m.id = v_doc.merchant_id;
  select * into v_session from public.pos_opening_entries s where s.id = v_doc.pos_opening_entry_id;
  v_today := private.merchant_today(v_doc.merchant_id);
  select 1 / power(10::numeric, coalesce(s.currency_precision, 2)) into v_unit from public.system_settings s where s.merchant_id = v_doc.merchant_id;
  v_unit := coalesce(v_unit, 0.01);

  -- "No sale without an open session": the caller's own, on this profile.
  if v_doc.user_id is distinct from (select auth.uid())
    or v_session.docstatus is distinct from 1 or v_session.status is distinct from 'Open'
    or v_session.user_id is distinct from (select auth.uid())
    or v_session.pos_profile_id is distinct from v_doc.pos_profile_id then
    raise exception 'no_open_session' using errcode = '23514', detail = 'A sale needs the cashier''s own open session on that POS Profile.';
  end if;
  if not private.pos_profile_usable(v_doc.pos_profile_id) then
    raise exception 'pos_profile_unusable' using errcode = '23514', detail = 'The POS Profile is disabled, or not applicable for this user.';
  end if;

  select coalesce(v_profile.selling_price_list, s.default_price_list) into v_price_list
  from public.selling_settings s where s.merchant_id = v_doc.merchant_id;
  select coalesce(s.auto_insert_price_list_rate_if_missing, false) into v_auto_price
  from public.stock_settings s where s.merchant_id = v_doc.merchant_id;

  if v_company.enable_perpetual_inventory then
    v_inventory := private.warehouse_account(v_profile.warehouse);
  end if;

  for v_row in
    select
      r.*, i.item_name as current_name, i.disabled, i.is_stock_item, i.stock_uom,
      -- 13.3: POS Profile → Item → Item Group → Brand → Company.
      coalesce(v_profile.income_account, i.income_account, g.income_account, b.income_account, v_company.default_income_account) as income,
      coalesce(v_profile.expense_account, i.expense_account, g.expense_account, v_company.default_expense_account) as expense,
      coalesce(v_profile.cost_center, i.selling_cost_center, g.selling_cost_center, b.selling_cost_center, v_company.cost_center) as center,
      (select u.conversion_factor from public.item_uoms u where u.item_id = i.id and u.uom_id = r.uom_id) as unit_factor
    from public.pos_invoice_items r
    join public.items i on i.id = r.item_id
    join public.item_groups g on g.id = i.item_group_id
    left join public.brands b on b.id = i.brand_id
    where r.pos_invoice_id = p_id
    order by r.idx
  loop
    v_rows := v_rows + 1;

    if v_row.disabled then
      raise exception 'item_unusable' using errcode = '23514', detail = 'A disabled item cannot be sold.';
    end if;
    -- 13.4: sold in the stock unit, or in one of the item's units at its conversion factor.
    if v_row.conversion_factor is distinct from (case when v_row.uom_id = v_row.stock_uom then 1 else v_row.unit_factor end)
      or v_row.stock_qty <> v_row.qty * v_row.conversion_factor then
      raise exception 'uom_not_on_item' using errcode = '23514', detail = 'A line is sold in a unit its item does not have, or at another conversion factor.';
    end if;
    if not v_profile.allow_rate_change and v_row.rate <> v_row.price_list_rate then
      raise exception 'rate_locked' using errcode = '23514', detail = 'This POS Profile does not allow a line''s rate to be changed.';
    end if;
    if abs(v_row.amount - v_row.qty * v_row.rate) > v_unit or v_row.net_amount < 0 or v_row.net_amount > v_row.amount + v_unit then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A line''s amount is not its quantity times its rate.';
    end if;

    v_net := v_net + v_row.net_amount;
    v_income := v_row.income;
    v_center := v_row.center;
    v_expense := null;
    v_cost := null;
    v_gl := v_gl || jsonb_build_object('account_id', v_income, 'amount', -v_row.net_amount, 'cost_center_id', v_center);

    -- "Posts at once: stock out and Cost of Goods Sold." A service moves no stock. Negative stock, a
    -- fraction in a whole-number unit and a backdated posting are the engine's to refuse.
    if v_row.is_stock_item then
      v_cost := -private.post_sle(
        v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_row.item_id, v_profile.warehouse, -v_row.stock_qty
      );
      if v_company.enable_perpetual_inventory then
        if v_inventory is null then
          raise exception 'no_inventory_account' using errcode = '23514',
            detail = 'Neither the warehouse, its parents nor the Company names an inventory account.';
        end if;
        v_expense := v_row.expense;
        v_gl := v_gl
          || jsonb_build_object('account_id', v_expense, 'amount', v_cost, 'cost_center_id', v_center)
          || jsonb_build_object('account_id', v_inventory, 'amount', -v_cost);
      end if;
    end if;

    update public.pos_invoice_items r set
      item_name = v_row.current_name, income_account = v_income, expense_account = v_expense, cost_center = v_center,
      valuation_rate = v_cost / v_row.stock_qty
    where r.id = v_row.id;

    -- 14.1, Stock Settings' Auto Insert Price List Rate if Missing: the item's first sale in this unit
    -- writes its rate into the sale's price list.
    if v_auto_price and v_row.price_list_rate > 0
      and exists (select 1 from public.price_lists p where p.id = v_price_list and p.enabled)
      and not exists (
        select 1 from public.item_prices p
        where p.item_id = v_row.item_id and p.price_list_id = v_price_list and p.uom_id = v_row.uom_id
      ) then
      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_doc.merchant_id, v_row.item_id, v_price_list, v_row.uom_id, v_row.price_list_rate);
    end if;
  end loop;

  if v_rows = 0 then
    raise exception 'no_rows' using errcode = '23514', detail = 'A sale needs at least one item.';
  end if;

  for v_row in select t.* from public.pos_invoice_taxes t where t.pos_invoice_id = p_id order by t.idx loop
    v_tax := v_tax + v_row.tax_amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.account_head, 'amount', -v_row.tax_amount, 'cost_center_id', v_row.cost_center);
  end loop;

  -- The totals add up. An inclusive tax can leave the grand total a few units off net + tax (the entered
  -- prices are kept); the Rounded Total is the grand total at the currency's smallest coin, or itself.
  if abs(v_doc.net_total - v_net) > v_unit or abs(v_doc.total_taxes_and_charges - v_tax) > v_unit
    or abs(v_doc.grand_total - v_net - v_tax) > 5 * v_unit
    or abs(v_doc.rounding_adjustment - (v_doc.rounded_total - v_doc.grand_total)) > v_unit
    or abs(v_doc.rounding_adjustment) > greatest(1, coalesce((
      select c.smallest_currency_fraction_value from public.currencies c
      where c.merchant_id = v_doc.merchant_id and c.code = v_company.default_currency
    ), 0)) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'The sale''s totals do not add up.';
  end if;

  -- "Only the modes set here will be available when using POS."
  for v_row in
    select r.id, r.amount, m.default_account, pp.id as offered
    from public.pos_invoice_payments r
    join public.modes_of_payment m on m.id = r.mode_of_payment_id
    left join public.pos_profile_payments pp on pp.pos_profile_id = v_doc.pos_profile_id and pp.mode_of_payment_id = r.mode_of_payment_id
    where r.pos_invoice_id = p_id
  loop
    if v_row.offered is null then
      raise exception 'payment_method_not_offered' using errcode = '23514', detail = 'The POS Profile does not offer that mode of payment.';
    end if;
    v_paid := v_paid + v_row.amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.default_account, 'amount', v_row.amount);
    update public.pos_invoice_payments r set account = v_row.default_account where r.id = v_row.id;
  end loop;

  -- "Paid in full, change returned, a small difference written off within the limit."
  v_change := greatest(v_paid - v_doc.rounded_total, 0);
  v_write_off := greatest(v_doc.rounded_total - v_paid, 0);
  if v_write_off > v_profile.write_off_limit then
    raise exception 'underpaid' using errcode = '23514', detail = 'The payments do not cover the total, and the shortfall is over the Write Off Limit.';
  end if;
  if abs(v_doc.paid_amount - v_paid) > v_unit or abs(v_doc.change_amount - v_change) > v_unit
    or abs(v_doc.write_off_amount - v_write_off) > v_unit then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'Paid, change and write-off do not match the payments.';
  end if;

  v_gl := v_gl
    -- Change goes back out of the till.
    || jsonb_build_object('account_id', coalesce(v_profile.account_for_change_amount, v_company.default_cash_account), 'amount', -v_change)
    || jsonb_build_object(
      'account_id', coalesce(v_profile.write_off_account, v_company.write_off_account), 'amount', v_write_off,
      'cost_center_id', coalesce(v_profile.write_off_cost_center, v_company.cost_center))
    -- What rounding added or took: the Rounded Total less net and taxes.
    || jsonb_build_object(
      'account_id', v_company.round_off_account, 'amount', -(v_doc.rounded_total - v_net - v_tax),
      'cost_center_id', coalesce(v_company.round_off_cost_center, v_company.cost_center));

  -- An account still missing here is refused by private.post_gl (account_unusable), as an unbalanced voucher is.
  perform private.post_gl(v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_gl);

  update public.pos_invoices set
    posting_date = v_today, warehouse = v_profile.warehouse, selling_price_list = v_price_list, tax_category = v_profile.tax_category
  where id = p_id;
end;
$$;

revoke execute on function private.submit_pos_invoices(uuid) from public, anon, authenticated, service_role;

-- "Ends the session: lists its POS Invoices and totals; per mode of payment shows opening, expected and
-- counted amount and the difference. Sales already posted, so it posts nothing."
create or replace function private.submit_pos_closing_entries(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.pos_closing_entries;
  v_session public.pos_opening_entries;
begin
  select * into v_doc from public.pos_closing_entries d where d.id = p_id;
  select * into v_session from public.pos_opening_entries s where s.id = v_doc.pos_opening_entry_id for update;

  if v_session.docstatus is distinct from 1 or v_session.status is distinct from 'Open' then
    raise exception 'session_not_open' using errcode = '23514', detail = 'That session is not open.';
  end if;
  -- Its cashier; or whoever may cancel a POS Opening Entry, for a session left open.
  if v_session.user_id is distinct from (select auth.uid())
    and v_session.merchant_id not in (select private.permitted_merchant_ids('POS Opening Entry', 'cancel')) then
    raise exception 'not_your_session' using errcode = '42501', detail = 'A session is closed by its cashier, or by a manager.';
  end if;

  -- Every mode the session touched or the profile offers gets a row; a mode nobody counted counts as 0.
  -- ponytail: change is taken off the invoice's first Cash-type payment, else its first payment — a change
  -- mode column on the invoice if a shop ever hands change out of another till.
  with sales as (
    select i.id, i.change_amount from public.pos_invoices i where i.pos_opening_entry_id = v_session.id and i.docstatus = 1
  ),
  paid as (
    select p.mode_of_payment_id as mode, sum(p.amount) as amount
    from public.pos_invoice_payments p join sales s on s.id = p.pos_invoice_id
    group by 1
  ),
  change as (
    select (
      select p.mode_of_payment_id
      from public.pos_invoice_payments p join public.modes_of_payment m on m.id = p.mode_of_payment_id
      where p.pos_invoice_id = s.id
      order by (m.type = 'Cash') desc, p.idx
      limit 1
    ) as mode, sum(s.change_amount) as amount
    from sales s where s.change_amount > 0
    group by 1
  ),
  opening as (
    select b.mode_of_payment_id as mode, b.opening_amount as amount
    from public.pos_opening_entry_balances b where b.pos_opening_entry_id = v_session.id
  ),
  modes as (
    select mode from paid union select mode from change where mode is not null union select mode from opening
    union select pp.mode_of_payment_id from public.pos_profile_payments pp where pp.pos_profile_id = v_session.pos_profile_id
  )
  insert into public.pos_closing_entry_payments as t
    (merchant_id, pos_closing_entry_id, idx, mode_of_payment_id, closing_amount, opening_amount, expected_amount, difference)
  select
    v_doc.merchant_id, p_id, 1000 + row_number() over (), m.mode, 0, coalesce(o.amount, 0),
    coalesce(o.amount, 0) + coalesce(p.amount, 0) - coalesce(c.amount, 0),
    -(coalesce(o.amount, 0) + coalesce(p.amount, 0) - coalesce(c.amount, 0))
  from modes m
  left join opening o on o.mode = m.mode
  left join paid p on p.mode = m.mode
  left join change c on c.mode = m.mode
  on conflict (pos_closing_entry_id, mode_of_payment_id) do update set
    opening_amount = excluded.opening_amount,
    expected_amount = excluded.expected_amount,
    difference = t.closing_amount - excluded.expected_amount;

  update public.pos_closing_entries set
    posting_date = private.merchant_today(v_doc.merchant_id),
    period_end = now(),
    grand_total = coalesce((select sum(i.grand_total) from public.pos_invoices i where i.pos_opening_entry_id = v_session.id and i.docstatus = 1), 0),
    net_total = coalesce((select sum(i.net_total) from public.pos_invoices i where i.pos_opening_entry_id = v_session.id and i.docstatus = 1), 0),
    total_quantity = coalesce((
      select sum(r.qty) from public.pos_invoice_items r
      join public.pos_invoices i on i.id = r.pos_invoice_id
      where i.pos_opening_entry_id = v_session.id and i.docstatus = 1
    ), 0)
  where id = p_id;

  update public.pos_opening_entries set status = 'Closed' where id = v_session.id;
end;
$$;

revoke execute on function private.submit_pos_closing_entries(uuid) from public, anon, authenticated, service_role;


-- 6. The three calls the register makes. Security invoker, like public.save_item_with_opening_stock: the
-- caller's own policies decide every row written (Create on the document, Write for its rows), and
-- public.submit_document() checks Submit — all in one transaction, so a refused sale leaves no draft and
-- uses no number. Rejected: a definer RPC per document — a second copy of submit_document's lock,
-- (select auth.uid()) and permission check, each one more definer function PostgREST serves.

create or replace function public.open_pos_session(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  insert into public.pos_opening_entries (merchant_id, posting_date, pos_profile_id)
  values (v_merchant, private.merchant_today(v_merchant), (payload ->> 'pos_profile_id')::uuid)
  returning id into v_id;

  insert into public.pos_opening_entry_balances (merchant_id, pos_opening_entry_id, idx, mode_of_payment_id, opening_amount)
  select v_merchant, v_id, t.ordinality, t.mode_of_payment_id, coalesce(t.opening_amount, 0)
  from jsonb_populate_recordset(null::public.pos_opening_entry_balances, coalesce(payload -> 'balances', '[]'::jsonb)) with ordinality as t;

  perform public.submit_document('POS Opening Entry', v_id);
  return v_id;
end;
$$;

revoke execute on function public.open_pos_session(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.open_pos_session(jsonb) to authenticated;

create or replace function public.pos_checkout(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_doc public.pos_invoices := jsonb_populate_record(null::public.pos_invoices, payload);
begin
  insert into public.pos_invoices (
    merchant_id, posting_date, pos_profile_id, pos_opening_entry_id, taxes_and_charges, net_total, total_taxes_and_charges,
    grand_total, rounding_adjustment, rounded_total, paid_amount, change_amount, write_off_amount
  )
  values (
    v_merchant, private.merchant_today(v_merchant), v_doc.pos_profile_id, v_doc.pos_opening_entry_id, v_doc.taxes_and_charges,
    coalesce(v_doc.net_total, 0), coalesce(v_doc.total_taxes_and_charges, 0), coalesce(v_doc.grand_total, 0),
    coalesce(v_doc.rounding_adjustment, 0), coalesce(v_doc.rounded_total, 0), coalesce(v_doc.paid_amount, 0),
    coalesce(v_doc.change_amount, 0), coalesce(v_doc.write_off_amount, 0)
  )
  returning id into v_id;

  insert into public.pos_invoice_items (
    merchant_id, pos_invoice_id, idx, item_id, qty, uom_id, conversion_factor, stock_qty, price_list_rate, rate, amount,
    net_rate, net_amount, item_tax_template_id
  )
  select
    v_merchant, v_id, t.ordinality, t.item_id, t.qty, t.uom_id, t.conversion_factor, t.stock_qty, coalesce(t.price_list_rate, 0),
    t.rate, t.amount, t.net_rate, t.net_amount, t.item_tax_template_id
  from jsonb_populate_recordset(null::public.pos_invoice_items, coalesce(payload -> 'items', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_taxes (
    merchant_id, pos_invoice_id, idx, charge_type, account_head, description, rate, row_id, included_in_print_rate, cost_center,
    tax_amount, total
  )
  select
    v_merchant, v_id, t.ordinality, t.charge_type, t.account_head, t.description, coalesce(t.rate, 0), t.row_id,
    coalesce(t.included_in_print_rate, false), t.cost_center, coalesce(t.tax_amount, 0), coalesce(t.total, 0)
  from jsonb_populate_recordset(null::public.pos_invoice_taxes, coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_payments (merchant_id, pos_invoice_id, idx, mode_of_payment_id, amount)
  select v_merchant, v_id, t.ordinality, t.mode_of_payment_id, t.amount
  from jsonb_populate_recordset(null::public.pos_invoice_payments, coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as t;

  perform public.submit_document('POS Invoice', v_id);
  return v_id;
end;
$$;

revoke execute on function public.pos_checkout(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.pos_checkout(jsonb) to authenticated;

create or replace function public.close_pos_session(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
begin
  insert into public.pos_closing_entries (merchant_id, posting_date, pos_opening_entry_id)
  values (v_merchant, private.merchant_today(v_merchant), (payload ->> 'pos_opening_entry_id')::uuid)
  returning id into v_id;

  insert into public.pos_closing_entry_payments (merchant_id, pos_closing_entry_id, idx, mode_of_payment_id, closing_amount)
  select v_merchant, v_id, t.ordinality, t.mode_of_payment_id, coalesce(t.closing_amount, 0)
  from jsonb_populate_recordset(null::public.pos_closing_entry_payments, coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as t;

  perform public.submit_document('POS Closing Entry', v_id);
  return v_id;
end;
$$;

revoke execute on function public.close_pos_session(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.close_pos_session(jsonb) to authenticated;


-- 7. Doctypes, permissions, policies (CLAUDE.md §6.7). A cashier is a Sales User: Create and Submit on the
-- three documents, and Write, which a document's rows are written under. Cancelling a sale is the
-- managers'. Accounts Settings becomes readable by every member: the cart reads "Taxes from Item Tax
-- Templates".

insert into public.doctypes (name, table_name, kind, restrictable)
values
  ('POS Opening Entry', 'pos_opening_entries', 'document', false),
  ('POS Invoice', 'pos_invoices', 'document', false),
  ('POS Closing Entry', 'pos_closing_entries', 'document', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete, can_submit, can_cancel)
values
  ('Sales User', 'POS Opening Entry', true, true, true, true, false, true, false),
  ('Sales Manager', 'POS Opening Entry', true, true, true, true, true, true, true),
  ('Accounts Manager', 'POS Opening Entry', true, true, false, false, false, false, false),

  ('Sales User', 'POS Invoice', true, true, true, true, false, true, false),
  ('Sales Manager', 'POS Invoice', true, true, true, true, true, true, true),
  ('Accounts Manager', 'POS Invoice', true, true, true, true, true, true, true),
  ('Accounts User', 'POS Invoice', true, true, false, false, false, false, false),

  ('Sales User', 'POS Closing Entry', true, true, true, true, false, true, false),
  ('Sales Manager', 'POS Closing Entry', true, true, true, true, true, true, true),
  ('Accounts Manager', 'POS Closing Entry', true, true, false, false, false, false, false),

  ('All', 'Accounts Settings', true, true, false, false, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('pos_opening_entries', 'POS Opening Entry');
select private.apply_doctype_policies('pos_opening_entry_balances', 'POS Opening Entry', true);
select private.apply_doctype_policies('pos_invoices', 'POS Invoice');
select private.apply_doctype_policies('pos_invoice_items', 'POS Invoice', true);
select private.apply_doctype_policies('pos_invoice_taxes', 'POS Invoice', true);
select private.apply_doctype_policies('pos_invoice_payments', 'POS Invoice', true);
select private.apply_doctype_policies('pos_closing_entries', 'POS Closing Entry');
select private.apply_doctype_policies('pos_closing_entry_payments', 'POS Closing Entry', true);


-- ===== 20261012080419_pos_returns_and_voids.sql =====

-- Step 19 of the POS batch, on ERPNext's model: Returns & Voids
-- (.claude/erpnext-docs/POS-System-Added-Features.md 19.1–19.2; docs.frappe.io/erpnext/sales-return,
-- /immutable-ledger-in-erpnext, /delete-submitted-document).
--
-- 1. A return is a POS Invoice: is_return, return_against, and on each line return_against_item. Its
--    quantities, amounts, totals and payments are negative, as ERPNext stores them, so a session's closing
--    entry and every report net a refund by adding it up.
-- 2. pos_invoice_taxes.item_wise_tax_detail: what each tax row charged each line — ERPNext's field. A return
--    is then the sale's own stored figures taken by share, and the database checks all of it.
-- 3. public.pos_checkout() and private.submit_pos_invoices(), re-created: one door and one poster for a
--    sale and a return.
-- 4. A void (public.cancel_document) is refused while returns stand against the sale, and once its session
--    is closed.
-- 5. public.delete_document(): Accounts Settings' "Delete Ledger Entries with the Document", for every
--    document.
--
-- Out of scope, so absent: exchanges, a credit kept for a later sale (no Customer), a return without the
-- goods, a return of a return. Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. The return's links. "Use the original submitted transaction as the starting point. This preserves the
-- link to the sale, fetches the original items and rates, and updates returned quantities correctly."

alter table public.pos_invoices
  add column if not exists is_return boolean not null default false,
  add column if not exists return_against uuid;

alter table public.pos_invoices drop constraint if exists pos_invoices_return_shape;
alter table public.pos_invoices add constraint pos_invoices_return_shape check (is_return = (return_against is not null));
alter table public.pos_invoices drop constraint if exists pos_invoices_return_fk;
alter table public.pos_invoices add constraint pos_invoices_return_fk
  foreign key (return_against, merchant_id) references public.pos_invoices (id, merchant_id);
create index if not exists pos_invoices_return_idx on public.pos_invoices (return_against, merchant_id);

alter table public.pos_invoice_items add column if not exists return_against_item uuid;

-- The line of the sale a return's line takes back. Dropped first, so the unique constraint it needs can be
-- made again.
alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_return_fk;
alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_id_merchant;
alter table public.pos_invoice_items add constraint pos_invoice_items_id_merchant unique (id, merchant_id);
alter table public.pos_invoice_items add constraint pos_invoice_items_return_fk
  foreign key (return_against_item, merchant_id) references public.pos_invoice_items (id, merchant_id);
create index if not exists pos_invoice_items_return_idx on public.pos_invoice_items (return_against_item, merchant_id);
-- One line of a return per line of the sale: what is left to return is checked line by line.
create unique index if not exists pos_invoice_items_return_once
  on public.pos_invoice_items (pos_invoice_id, return_against_item) where return_against_item is not null;

-- "ERPNext represents return quantities as negative values." Which sign a document's rows carry is the
-- poster's to hold.
alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_qty;
alter table public.pos_invoice_items add constraint pos_invoice_items_qty
  check (qty <> 0 and stock_qty <> 0 and sign(qty) = sign(stock_qty) and conversion_factor > 0);
alter table public.pos_invoice_payments drop constraint if exists pos_invoice_payments_amount;
alter table public.pos_invoice_payments add constraint pos_invoice_payments_amount check (amount <> 0);


-- 2. What each tax row charged each line, in the lines' order — ERPNext's item_wise_tax_detail. Unrounded,
-- as the app's engine holds them; the row's own tax_amount is their sum, rounded.

alter table public.pos_invoice_taxes add column if not exists item_wise_tax_detail jsonb not null default '[]'::jsonb;
alter table public.pos_invoice_taxes drop constraint if exists pos_invoice_taxes_detail;
alter table public.pos_invoice_taxes add constraint pos_invoice_taxes_detail check (jsonb_typeof(item_wise_tax_detail) = 'array');

-- The sales that exist: each row spread over the lines by net amount. Exact where every line carries the
-- same rate; a sale of mixed rates made before this migration refunds its tax by net amount.
update public.pos_invoice_taxes t
set item_wise_tax_detail = d.detail
from (
  select x.id, jsonb_agg(case when i.net_total = 0 then 0 else x.tax_amount * r.net_amount / i.net_total end order by r.idx) as detail
  from public.pos_invoice_taxes x
  join public.pos_invoices i on i.id = x.pos_invoice_id
  join public.pos_invoice_items r on r.pos_invoice_id = i.id
  group by x.id
) d
where d.id = t.id and t.item_wise_tax_detail = '[]'::jsonb;


-- 3. The door and the poster (20261012004616_pos_shift_and_sale.sql), for a return too. A return is the same
-- payload with return_against, each line naming the line it takes back.

create or replace function public.pos_checkout(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_doc public.pos_invoices := jsonb_populate_record(null::public.pos_invoices, payload);
begin
  insert into public.pos_invoices (
    merchant_id, posting_date, pos_profile_id, pos_opening_entry_id, taxes_and_charges, net_total, total_taxes_and_charges,
    grand_total, rounding_adjustment, rounded_total, paid_amount, change_amount, write_off_amount, is_return, return_against
  )
  values (
    v_merchant, private.merchant_today(v_merchant), v_doc.pos_profile_id, v_doc.pos_opening_entry_id, v_doc.taxes_and_charges,
    coalesce(v_doc.net_total, 0), coalesce(v_doc.total_taxes_and_charges, 0), coalesce(v_doc.grand_total, 0),
    coalesce(v_doc.rounding_adjustment, 0), coalesce(v_doc.rounded_total, 0), coalesce(v_doc.paid_amount, 0),
    coalesce(v_doc.change_amount, 0), coalesce(v_doc.write_off_amount, 0), v_doc.return_against is not null, v_doc.return_against
  )
  returning id into v_id;

  insert into public.pos_invoice_items (
    merchant_id, pos_invoice_id, idx, item_id, qty, uom_id, conversion_factor, stock_qty, price_list_rate, rate, amount,
    net_rate, net_amount, item_tax_template_id, return_against_item
  )
  select
    v_merchant, v_id, t.ordinality, t.item_id, t.qty, t.uom_id, t.conversion_factor, t.stock_qty, coalesce(t.price_list_rate, 0),
    t.rate, t.amount, t.net_rate, t.net_amount, t.item_tax_template_id, t.return_against_item
  from jsonb_populate_recordset(null::public.pos_invoice_items, coalesce(payload -> 'items', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_taxes (
    merchant_id, pos_invoice_id, idx, charge_type, account_head, description, rate, row_id, included_in_print_rate, cost_center,
    tax_amount, total, item_wise_tax_detail
  )
  select
    v_merchant, v_id, t.ordinality, t.charge_type, t.account_head, t.description, coalesce(t.rate, 0), t.row_id,
    coalesce(t.included_in_print_rate, false), t.cost_center, coalesce(t.tax_amount, 0), coalesce(t.total, 0),
    coalesce(t.item_wise_tax_detail, '[]'::jsonb)
  from jsonb_populate_recordset(null::public.pos_invoice_taxes, coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_payments (merchant_id, pos_invoice_id, idx, mode_of_payment_id, amount)
  select v_merchant, v_id, t.ordinality, t.mode_of_payment_id, t.amount
  from jsonb_populate_recordset(null::public.pos_invoice_payments, coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as t;

  perform public.submit_document('POS Invoice', v_id);
  return v_id;
end;
$$;

revoke execute on function public.pos_checkout(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.pos_checkout(jsonb) to authenticated;

-- The sale, and the return of one. ponytail: a sale's tax amounts, each line's net amount and its Price List
-- Rate are trusted from the app — the invoice stores the template and its rows as applied, so a query can
-- re-run them. Upgrade path: port taxes_and_totals and the price lookup to SQL. A return trusts nothing:
-- every figure of it is the sale's own, taken by share.
create or replace function private.submit_pos_invoices(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.pos_invoices;
  v_profile public.pos_profiles;
  v_company public.merchants;
  v_session public.pos_opening_entries;
  -- The sale a return is made against.
  v_original public.pos_invoices;
  v_row record;
  v_today date;
  -- One unit of the currency's smallest decimal: what two roundings of the same figure may differ by.
  v_unit numeric;
  v_price_list uuid;
  v_auto_price boolean;
  v_warehouse uuid;
  v_inventory uuid;
  v_income uuid;
  v_expense uuid;
  v_center uuid;
  v_cost numeric;
  v_rows integer := 0;
  v_tax_rows integer := 0;
  v_net numeric := 0;
  v_tax numeric := 0;
  v_paid numeric := 0;
  v_change numeric := 0;
  v_write_off numeric := 0;
  v_gl jsonb := '[]'::jsonb;
begin
  select * into v_doc from public.pos_invoices d where d.id = p_id;
  select * into v_profile from public.pos_profiles p where p.id = v_doc.pos_profile_id;
  select * into v_company from public.merchants m where m.id = v_doc.merchant_id;
  select * into v_session from public.pos_opening_entries s where s.id = v_doc.pos_opening_entry_id;
  v_today := private.merchant_today(v_doc.merchant_id);
  select 1 / power(10::numeric, coalesce(s.currency_precision, 2)) into v_unit from public.system_settings s where s.merchant_id = v_doc.merchant_id;
  v_unit := coalesce(v_unit, 0.01);

  -- "No sale without an open session": the caller's own, on this profile. A refund comes out of that drawer.
  if v_doc.user_id is distinct from (select auth.uid())
    or v_session.docstatus is distinct from 1 or v_session.status is distinct from 'Open'
    or v_session.user_id is distinct from (select auth.uid())
    or v_session.pos_profile_id is distinct from v_doc.pos_profile_id then
    raise exception 'no_open_session' using errcode = '23514', detail = 'A sale needs the cashier''s own open session on that POS Profile.';
  end if;
  if not private.pos_profile_usable(v_doc.pos_profile_id) then
    raise exception 'pos_profile_unusable' using errcode = '23514', detail = 'The POS Profile is disabled, or not applicable for this user.';
  end if;

  -- 19.1: "the original Delivery Note or Sales Invoice is submitted". Locked: two returns cannot both take
  -- the last unit, and a void of the sale waits for this one.
  if v_doc.is_return then
    select * into v_original from public.pos_invoices o where o.id = v_doc.return_against for update;
    if v_original.docstatus is distinct from 1 or v_original.is_return then
      raise exception 'return_original_invalid' using errcode = '23514',
        detail = 'A return is made against a submitted sale that is not itself a return.';
    end if;
  end if;

  -- "Stock back into the warehouse": the one it was sold from.
  v_warehouse := case when v_doc.is_return then v_original.warehouse else v_profile.warehouse end;

  select coalesce(v_profile.selling_price_list, s.default_price_list) into v_price_list
  from public.selling_settings s where s.merchant_id = v_doc.merchant_id;
  select coalesce(s.auto_insert_price_list_rate_if_missing, false) into v_auto_price
  from public.stock_settings s where s.merchant_id = v_doc.merchant_id;

  if v_company.enable_perpetual_inventory then
    v_inventory := private.warehouse_account(v_warehouse);
  end if;

  for v_row in
    select
      r.*, i.item_name as current_name, i.disabled, i.is_stock_item, i.stock_uom,
      -- 13.3: POS Profile → Item → Item Group → Brand → Company.
      coalesce(v_profile.income_account, i.income_account, g.income_account, b.income_account, v_company.default_income_account) as income,
      coalesce(v_profile.expense_account, i.expense_account, g.expense_account, v_company.default_expense_account) as expense,
      coalesce(v_profile.cost_center, i.selling_cost_center, g.selling_cost_center, b.selling_cost_center, v_company.cost_center) as center,
      (select u.conversion_factor from public.item_uoms u where u.item_id = i.id and u.uom_id = r.uom_id) as unit_factor,
      -- The line of the sale a return's line takes back, and what earlier returns took of it (below zero).
      o.pos_invoice_id as o_invoice, o.item_id as o_item, o.item_name as o_name, o.uom_id as o_uom, o.conversion_factor as o_factor,
      o.qty as o_qty, o.price_list_rate as o_price_list_rate, o.rate as o_rate, o.amount as o_amount, o.net_amount as o_net_amount,
      o.income_account as o_income, o.expense_account as o_expense, o.cost_center as o_center, o.valuation_rate as o_valuation,
      coalesce((
        select sum(x.qty) from public.pos_invoice_items x
        join public.pos_invoices xi on xi.id = x.pos_invoice_id
        where x.return_against_item = o.id and xi.docstatus = 1
      ), 0) as o_returned
    from public.pos_invoice_items r
    join public.items i on i.id = r.item_id
    join public.item_groups g on g.id = i.item_group_id
    left join public.brands b on b.id = i.brand_id
    left join public.pos_invoice_items o on o.id = r.return_against_item
    where r.pos_invoice_id = p_id
    order by r.idx
  loop
    v_rows := v_rows + 1;

    if v_doc.is_return then
      -- "Rate: Original selling rate used to calculate the returned value." The line is the sale's own, in
      -- the unit it was sold in, with a quantity below zero.
      if v_row.o_invoice is distinct from v_doc.return_against or v_row.qty > 0
        or v_row.item_id <> v_row.o_item or v_row.uom_id <> v_row.o_uom or v_row.conversion_factor <> v_row.o_factor
        or v_row.rate <> v_row.o_rate or v_row.price_list_rate <> v_row.o_price_list_rate
        or v_row.stock_qty <> v_row.qty * v_row.conversion_factor then
        raise exception 'return_line_invalid' using errcode = '23514',
          detail = 'A returned line names a line of the sale, with its item, unit and rate, and a quantity below zero.';
      end if;
      -- "Returned quantity is rejected: confirm it does not exceed the quantity available to return."
      if -v_row.qty > v_row.o_qty + v_row.o_returned then
        raise exception 'return_qty_exceeds' using errcode = '23514',
          detail = format('%s sold, %s already returned.', v_row.o_qty, -v_row.o_returned);
      end if;
      if abs(v_row.amount - v_row.o_amount * v_row.qty / v_row.o_qty) > v_unit
        or abs(v_row.net_amount - v_row.o_net_amount * v_row.qty / v_row.o_qty) > v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A returned line is not its share of the line sold.';
      end if;

      -- Where the sale posted, the return posts back.
      v_income := v_row.o_income;
      v_center := v_row.o_center;
    else
      if v_row.qty < 0 or v_row.return_against_item is not null then
        raise exception 'return_line_invalid' using errcode = '23514', detail = 'A sale''s lines are sold, not returned.';
      end if;
      if v_row.disabled then
        raise exception 'item_unusable' using errcode = '23514', detail = 'A disabled item cannot be sold.';
      end if;
      -- 13.4: sold in the stock unit, or in one of the item's units at its conversion factor.
      if v_row.conversion_factor is distinct from (case when v_row.uom_id = v_row.stock_uom then 1 else v_row.unit_factor end)
        or v_row.stock_qty <> v_row.qty * v_row.conversion_factor then
        raise exception 'uom_not_on_item' using errcode = '23514', detail = 'A line is sold in a unit its item does not have, or at another conversion factor.';
      end if;
      if not v_profile.allow_rate_change and v_row.rate <> v_row.price_list_rate then
        raise exception 'rate_locked' using errcode = '23514', detail = 'This POS Profile does not allow a line''s rate to be changed.';
      end if;
      if abs(v_row.amount - v_row.qty * v_row.rate) > v_unit or v_row.net_amount < 0 or v_row.net_amount > v_row.amount + v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A line''s amount is not its quantity times its rate.';
      end if;

      v_income := v_row.income;
      v_center := v_row.center;
    end if;

    v_net := v_net + v_row.net_amount;
    v_expense := null;
    v_cost := null;
    v_gl := v_gl || jsonb_build_object('account_id', v_income, 'amount', -v_row.net_amount, 'cost_center_id', v_center);

    -- "Posts at once: stock out and Cost of Goods Sold." A service moves no stock. Negative stock, a
    -- fraction in a whole-number unit and a backdated posting are the engine's to refuse. A return brings
    -- back what the sale moved, at the valuation it left at.
    if (v_doc.is_return and v_row.o_valuation is not null) or (not v_doc.is_return and v_row.is_stock_item) then
      v_cost := -private.post_sle(
        v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_row.item_id, v_warehouse, -v_row.stock_qty,
        case when v_doc.is_return then v_row.o_valuation end
      );
      if v_company.enable_perpetual_inventory then
        if v_inventory is null then
          raise exception 'no_inventory_account' using errcode = '23514',
            detail = 'Neither the warehouse, its parents nor the Company names an inventory account.';
        end if;
        v_expense := case when v_doc.is_return then coalesce(v_row.o_expense, v_row.expense) else v_row.expense end;
        v_gl := v_gl
          || jsonb_build_object('account_id', v_expense, 'amount', v_cost, 'cost_center_id', v_center)
          || jsonb_build_object('account_id', v_inventory, 'amount', -v_cost);
      end if;
    end if;

    update public.pos_invoice_items r set
      item_name = case when v_doc.is_return then v_row.o_name else v_row.current_name end,
      income_account = v_income, expense_account = v_expense, cost_center = v_center,
      valuation_rate = v_cost / v_row.stock_qty
    where r.id = v_row.id;

    -- 14.1, Stock Settings' Auto Insert Price List Rate if Missing: the item's first sale in this unit
    -- writes its rate into the sale's price list.
    if not v_doc.is_return and v_auto_price and v_row.price_list_rate > 0
      and exists (select 1 from public.price_lists p where p.id = v_price_list and p.enabled)
      and not exists (
        select 1 from public.item_prices p
        where p.item_id = v_row.item_id and p.price_list_id = v_price_list and p.uom_id = v_row.uom_id
      ) then
      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_doc.merchant_id, v_row.item_id, v_price_list, v_row.uom_id, v_row.price_list_rate);
    end if;
  end loop;

  if v_rows = 0 then
    raise exception 'no_rows' using errcode = '23514', detail = 'A sale needs at least one item.';
  end if;

  for v_row in
    select
      t.*, o.account_head as o_account,
      -- The sale's row, line by line, for the share of each line this return takes back.
      (
        select sum((o.item_wise_tax_detail ->> (l.pos - 1))::numeric * r.qty / l.qty)
        from public.pos_invoice_items r
        join (
          select x.id, x.qty, (row_number() over (order by x.idx))::integer as pos
          from public.pos_invoice_items x where x.pos_invoice_id = v_doc.return_against
        ) l on l.id = r.return_against_item
        where r.pos_invoice_id = p_id
      ) as o_share
    from public.pos_invoice_taxes t
    left join public.pos_invoice_taxes o on o.pos_invoice_id = v_doc.return_against and o.idx = t.idx
    where t.pos_invoice_id = p_id
    order by t.idx
  loop
    v_tax_rows := v_tax_rows + 1;

    if v_doc.is_return then
      if v_row.o_account is distinct from v_row.account_head or abs(v_row.tax_amount - coalesce(v_row.o_share, 0)) > v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A returned tax is not its share of the tax charged.';
      end if;
    elsif jsonb_array_length(v_row.item_wise_tax_detail) <> v_rows
      or abs(v_row.tax_amount - coalesce((select sum(d.value::numeric) from jsonb_array_elements_text(v_row.item_wise_tax_detail) as d (value)), 0)) > v_unit then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A tax row''s amounts per line do not add up to it.';
    end if;

    v_tax := v_tax + v_row.tax_amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.account_head, 'amount', -v_row.tax_amount, 'cost_center_id', v_row.cost_center);
  end loop;

  if v_doc.is_return and v_tax_rows <> (select count(*) from public.pos_invoice_taxes o where o.pos_invoice_id = v_doc.return_against) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'A return carries every tax row of its sale.';
  end if;

  -- The totals add up. An inclusive tax can leave the grand total a few units off net + tax (the entered
  -- prices are kept); the Rounded Total is the grand total at the currency's smallest coin, or itself.
  if abs(v_doc.net_total - v_net) > v_unit or abs(v_doc.total_taxes_and_charges - v_tax) > v_unit
    or abs(v_doc.grand_total - v_net - v_tax) > 5 * v_unit
    or abs(v_doc.rounding_adjustment - (v_doc.rounded_total - v_doc.grand_total)) > v_unit
    or abs(v_doc.rounding_adjustment) > greatest(1, coalesce((
      select c.smallest_currency_fraction_value from public.currencies c
      where c.merchant_id = v_doc.merchant_id and c.code = v_company.default_currency
    ), 0)) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'The sale''s totals do not add up.';
  end if;

  -- "Only the modes set here will be available when using POS", and for a refund only those with
  -- "Allow in Returns".
  for v_row in
    select r.id, r.amount, m.default_account, pp.id as offered, pp.allow_in_returns
    from public.pos_invoice_payments r
    join public.modes_of_payment m on m.id = r.mode_of_payment_id
    left join public.pos_profile_payments pp on pp.pos_profile_id = v_doc.pos_profile_id and pp.mode_of_payment_id = r.mode_of_payment_id
    where r.pos_invoice_id = p_id
  loop
    if v_row.offered is null then
      raise exception 'payment_method_not_offered' using errcode = '23514', detail = 'The POS Profile does not offer that mode of payment.';
    end if;
    if v_doc.is_return and not v_row.allow_in_returns then
      raise exception 'refund_method_not_allowed' using errcode = '23514', detail = 'That mode of payment is not marked Allow in Returns on the POS Profile.';
    end if;
    if (v_row.amount < 0) is distinct from v_doc.is_return then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A sale is paid in; a return is paid out.';
    end if;
    v_paid := v_paid + v_row.amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.default_account, 'amount', v_row.amount);
    update public.pos_invoice_payments r set account = v_row.default_account where r.id = v_row.id;
  end loop;

  if v_doc.is_return then
    -- The refund is the whole of the return: nothing to hand back, nothing to write off.
    if abs(v_paid - v_doc.rounded_total) > v_unit then
      raise exception 'refund_mismatch' using errcode = '23514', detail = 'The refund is not the return''s total.';
    end if;
  else
    -- "Paid in full, change returned, a small difference written off within the limit."
    v_change := greatest(v_paid - v_doc.rounded_total, 0);
    v_write_off := greatest(v_doc.rounded_total - v_paid, 0);
    if v_write_off > v_profile.write_off_limit then
      raise exception 'underpaid' using errcode = '23514', detail = 'The payments do not cover the total, and the shortfall is over the Write Off Limit.';
    end if;
  end if;
  if abs(v_doc.paid_amount - v_paid) > v_unit or abs(v_doc.change_amount - v_change) > v_unit
    or abs(v_doc.write_off_amount - v_write_off) > v_unit then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'Paid, change and write-off do not match the payments.';
  end if;

  v_gl := v_gl
    -- Change goes back out of the till.
    || jsonb_build_object('account_id', coalesce(v_profile.account_for_change_amount, v_company.default_cash_account), 'amount', -v_change)
    || jsonb_build_object(
      'account_id', coalesce(v_profile.write_off_account, v_company.write_off_account), 'amount', v_write_off,
      'cost_center_id', coalesce(v_profile.write_off_cost_center, v_company.cost_center))
    -- What rounding added or took: the Rounded Total less net and taxes.
    || jsonb_build_object(
      'account_id', v_company.round_off_account, 'amount', -(v_doc.rounded_total - v_net - v_tax),
      'cost_center_id', coalesce(v_company.round_off_cost_center, v_company.cost_center));

  -- An account still missing here is refused by private.post_gl (account_unusable), as an unbalanced voucher is.
  perform private.post_gl(v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_gl);

  update public.pos_invoices set
    posting_date = v_today,
    warehouse = v_warehouse,
    selling_price_list = case when v_doc.is_return then v_original.selling_price_list else v_price_list end,
    tax_category = case when v_doc.is_return then v_original.tax_category else v_profile.tax_category end
  where id = p_id;
end;
$$;

revoke execute on function private.submit_pos_invoices(uuid) from public, anon, authenticated, service_role;


-- 4. Voids (19.2). public.cancel_document() reverses a sale's stock and ledger entries as Accounts Settings
-- say, for whoever holds Cancel; these are the two sales it must leave alone. "Original document cannot be
-- cancelled: use a return document instead of forcing cancellation."

create or replace function private.guard_pos_invoice_void()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.docstatus = 2 and old.docstatus = 1 then
    if exists (select 1 from public.pos_invoices r where r.return_against = new.id and r.docstatus = 1) then
      raise exception 'has_returns' using errcode = '23514', detail = 'Returns stand against this sale; cancel them first.';
    end if;
    -- Its POS Closing Entry has counted it: the entry's expected amounts would stop matching the books.
    if exists (select 1 from public.pos_opening_entries s where s.id = new.pos_opening_entry_id and s.status = 'Closed') then
      raise exception 'session_closed' using errcode = '23514', detail = 'The session this was rung in is closed; make a return instead.';
    end if;
  end if;
  return new;
end;
$$;

revoke execute on function private.guard_pos_invoice_void() from public, anon, authenticated, service_role;

drop trigger if exists pos_invoices_void_guard on public.pos_invoices;
create trigger pos_invoices_void_guard
  before update of docstatus on public.pos_invoices
  for each row execute function private.guard_pos_invoice_void();


-- 5. Delete a cancelled document (docs.frappe.io/erpnext/delete-submitted-document: "To delete a submitted
-- document, you need to cancel it first"). A draft is deleted through its own policy; a cancelled document
-- has entries in the ledgers no role may write, so this is the third door beside submit_document and
-- cancel_document — security definer in `public`, and CLAUDE.md §6.2's three rules: revoked from every role
-- and granted to `authenticated` alone, search_path pinned with every name qualified, and the caller checked
-- inside — signed in, and holding Delete on that document type in that system.
--
-- Accounts Settings decide: with "Delete Ledger Entries with the Document" on, the document goes with every
-- entry it posted and every entry that reversed them; off, a cancelled document stays as the source of its
-- entries ("Deleting it would break that audit trail").
create or replace function public.delete_document(p_doctype text, p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_table text;
  v_merchant uuid;
  v_status smallint;
begin
  if (select auth.uid()) is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select d.table_name into v_table from public.doctypes d where d.name = p_doctype and d.kind = 'document';
  if v_table is null then
    raise exception 'not_a_document' using errcode = '22023';
  end if;

  execute format('select d.merchant_id, d.docstatus from public.%I d where d.id = $1 for update', v_table)
    into v_merchant, v_status using p_id;

  -- One answer for a document that is not there and one the caller may not delete.
  if v_merchant is null or v_merchant not in (select private.permitted_merchant_ids(p_doctype, 'delete')) then
    raise exception 'not_permitted' using errcode = '42501';
  end if;

  if v_status <> 2 then
    raise exception 'not_cancelled' using errcode = '23514', detail = 'Only a cancelled document is deleted here; a draft through its own page.';
  end if;

  if not coalesce((select s.delete_linked_ledger_entries from public.accounts_settings s where s.merchant_id = v_merchant), false) then
    raise exception 'ledger_entries_kept' using errcode = '23514',
      detail = 'Accounts Settings keep a cancelled document''s ledger entries, and the document with them.';
  end if;

  delete from public.gl_entries g where g.merchant_id = v_merchant and g.voucher_type = p_doctype and g.voucher_id = p_id;
  delete from public.stock_ledger_entries s where s.merchant_id = v_merchant and s.voucher_type = p_doctype and s.voucher_id = p_id;

  -- "If your document is linked with other documents, you will need to cancel the dependent document first."
  begin
    execute format('delete from public.%I where id = $1', v_table) using p_id;
  exception when foreign_key_violation then
    raise exception 'document_in_use' using errcode = '23503', detail = 'Another document still names this one.';
  end;
end;
$$;

revoke execute on function public.delete_document(text, uuid) from public, anon, authenticated, service_role;
grant execute on function public.delete_document(text, uuid) to authenticated;


-- ===== 20261012085121_discounts.sql =====

-- Step 20 of the ERPNext rebuild, part 1 — what a discount is set up from
-- (.claude/erpnext-docs/POS-System-Added-Features.md 20.3–20.5; docs.frappe.io/erpnext/pricing-rule,
-- /discount_accounting, /pos-profile, /applying-discount): the discount accounts, the Item's and the POS
-- Profile's discount fields, and Pricing Rules. The sale that uses them is the next migration,
-- pos_invoice_discounts.

create schema if not exists private;


-- 1. The new fields.

-- 20.5: "falling back to the Company's Default Discount Account".
alter table public.merchants add column if not exists default_discount_account uuid;

alter table public.merchants drop constraint if exists merchants_default_discount_account_fk;
alter table public.merchants add constraint merchants_default_discount_account_fk
  foreign key (default_discount_account, id) references public.accounts (id, merchant_id);

alter table public.items
  -- 20.3, Max Discount (%): the most any line of this item may be discounted. 0: no limit.
  add column if not exists max_discount numeric not null default 0,
  -- 20.5: where this item's discounts post under Discount Accounting.
  add column if not exists discount_account uuid;

alter table public.items drop constraint if exists items_max_discount;
alter table public.items add constraint items_max_discount check (max_discount between 0 and 100);
alter table public.items drop constraint if exists items_discount_account_fk;
alter table public.items add constraint items_discount_account_fk
  foreign key (discount_account, merchant_id) references public.accounts (id, merchant_id);
create index if not exists items_discount_account_idx on public.items (discount_account, merchant_id);

alter table public.pos_profiles
  -- 20.2: what an additional discount is taken from, to start with.
  add column if not exists apply_discount_on text not null default 'Grand Total',
  -- 20.3, Allow User to Edit Discount: a cashier may discount a line, and the sale.
  add column if not exists allow_discount_change boolean not null default false,
  -- 20.4: no Pricing Rule applies at this register.
  add column if not exists ignore_pricing_rule boolean not null default false,
  -- 20.5: where this register's additional discounts post under Discount Accounting.
  add column if not exists discount_account uuid;

alter table public.pos_profiles drop constraint if exists pos_profiles_apply_discount_on;
alter table public.pos_profiles add constraint pos_profiles_apply_discount_on check (apply_discount_on in ('Grand Total', 'Net Total'));
alter table public.pos_profiles drop constraint if exists pos_profiles_discount_account_fk;
alter table public.pos_profiles add constraint pos_profiles_discount_account_fk
  foreign key (discount_account, merchant_id) references public.accounts (id, merchant_id);
create index if not exists pos_profiles_discount_account_idx on public.pos_profiles (discount_account, merchant_id);


-- 2. One check for every discount account — the Company's, an Item's, a POS Profile's: an enabled Income
-- or Expense ledger of the same system. The column is the trigger's argument; the system is `merchant_id`,
-- or `id` on merchants itself.
-- Rejected: a branch in private.validate_company_accounts(), validate_defaults() and validate_pos_profile()
-- each — three functions re-created for one column.
create or replace function private.validate_discount_account()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_column text := tg_argv[0];
  v_new jsonb := to_jsonb(new);
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_id uuid := (v_new ->> v_column)::uuid;
begin
  if v_id is null or (v_new ->> v_column) is not distinct from (v_old ->> v_column) then
    return new;
  end if;

  if not exists (
    select 1 from public.accounts a
    where a.id = v_id and a.merchant_id = coalesce(v_new ->> 'merchant_id', v_new ->> 'id')::uuid
      and not a.is_group and not a.disabled and a.root_type in ('Income', 'Expense')
  ) then
    raise exception 'default_invalid' using errcode = '23514', detail = format('%s cannot name that record.', v_column);
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_discount_account() from public, anon, authenticated, service_role;

drop trigger if exists merchants_validate_discount_account on public.merchants;
create trigger merchants_validate_discount_account
  before insert or update of default_discount_account on public.merchants
  for each row execute function private.validate_discount_account('default_discount_account');

drop trigger if exists items_validate_discount_account on public.items;
create trigger items_validate_discount_account
  before insert or update of discount_account on public.items
  for each row execute function private.validate_discount_account('discount_account');

drop trigger if exists pos_profiles_validate_discount_account on public.pos_profiles;
create trigger pos_profiles_validate_discount_account
  before insert or update of discount_account on public.pos_profiles
  for each row execute function private.validate_discount_account('discount_account');


-- 3. 20.5: "A new system gets a Sales Discounts Allowed ledger under Indirect Expenses as that default."
-- After the chart (merchants_seed_40_accounting) and the other default accounts (…_50_…), so 52.
create or replace function private.seed_discounts_for(p_merchant uuid)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_parent uuid;
  v_account uuid;
begin
  select a.id into v_parent from public.accounts a
  where a.merchant_id = p_merchant and a.account_name = 'Indirect Expenses' and a.is_group and a.root_type = 'Expense';
  -- A chart that no longer has that group keeps the default it has, or none.
  if v_parent is null then
    return;
  end if;

  v_account := private.seed_account(p_merchant, 'Sales Discounts Allowed', v_parent, false, 'Expense', null);

  -- An account of that name the system already made, and made a group or disabled, is not forced in.
  update public.merchants m set default_discount_account = v_account
  where m.id = p_merchant and m.default_discount_account is null
    and exists (select 1 from public.accounts a where a.id = v_account and not a.is_group and not a.disabled and a.root_type = 'Expense');
end;
$$;

revoke execute on function private.seed_discounts_for(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_discounts()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_discounts_for(new.id);
  return new;
end;
$$;

revoke execute on function private.seed_discounts() from public, anon, authenticated, service_role;

drop trigger if exists merchants_seed_52_discounts on public.merchants;
create trigger merchants_seed_52_discounts
  after insert on public.merchants
  for each row execute function private.seed_discounts();

-- The systems that exist.
select private.seed_discounts_for(m.id) from public.merchants m;


-- 4. An item with its rows (20261011134357_item_prices.sql), now with Max Discount and its Discount Account.
create or replace function public.save_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_rate numeric := nullif(payload ->> 'standard_rate', '')::numeric;
  v_list uuid;
begin
  if v_id is null then
    insert into public.items (
      merchant_id, item_code, item_name, item_group_id, stock_uom, description, brand_id, disabled, is_stock_item,
      valuation_method, allow_negative_stock, reorder_level, sales_uom,
      default_warehouse, default_price_list, selling_cost_center, income_account, expense_account,
      max_discount, discount_account
    )
    values (
      v_merchant,
      payload ->> 'item_code',
      payload ->> 'item_name',
      (payload ->> 'item_group_id')::uuid,
      (payload ->> 'stock_uom')::uuid,
      nullif(btrim(payload ->> 'description'), ''),
      nullif(payload ->> 'brand_id', '')::uuid,
      coalesce((payload ->> 'disabled')::boolean, false),
      coalesce((payload ->> 'is_stock_item')::boolean, true),
      nullif(payload ->> 'valuation_method', ''),
      coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      nullif(payload ->> 'reorder_level', '')::numeric,
      nullif(payload ->> 'sales_uom', '')::uuid,
      nullif(payload ->> 'default_warehouse', '')::uuid,
      nullif(payload ->> 'default_price_list', '')::uuid,
      nullif(payload ->> 'selling_cost_center', '')::uuid,
      nullif(payload ->> 'income_account', '')::uuid,
      nullif(payload ->> 'expense_account', '')::uuid,
      coalesce(nullif(payload ->> 'max_discount', '')::numeric, 0),
      nullif(payload ->> 'discount_account', '')::uuid
    )
    returning id into v_id;

    if coalesce(v_rate, 0) > 0 then
      select s.default_price_list into v_list from public.selling_settings s where s.merchant_id = v_merchant;
      if v_list is null then
        raise exception 'no_default_price_list' using errcode = '23514',
          detail = 'Selling Settings names no default price list for the Standard Selling Rate.';
      end if;

      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_merchant, v_id, v_list, (payload ->> 'stock_uom')::uuid, v_rate);
    end if;
  else
    update public.items set
      item_name = payload ->> 'item_name',
      item_group_id = (payload ->> 'item_group_id')::uuid,
      stock_uom = (payload ->> 'stock_uom')::uuid,
      description = nullif(btrim(payload ->> 'description'), ''),
      brand_id = nullif(payload ->> 'brand_id', '')::uuid,
      disabled = coalesce((payload ->> 'disabled')::boolean, false),
      is_stock_item = coalesce((payload ->> 'is_stock_item')::boolean, true),
      valuation_method = nullif(payload ->> 'valuation_method', ''),
      allow_negative_stock = coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      reorder_level = nullif(payload ->> 'reorder_level', '')::numeric,
      sales_uom = nullif(payload ->> 'sales_uom', '')::uuid,
      default_warehouse = nullif(payload ->> 'default_warehouse', '')::uuid,
      default_price_list = nullif(payload ->> 'default_price_list', '')::uuid,
      selling_cost_center = nullif(payload ->> 'selling_cost_center', '')::uuid,
      income_account = nullif(payload ->> 'income_account', '')::uuid,
      expense_account = nullif(payload ->> 'expense_account', '')::uuid,
      max_discount = coalesce(nullif(payload ->> 'max_discount', '')::numeric, 0),
      discount_account = nullif(payload ->> 'discount_account', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.item_uoms where item_id = v_id;

  insert into public.item_uoms (merchant_id, item_id, idx, uom_id, conversion_factor)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'uom_id')::uuid, (r.value ->> 'conversion_factor')::numeric
  from jsonb_array_elements(coalesce(payload -> 'uoms', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.item_taxes where item_id = v_id;

  insert into public.item_taxes (merchant_id, item_id, idx, item_tax_template_id, tax_category_id, valid_from)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_tax_template_id')::uuid,
    nullif(r.value ->> 'tax_category_id', '')::uuid,
    nullif(r.value ->> 'valid_from', '')::date
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item(jsonb) to authenticated;


-- 5. A POS Profile with its rows (20261011233916_pos_profiles.sql), now with its four discount fields.
create or replace function public.save_pos_profile(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_row public.pos_profiles;
begin
  v_row := jsonb_populate_record(null::public.pos_profiles, jsonb_strip_nulls(jsonb_build_object(
    'pos_profile_name', btrim(payload ->> 'pos_profile_name'),
    'disabled', coalesce((payload ->> 'disabled')::boolean, false),
    'warehouse', nullif(payload ->> 'warehouse', ''),
    'selling_price_list', nullif(payload ->> 'selling_price_list', ''),
    'taxes_and_charges', nullif(payload ->> 'taxes_and_charges', ''),
    'tax_category', nullif(payload ->> 'tax_category', ''),
    'print_format', nullif(payload ->> 'print_format', ''),
    'letter_head', nullif(payload ->> 'letter_head', ''),
    'account_for_change_amount', nullif(payload ->> 'account_for_change_amount', ''),
    'write_off_account', nullif(payload ->> 'write_off_account', ''),
    'write_off_cost_center', nullif(payload ->> 'write_off_cost_center', ''),
    'write_off_limit', coalesce(nullif(payload ->> 'write_off_limit', '')::numeric, 0),
    'income_account', nullif(payload ->> 'income_account', ''),
    'expense_account', nullif(payload ->> 'expense_account', ''),
    'cost_center', nullif(payload ->> 'cost_center', ''),
    'hide_unavailable_items', coalesce((payload ->> 'hide_unavailable_items')::boolean, false),
    'allow_rate_change', coalesce((payload ->> 'allow_rate_change')::boolean, false),
    'set_grand_total_to_default_mop', coalesce((payload ->> 'set_grand_total_to_default_mop')::boolean, true),
    'print_receipt_on_order_complete', coalesce((payload ->> 'print_receipt_on_order_complete')::boolean, false),
    'apply_discount_on', coalesce(nullif(payload ->> 'apply_discount_on', ''), 'Grand Total'),
    'allow_discount_change', coalesce((payload ->> 'allow_discount_change')::boolean, false),
    'ignore_pricing_rule', coalesce((payload ->> 'ignore_pricing_rule')::boolean, false),
    'discount_account', nullif(payload ->> 'discount_account', '')
  )));

  if v_id is null then
    insert into public.pos_profiles (
      merchant_id, pos_profile_name, disabled, warehouse, selling_price_list, taxes_and_charges, tax_category, print_format,
      letter_head, account_for_change_amount, write_off_account, write_off_cost_center, write_off_limit, income_account,
      expense_account, cost_center, hide_unavailable_items, allow_rate_change, set_grand_total_to_default_mop,
      print_receipt_on_order_complete, apply_discount_on, allow_discount_change, ignore_pricing_rule, discount_account
    )
    values (
      v_merchant, v_row.pos_profile_name, v_row.disabled, v_row.warehouse, v_row.selling_price_list, v_row.taxes_and_charges,
      v_row.tax_category, v_row.print_format, v_row.letter_head, v_row.account_for_change_amount, v_row.write_off_account,
      v_row.write_off_cost_center, v_row.write_off_limit, v_row.income_account, v_row.expense_account, v_row.cost_center,
      v_row.hide_unavailable_items, v_row.allow_rate_change, v_row.set_grand_total_to_default_mop,
      v_row.print_receipt_on_order_complete, v_row.apply_discount_on, v_row.allow_discount_change, v_row.ignore_pricing_rule,
      v_row.discount_account
    )
    returning id into v_id;
  else
    update public.pos_profiles set
      pos_profile_name = v_row.pos_profile_name,
      disabled = v_row.disabled,
      warehouse = v_row.warehouse,
      selling_price_list = v_row.selling_price_list,
      taxes_and_charges = v_row.taxes_and_charges,
      tax_category = v_row.tax_category,
      print_format = v_row.print_format,
      letter_head = v_row.letter_head,
      account_for_change_amount = v_row.account_for_change_amount,
      write_off_account = v_row.write_off_account,
      write_off_cost_center = v_row.write_off_cost_center,
      write_off_limit = v_row.write_off_limit,
      income_account = v_row.income_account,
      expense_account = v_row.expense_account,
      cost_center = v_row.cost_center,
      hide_unavailable_items = v_row.hide_unavailable_items,
      allow_rate_change = v_row.allow_rate_change,
      set_grand_total_to_default_mop = v_row.set_grand_total_to_default_mop,
      print_receipt_on_order_complete = v_row.print_receipt_on_order_complete,
      apply_discount_on = v_row.apply_discount_on,
      allow_discount_change = v_row.allow_discount_change,
      ignore_pricing_rule = v_row.ignore_pricing_rule,
      discount_account = v_row.discount_account
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'pos_profile_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.pos_profile_users where pos_profile_id = v_id;
  insert into public.pos_profile_users (merchant_id, pos_profile_id, idx, member_id, is_default)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'member_id')::uuid, coalesce((r.value ->> 'is_default')::boolean, false)
  from jsonb_array_elements(coalesce(payload -> 'users', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.pos_profile_payments where pos_profile_id = v_id;
  insert into public.pos_profile_payments (merchant_id, pos_profile_id, idx, mode_of_payment_id, is_default, allow_in_returns)
  select
    v_merchant, v_id, r.idx::integer, (r.value ->> 'mode_of_payment_id')::uuid,
    coalesce((r.value ->> 'is_default')::boolean, false), coalesce((r.value ->> 'allow_in_returns')::boolean, false)
  from jsonb_array_elements(coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as r (value, idx);

  delete from public.pos_profile_item_groups where pos_profile_id = v_id;
  insert into public.pos_profile_item_groups (merchant_id, pos_profile_id, idx, item_group_id)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'item_group_id')::uuid
  from jsonb_array_elements(coalesce(payload -> 'item_groups', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_pos_profile(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_pos_profile(jsonb) to authenticated;


-- 6. Pricing Rule (20.4): "Automatic price discount." A rule names what it applies on in its rows — items,
-- item groups (a group covers the groups under it) or brands — and gives one of three results.
-- Out of scope: Apply On Transaction, a customer or territory, free items, margins, coupons, promotional
-- schemes, mixed conditions.

create table if not exists public.pricing_rules (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  title text not null,
  -- What its rows in pricing_rule_targets are.
  apply_on text not null default 'Item Code',
  -- A line's quantity in the item's stock unit, as ERPNext counts it. A max of 0 is no upper limit.
  min_qty numeric not null default 0,
  max_qty numeric not null default 0,
  -- A line's quantity × Price List Rate. A max of 0 is no upper limit.
  min_amt numeric not null default 0,
  max_amt numeric not null default 0,
  valid_from date,
  valid_upto date,
  -- Empty: any price list.
  for_price_list uuid,
  -- 1 is the highest, as a Tax Rule's reads (the human's decision of 2026-10-12). Rejected: ERPNext's
  -- "higher the number, higher the priority" — two screens of one app reading opposite ways.
  priority integer not null default 1,
  disable boolean not null default false,
  -- Which of the three below the rule gives. A Rate is per stock unit; a Discount Amount is per unit sold.
  rate_or_discount text not null default 'Discount Percentage',
  rate numeric not null default 0,
  discount_percentage numeric not null default 0,
  discount_amount numeric not null default 0,
  created_at timestamptz not null default now(),

  constraint pricing_rules_id_merchant unique (id, merchant_id),
  constraint pricing_rules_title_unique unique (merchant_id, title),
  constraint pricing_rules_title_length check (length(btrim(title)) between 1 and 140),
  constraint pricing_rules_apply_on check (apply_on in ('Item Code', 'Item Group', 'Brand')),
  constraint pricing_rules_ranges check (
    min_qty >= 0 and max_qty >= 0 and min_amt >= 0 and max_amt >= 0
    and (max_qty = 0 or max_qty >= min_qty) and (max_amt = 0 or max_amt >= min_amt)
  ),
  constraint pricing_rules_dates check (valid_from is null or valid_upto is null or valid_from <= valid_upto),
  constraint pricing_rules_priority check (priority >= 1),
  constraint pricing_rules_result check (
    rate_or_discount in ('Rate', 'Discount Percentage', 'Discount Amount')
    and rate >= 0 and discount_percentage between 0 and 100 and discount_amount >= 0
  ),
  constraint pricing_rules_price_list_fk foreign key (for_price_list, merchant_id) references public.price_lists (id, merchant_id)
);

alter table public.pricing_rules enable row level security;
create index if not exists pricing_rules_price_list_idx on public.pricing_rules (for_price_list, merchant_id);

-- What a rule applies on: exactly one of the three per row. public.save_pricing_rule keeps only the kind the
-- rule's Apply On names.
create table if not exists public.pricing_rule_targets (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  pricing_rule_id uuid not null,
  idx integer not null,
  item_id uuid,
  item_group_id uuid,
  brand_id uuid,

  constraint pricing_rule_targets_one check (num_nonnulls(item_id, item_group_id, brand_id) = 1),
  constraint pricing_rule_targets_rule_fk foreign key (pricing_rule_id, merchant_id)
    references public.pricing_rules (id, merchant_id) on delete cascade,
  constraint pricing_rule_targets_item_fk foreign key (item_id, merchant_id) references public.items (id, merchant_id),
  constraint pricing_rule_targets_item_group_fk foreign key (item_group_id, merchant_id) references public.item_groups (id, merchant_id),
  constraint pricing_rule_targets_brand_fk foreign key (brand_id, merchant_id) references public.brands (id, merchant_id)
);

alter table public.pricing_rule_targets enable row level security;
create index if not exists pricing_rule_targets_rule_idx on public.pricing_rule_targets (pricing_rule_id, merchant_id);
create index if not exists pricing_rule_targets_item_idx on public.pricing_rule_targets (item_id, merchant_id);
create index if not exists pricing_rule_targets_item_group_idx on public.pricing_rule_targets (item_group_id, merchant_id);
create index if not exists pricing_rule_targets_brand_idx on public.pricing_rule_targets (brand_id, merchant_id);

-- A rule with its rows, in one transaction. Security invoker: the caller's own Pricing Rule policies decide.
create or replace function public.save_pricing_rule(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_row public.pricing_rules := jsonb_populate_record(null::public.pricing_rules, payload - 'id');
begin
  if v_id is null then
    insert into public.pricing_rules (
      merchant_id, title, apply_on, min_qty, max_qty, min_amt, max_amt, valid_from, valid_upto, for_price_list, priority,
      disable, rate_or_discount, rate, discount_percentage, discount_amount
    )
    values (
      v_merchant, btrim(v_row.title), v_row.apply_on, coalesce(v_row.min_qty, 0), coalesce(v_row.max_qty, 0),
      coalesce(v_row.min_amt, 0), coalesce(v_row.max_amt, 0), v_row.valid_from, v_row.valid_upto, v_row.for_price_list,
      coalesce(v_row.priority, 1), coalesce(v_row.disable, false), v_row.rate_or_discount, coalesce(v_row.rate, 0),
      coalesce(v_row.discount_percentage, 0), coalesce(v_row.discount_amount, 0)
    )
    returning id into v_id;
  else
    update public.pricing_rules set
      title = btrim(v_row.title),
      apply_on = v_row.apply_on,
      min_qty = coalesce(v_row.min_qty, 0),
      max_qty = coalesce(v_row.max_qty, 0),
      min_amt = coalesce(v_row.min_amt, 0),
      max_amt = coalesce(v_row.max_amt, 0),
      valid_from = v_row.valid_from,
      valid_upto = v_row.valid_upto,
      for_price_list = v_row.for_price_list,
      priority = coalesce(v_row.priority, 1),
      disable = coalesce(v_row.disable, false),
      rate_or_discount = v_row.rate_or_discount,
      rate = coalesce(v_row.rate, 0),
      discount_percentage = coalesce(v_row.discount_percentage, 0),
      discount_amount = coalesce(v_row.discount_amount, 0)
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'pricing_rule_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.pricing_rule_targets where pricing_rule_id = v_id;

  -- A row of another kind than the rule's Apply On keeps nothing, and pricing_rule_targets_one refuses it.
  insert into public.pricing_rule_targets (merchant_id, pricing_rule_id, idx, item_id, item_group_id, brand_id)
  select
    v_merchant, v_id, t.ordinality,
    case when v_row.apply_on = 'Item Code' then t.item_id end,
    case when v_row.apply_on = 'Item Group' then t.item_group_id end,
    case when v_row.apply_on = 'Brand' then t.brand_id end
  from jsonb_populate_recordset(null::public.pricing_rule_targets, coalesce(payload -> 'targets', '[]'::jsonb)) with ordinality as t;

  return v_id;
end;
$$;

revoke execute on function public.save_pricing_rule(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_pricing_rule(jsonb) to authenticated;

-- ERPNext's matrix for Pricing Rule: the selling managers keep it; a cashier reads it, because the Register
-- applies it on the device; an Accounts Manager reads it.
insert into public.doctypes (name, table_name, kind, restrictable)
values ('Pricing Rule', 'pricing_rules', 'record', false)
on conflict (name) do nothing;

insert into public.standard_role_permissions (role_name, doctype, can_select, can_read, can_write, can_create, can_delete)
values
  ('Sales Manager', 'Pricing Rule', true, true, true, true, true),
  ('Sales Master Manager', 'Pricing Rule', true, true, true, true, true),
  ('Sales User', 'Pricing Rule', true, true, false, false, false),
  ('Accounts Manager', 'Pricing Rule', true, true, false, false, false)
on conflict (role_name, doctype) do nothing;

select private.sync_standard_permissions();

select private.apply_doctype_policies('pricing_rules', 'Pricing Rule');
select private.apply_doctype_policies('pricing_rule_targets', 'Pricing Rule', true);


-- ===== 20261012085548_pos_invoice_discounts.sql =====

-- Step 20 of the ERPNext rebuild, part 2 — the discounted sale
-- (.claude/erpnext-docs/POS-System-Added-Features.md 20.1–20.5; docs.frappe.io/erpnext/applying-discount,
-- /pricing-rule, /discount_accounting): a line's discount against its Price List Rate, an additional discount
-- on the whole sale, the guards on both, a Pricing Rule's price, and Discount Accounting.
-- 20261012085121_discounts.sql holds what these read.

create schema if not exists private;


-- 1. What a sale keeps of its discounts — ERPNext's fields.

alter table public.pos_invoices
  -- What the additional discount was taken from.
  add column if not exists apply_discount_on text not null default 'Grand Total',
  add column if not exists additional_discount_percentage numeric not null default 0,
  -- The additional discount itself; below zero on a return.
  add column if not exists discount_amount numeric not null default 0,
  -- Filled on submit, under Discount Accounting: where that discount posted. Empty: it only reduced the sale.
  add column if not exists additional_discount_account uuid;

alter table public.pos_invoices drop constraint if exists pos_invoices_discount;
alter table public.pos_invoices add constraint pos_invoices_discount check (
  apply_discount_on in ('Grand Total', 'Net Total') and additional_discount_percentage between 0 and 100
  and (case when is_return then discount_amount <= 0 else discount_amount >= 0 end)
);
alter table public.pos_invoices drop constraint if exists pos_invoices_discount_account_fk;
alter table public.pos_invoices add constraint pos_invoices_discount_account_fk
  foreign key (additional_discount_account, merchant_id) references public.accounts (id, merchant_id);
create index if not exists pos_invoices_discount_account_idx on public.pos_invoices (additional_discount_account, merchant_id);

alter table public.pos_invoice_items
  -- Per unit, against the Price List Rate: rate = price_list_rate - discount_amount. On a return too.
  add column if not exists discount_percentage numeric not null default 0,
  add column if not exists discount_amount numeric not null default 0,
  -- The line's share of the sale's additional discount, already out of its net amount; below zero on a return.
  add column if not exists distributed_discount_amount numeric not null default 0,
  -- The Pricing Rule that priced the line. Empty: the list's price, or a discount typed at the register.
  add column if not exists pricing_rule_id uuid,
  -- Filled on submit, under Discount Accounting: where the line's own discount posted.
  add column if not exists discount_account uuid;

alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_discount;
alter table public.pos_invoice_items add constraint pos_invoice_items_discount
  check (discount_percentage between 0 and 100 and discount_amount >= 0);
alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_pricing_rule_fk;
alter table public.pos_invoice_items add constraint pos_invoice_items_pricing_rule_fk
  foreign key (pricing_rule_id, merchant_id) references public.pricing_rules (id, merchant_id);
alter table public.pos_invoice_items drop constraint if exists pos_invoice_items_discount_account_fk;
alter table public.pos_invoice_items add constraint pos_invoice_items_discount_account_fk
  foreign key (discount_account, merchant_id) references public.accounts (id, merchant_id);
create index if not exists pos_invoice_items_pricing_rule_idx on public.pos_invoice_items (pricing_rule_id, merchant_id);
create index if not exists pos_invoice_items_discount_account_idx on public.pos_invoice_items (discount_account, merchant_id);


-- 2. The door (20261012080419_pos_returns_and_voids.sql), now passing the discounts through. The two
-- discount accounts are the poster's to fill, never the payload's.

create or replace function public.pos_checkout(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_doc public.pos_invoices := jsonb_populate_record(null::public.pos_invoices, payload);
begin
  insert into public.pos_invoices (
    merchant_id, posting_date, pos_profile_id, pos_opening_entry_id, taxes_and_charges, net_total, total_taxes_and_charges,
    grand_total, rounding_adjustment, rounded_total, paid_amount, change_amount, write_off_amount, is_return, return_against,
    apply_discount_on, additional_discount_percentage, discount_amount
  )
  values (
    v_merchant, private.merchant_today(v_merchant), v_doc.pos_profile_id, v_doc.pos_opening_entry_id, v_doc.taxes_and_charges,
    coalesce(v_doc.net_total, 0), coalesce(v_doc.total_taxes_and_charges, 0), coalesce(v_doc.grand_total, 0),
    coalesce(v_doc.rounding_adjustment, 0), coalesce(v_doc.rounded_total, 0), coalesce(v_doc.paid_amount, 0),
    coalesce(v_doc.change_amount, 0), coalesce(v_doc.write_off_amount, 0), v_doc.return_against is not null, v_doc.return_against,
    coalesce(v_doc.apply_discount_on, 'Grand Total'), coalesce(v_doc.additional_discount_percentage, 0),
    coalesce(v_doc.discount_amount, 0)
  )
  returning id into v_id;

  insert into public.pos_invoice_items (
    merchant_id, pos_invoice_id, idx, item_id, qty, uom_id, conversion_factor, stock_qty, price_list_rate, rate, amount,
    net_rate, net_amount, item_tax_template_id, return_against_item,
    discount_percentage, discount_amount, distributed_discount_amount, pricing_rule_id
  )
  select
    v_merchant, v_id, t.ordinality, t.item_id, t.qty, t.uom_id, t.conversion_factor, t.stock_qty, coalesce(t.price_list_rate, 0),
    t.rate, t.amount, t.net_rate, t.net_amount, t.item_tax_template_id, t.return_against_item,
    coalesce(t.discount_percentage, 0), coalesce(t.discount_amount, 0), coalesce(t.distributed_discount_amount, 0), t.pricing_rule_id
  from jsonb_populate_recordset(null::public.pos_invoice_items, coalesce(payload -> 'items', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_taxes (
    merchant_id, pos_invoice_id, idx, charge_type, account_head, description, rate, row_id, included_in_print_rate, cost_center,
    tax_amount, total, item_wise_tax_detail
  )
  select
    v_merchant, v_id, t.ordinality, t.charge_type, t.account_head, t.description, coalesce(t.rate, 0), t.row_id,
    coalesce(t.included_in_print_rate, false), t.cost_center, coalesce(t.tax_amount, 0), coalesce(t.total, 0),
    coalesce(t.item_wise_tax_detail, '[]'::jsonb)
  from jsonb_populate_recordset(null::public.pos_invoice_taxes, coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as t;

  insert into public.pos_invoice_payments (merchant_id, pos_invoice_id, idx, mode_of_payment_id, amount)
  select v_merchant, v_id, t.ordinality, t.mode_of_payment_id, t.amount
  from jsonb_populate_recordset(null::public.pos_invoice_payments, coalesce(payload -> 'payments', '[]'::jsonb)) with ordinality as t;

  perform public.submit_document('POS Invoice', v_id);
  return v_id;
end;
$$;

revoke execute on function public.pos_checkout(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.pos_checkout(jsonb) to authenticated;


-- 3. The poster. The sale, and the return of one, as 20261012080419 left it — plus the discounts.
--
-- ponytail: a sale's tax amounts, each line's net amount and its Price List Rate are trusted from the app —
-- the invoice stores the template and its rows as applied, so a query can re-run them — and so is the share
-- of a Grand Total discount each line took. Upgrade path: port taxes_and_totals and the price lookup to SQL.
-- ponytail: of a Pricing Rule, the poster checks that the rule a line claims covers it and gives its rate.
-- Which rule wins among several stays the app's (src/features/pricing-rules/apply.ts); a second ranking
-- engine in SQL is the upgrade.
-- A return trusts nothing: every figure of it is the sale's own, taken by share.
create or replace function private.submit_pos_invoices(p_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc public.pos_invoices;
  v_profile public.pos_profiles;
  v_company public.merchants;
  v_session public.pos_opening_entries;
  -- The sale a return is made against.
  v_original public.pos_invoices;
  v_rule public.pricing_rules;
  v_row record;
  v_today date;
  v_precision integer;
  -- One unit of the currency's smallest decimal: what two roundings of the same figure may differ by.
  v_unit numeric;
  v_price_list uuid;
  v_auto_price boolean;
  v_validate_price boolean;
  v_discount_accounting boolean;
  v_warehouse uuid;
  v_inventory uuid;
  v_income uuid;
  v_expense uuid;
  v_center uuid;
  -- Where a line's own discount posts, and the sale's additional one. Null: it only reduces the sale.
  v_discount_account uuid;
  v_additional_account uuid;
  v_cost numeric;
  v_item_discount numeric;
  v_additional numeric;
  v_rows integer := 0;
  v_tax_rows integer := 0;
  v_net numeric := 0;
  v_distributed numeric := 0;
  v_tax numeric := 0;
  v_paid numeric := 0;
  v_change numeric := 0;
  v_write_off numeric := 0;
  v_gl jsonb := '[]'::jsonb;
begin
  select * into v_doc from public.pos_invoices d where d.id = p_id;
  select * into v_profile from public.pos_profiles p where p.id = v_doc.pos_profile_id;
  select * into v_company from public.merchants m where m.id = v_doc.merchant_id;
  select * into v_session from public.pos_opening_entries s where s.id = v_doc.pos_opening_entry_id;
  v_today := private.merchant_today(v_doc.merchant_id);
  select s.currency_precision into v_precision from public.system_settings s where s.merchant_id = v_doc.merchant_id;
  v_precision := coalesce(v_precision, 2);
  v_unit := 1 / power(10::numeric, v_precision);

  -- "No sale without an open session": the caller's own, on this profile. A refund comes out of that drawer.
  if v_doc.user_id is distinct from (select auth.uid())
    or v_session.docstatus is distinct from 1 or v_session.status is distinct from 'Open'
    or v_session.user_id is distinct from (select auth.uid())
    or v_session.pos_profile_id is distinct from v_doc.pos_profile_id then
    raise exception 'no_open_session' using errcode = '23514', detail = 'A sale needs the cashier''s own open session on that POS Profile.';
  end if;
  if not private.pos_profile_usable(v_doc.pos_profile_id) then
    raise exception 'pos_profile_unusable' using errcode = '23514', detail = 'The POS Profile is disabled, or not applicable for this user.';
  end if;

  -- 19.1: "the original Delivery Note or Sales Invoice is submitted". Locked: two returns cannot both take
  -- the last unit, and a void of the sale waits for this one.
  if v_doc.is_return then
    select * into v_original from public.pos_invoices o where o.id = v_doc.return_against for update;
    if v_original.docstatus is distinct from 1 or v_original.is_return then
      raise exception 'return_original_invalid' using errcode = '23514',
        detail = 'A return is made against a submitted sale that is not itself a return.';
    end if;
  end if;

  -- "Stock back into the warehouse": the one it was sold from.
  v_warehouse := case when v_doc.is_return then v_original.warehouse else v_profile.warehouse end;

  select coalesce(v_profile.selling_price_list, s.default_price_list), s.validate_selling_price into v_price_list, v_validate_price
  from public.selling_settings s where s.merchant_id = v_doc.merchant_id;
  select coalesce(s.auto_insert_price_list_rate_if_missing, false) into v_auto_price
  from public.stock_settings s where s.merchant_id = v_doc.merchant_id;
  select a.enable_discount_accounting into v_discount_accounting
  from public.accounts_settings a where a.merchant_id = v_doc.merchant_id;

  if v_company.enable_perpetual_inventory then
    v_inventory := private.warehouse_account(v_warehouse);
  end if;

  -- 20.5, Discount Accounting: "additional discounts [post] to the POS Profile's, falling back to the
  -- Company's Default Discount Account". A return posts back where its sale posted.
  v_additional_account := case
    when v_doc.is_return then v_original.additional_discount_account
    when v_discount_accounting then coalesce(v_profile.discount_account, v_company.default_discount_account)
  end;

  -- 20.3, Allow User to Edit Discount.
  if not v_doc.is_return and v_doc.discount_amount > 0 and not v_profile.allow_discount_change then
    raise exception 'discount_locked' using errcode = '23514', detail = 'This POS Profile does not allow a discount on the sale.';
  end if;

  for v_row in
    select
      r.*, i.item_name as current_name, i.disabled, i.is_stock_item, i.stock_uom, i.max_discount,
      i.item_group_id as item_group, i.brand_id as brand,
      -- 13.3: POS Profile → Item → Item Group → Brand → Company.
      coalesce(v_profile.income_account, i.income_account, g.income_account, b.income_account, v_company.default_income_account) as income,
      coalesce(v_profile.expense_account, i.expense_account, g.expense_account, v_company.default_expense_account) as expense,
      coalesce(v_profile.cost_center, i.selling_cost_center, g.selling_cost_center, b.selling_cost_center, v_company.cost_center) as center,
      -- 20.5: "item discounts post to the Item's Discount Account … falling back to the Company's".
      coalesce(i.discount_account, v_company.default_discount_account) as item_discount_account,
      (select u.conversion_factor from public.item_uoms u where u.item_id = i.id and u.uom_id = r.uom_id) as unit_factor,
      -- The line of the sale a return's line takes back, and what earlier returns took of it (below zero).
      o.pos_invoice_id as o_invoice, o.item_id as o_item, o.item_name as o_name, o.uom_id as o_uom, o.conversion_factor as o_factor,
      o.qty as o_qty, o.price_list_rate as o_price_list_rate, o.rate as o_rate, o.amount as o_amount, o.net_amount as o_net_amount,
      o.income_account as o_income, o.expense_account as o_expense, o.cost_center as o_center, o.valuation_rate as o_valuation,
      o.discount_percentage as o_discount_percentage, o.discount_amount as o_discount_amount,
      o.distributed_discount_amount as o_distributed, o.pricing_rule_id as o_rule, o.discount_account as o_discount_account,
      coalesce((
        select sum(x.qty) from public.pos_invoice_items x
        join public.pos_invoices xi on xi.id = x.pos_invoice_id
        where x.return_against_item = o.id and xi.docstatus = 1
      ), 0) as o_returned
    from public.pos_invoice_items r
    join public.items i on i.id = r.item_id
    join public.item_groups g on g.id = i.item_group_id
    left join public.brands b on b.id = i.brand_id
    left join public.pos_invoice_items o on o.id = r.return_against_item
    where r.pos_invoice_id = p_id
    order by r.idx
  loop
    v_rows := v_rows + 1;

    if v_doc.is_return then
      -- "Rate: Original selling rate used to calculate the returned value." The line is the sale's own, in
      -- the unit it was sold in, under the discount it was sold at, with a quantity below zero.
      if v_row.o_invoice is distinct from v_doc.return_against or v_row.qty > 0
        or v_row.item_id <> v_row.o_item or v_row.uom_id <> v_row.o_uom or v_row.conversion_factor <> v_row.o_factor
        or v_row.rate <> v_row.o_rate or v_row.price_list_rate <> v_row.o_price_list_rate
        or abs(v_row.discount_percentage - v_row.o_discount_percentage) > 0.000001
        or v_row.discount_amount <> v_row.o_discount_amount or v_row.pricing_rule_id is distinct from v_row.o_rule
        or v_row.stock_qty <> v_row.qty * v_row.conversion_factor then
        raise exception 'return_line_invalid' using errcode = '23514',
          detail = 'A returned line names a line of the sale, with its item, unit, rate and discount, and a quantity below zero.';
      end if;
      -- "Returned quantity is rejected: confirm it does not exceed the quantity available to return."
      if -v_row.qty > v_row.o_qty + v_row.o_returned then
        raise exception 'return_qty_exceeds' using errcode = '23514',
          detail = format('%s sold, %s already returned.', v_row.o_qty, -v_row.o_returned);
      end if;
      if abs(v_row.amount - v_row.o_amount * v_row.qty / v_row.o_qty) > v_unit
        or abs(v_row.net_amount - v_row.o_net_amount * v_row.qty / v_row.o_qty) > v_unit
        or abs(v_row.distributed_discount_amount - v_row.o_distributed * v_row.qty / v_row.o_qty) > v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A returned line is not its share of the line sold.';
      end if;

      -- Where the sale posted, the return posts back.
      v_income := v_row.o_income;
      v_center := v_row.o_center;
      v_discount_account := v_row.o_discount_account;
    else
      if v_row.qty < 0 or v_row.return_against_item is not null then
        raise exception 'return_line_invalid' using errcode = '23514', detail = 'A sale''s lines are sold, not returned.';
      end if;
      if v_row.disabled then
        raise exception 'item_unusable' using errcode = '23514', detail = 'A disabled item cannot be sold.';
      end if;
      -- 13.4: sold in the stock unit, or in one of the item's units at its conversion factor.
      if v_row.conversion_factor is distinct from (case when v_row.uom_id = v_row.stock_uom then 1 else v_row.unit_factor end)
        or v_row.stock_qty <> v_row.qty * v_row.conversion_factor then
        raise exception 'uom_not_on_item' using errcode = '23514', detail = 'A line is sold in a unit its item does not have, or at another conversion factor.';
      end if;
      -- 20.1: "calculated against the Price List Rate". The discount is what the rate is under the list's,
      -- per unit, and the percentage says the same; a typed lower rate is a discount too.
      if abs(v_row.discount_amount - greatest(v_row.price_list_rate - v_row.rate, 0)) > v_unit
        or abs(v_row.discount_amount - v_row.price_list_rate * v_row.discount_percentage / 100) > v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A line''s discount is not its Price List Rate less its rate.';
      end if;
      if abs(v_row.amount - v_row.qty * v_row.rate) > v_unit or v_row.net_amount < 0 or v_row.distributed_discount_amount < 0
        or v_row.net_amount + v_row.distributed_discount_amount > v_row.amount + v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A line''s amount is not its quantity times its rate.';
      end if;

      if v_row.pricing_rule_id is not null then
        -- 20.4: the rule the line claims is enabled, valid today, for this price list, covers the item — by
        -- itself, its brand, or its item group or one above it — within its quantity and amount, and gives
        -- this rate. "POS Profile Ignore Pricing Rule switches it off for a register."
        select * into v_rule from public.pricing_rules p where p.id = v_row.pricing_rule_id;
        if v_profile.ignore_pricing_rule or v_rule.disable is distinct from false
          or v_rule.valid_from > v_today or v_rule.valid_upto < v_today
          or (v_rule.for_price_list is not null and v_rule.for_price_list is distinct from v_price_list)
          or v_row.stock_qty < v_rule.min_qty or (v_rule.max_qty > 0 and v_row.stock_qty > v_rule.max_qty)
          or v_row.qty * v_row.price_list_rate < v_rule.min_amt
          or (v_rule.max_amt > 0 and v_row.qty * v_row.price_list_rate > v_rule.max_amt)
          or not exists (
            select 1 from public.pricing_rule_targets t
            where t.pricing_rule_id = v_rule.id
              and (t.item_id = v_row.item_id or t.brand_id = v_row.brand or t.item_group_id in (
                with recursive up as (
                  select g.id, g.parent_id from public.item_groups g where g.id = v_row.item_group
                  union all
                  select g.id, g.parent_id from public.item_groups g join up on g.id = up.parent_id
                )
                select up.id from up
              ))
          )
          or abs(v_row.rate - case v_rule.rate_or_discount
            when 'Rate' then v_rule.rate * v_row.conversion_factor
            when 'Discount Percentage' then v_row.price_list_rate * (1 - v_rule.discount_percentage / 100)
            else greatest(v_row.price_list_rate - v_rule.discount_amount, 0)
          end) > v_unit then
          raise exception 'pricing_rule_mismatch' using errcode = '23514', detail = 'A line''s Pricing Rule does not apply to it, or gives another rate.';
        end if;
      elsif v_row.rate > v_row.price_list_rate and not v_profile.allow_rate_change then
        raise exception 'rate_locked' using errcode = '23514', detail = 'This POS Profile does not allow a line''s rate to be changed.';
      elsif v_row.discount_amount > 0 and not (v_profile.allow_discount_change or v_profile.allow_rate_change) then
        -- 20.3, Allow User to Edit Discount.
        raise exception 'discount_locked' using errcode = '23514', detail = 'This POS Profile does not allow a discount on a line.';
      end if;
      -- 20.3, Item Max Discount (%), whoever gave the discount.
      if v_row.max_discount > 0 and v_row.discount_percentage > v_row.max_discount then
        raise exception 'max_discount_exceeded' using errcode = '23514',
          detail = format('%s takes at most %s%%.', v_row.current_name, v_row.max_discount);
      end if;

      v_income := v_row.income;
      v_center := v_row.center;
      v_discount_account := case when v_discount_accounting then v_row.item_discount_account end;
    end if;

    v_net := v_net + v_row.net_amount;
    v_distributed := v_distributed + v_row.distributed_discount_amount;
    v_expense := null;
    v_cost := null;

    -- 20.5, Discount Accounting: "Sales shows the full price." Each discount is debited to its account net
    -- of tax and income credited by as much more, so the taxes stay what the customer was charged.
    -- Rejected: ERPNext's Grand Total variant, which credits tax at the amount before the discount.
    -- With no account for it, a discount only reduces the sale.
    v_item_discount := case when v_discount_account is null then 0 else round(
      v_row.qty * v_row.discount_amount
        * case when v_row.amount = 0 then 1 else (v_row.net_amount + v_row.distributed_discount_amount) / v_row.amount end,
      v_precision) end;
    v_additional := case when v_additional_account is null then 0 else v_row.distributed_discount_amount end;
    v_gl := v_gl
      || jsonb_build_object('account_id', v_income, 'amount', -(v_row.net_amount + v_item_discount + v_additional), 'cost_center_id', v_center)
      || jsonb_build_object('account_id', v_discount_account, 'amount', v_item_discount, 'cost_center_id', v_center)
      || jsonb_build_object('account_id', v_additional_account, 'amount', v_additional, 'cost_center_id', v_center);

    -- "Posts at once: stock out and Cost of Goods Sold." A service moves no stock. Negative stock, a
    -- fraction in a whole-number unit and a backdated posting are the engine's to refuse. A return brings
    -- back what the sale moved, at the valuation it left at.
    if (v_doc.is_return and v_row.o_valuation is not null) or (not v_doc.is_return and v_row.is_stock_item) then
      v_cost := -private.post_sle(
        v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_row.item_id, v_warehouse, -v_row.stock_qty,
        case when v_doc.is_return then v_row.o_valuation end
      );
      -- 20.3, Selling Settings' Validate Selling Price: the line sells for no less than it is valued at.
      if not v_doc.is_return and v_validate_price and v_row.net_amount < v_cost - v_unit then
        raise exception 'below_valuation' using errcode = '23514',
          detail = format('%s sells for %s and is valued at %s.', v_row.current_name, v_row.net_amount, v_cost);
      end if;
      if v_company.enable_perpetual_inventory then
        if v_inventory is null then
          raise exception 'no_inventory_account' using errcode = '23514',
            detail = 'Neither the warehouse, its parents nor the Company names an inventory account.';
        end if;
        v_expense := case when v_doc.is_return then coalesce(v_row.o_expense, v_row.expense) else v_row.expense end;
        v_gl := v_gl
          || jsonb_build_object('account_id', v_expense, 'amount', v_cost, 'cost_center_id', v_center)
          || jsonb_build_object('account_id', v_inventory, 'amount', -v_cost);
      end if;
    end if;

    update public.pos_invoice_items r set
      item_name = case when v_doc.is_return then v_row.o_name else v_row.current_name end,
      income_account = v_income, expense_account = v_expense, cost_center = v_center,
      discount_account = case when v_item_discount <> 0 then v_discount_account end,
      valuation_rate = v_cost / v_row.stock_qty
    where r.id = v_row.id;

    -- 14.1, Stock Settings' Auto Insert Price List Rate if Missing: the item's first sale in this unit
    -- writes its rate into the sale's price list.
    if not v_doc.is_return and v_auto_price and v_row.price_list_rate > 0
      and exists (select 1 from public.price_lists p where p.id = v_price_list and p.enabled)
      and not exists (
        select 1 from public.item_prices p
        where p.item_id = v_row.item_id and p.price_list_id = v_price_list and p.uom_id = v_row.uom_id
      ) then
      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_doc.merchant_id, v_row.item_id, v_price_list, v_row.uom_id, v_row.price_list_rate);
    end if;
  end loop;

  if v_rows = 0 then
    raise exception 'no_rows' using errcode = '23514', detail = 'A sale needs at least one item.';
  end if;

  for v_row in
    select
      t.*, o.account_head as o_account,
      -- The sale's row, line by line, for the share of each line this return takes back.
      (
        select sum((o.item_wise_tax_detail ->> (l.pos - 1))::numeric * r.qty / l.qty)
        from public.pos_invoice_items r
        join (
          select x.id, x.qty, (row_number() over (order by x.idx))::integer as pos
          from public.pos_invoice_items x where x.pos_invoice_id = v_doc.return_against
        ) l on l.id = r.return_against_item
        where r.pos_invoice_id = p_id
      ) as o_share
    from public.pos_invoice_taxes t
    left join public.pos_invoice_taxes o on o.pos_invoice_id = v_doc.return_against and o.idx = t.idx
    where t.pos_invoice_id = p_id
    order by t.idx
  loop
    v_tax_rows := v_tax_rows + 1;

    if v_doc.is_return then
      if v_row.o_account is distinct from v_row.account_head or abs(v_row.tax_amount - coalesce(v_row.o_share, 0)) > v_unit then
        raise exception 'totals_mismatch' using errcode = '23514', detail = 'A returned tax is not its share of the tax charged.';
      end if;
    elsif jsonb_array_length(v_row.item_wise_tax_detail) <> v_rows
      or abs(v_row.tax_amount - coalesce((select sum(d.value::numeric) from jsonb_array_elements_text(v_row.item_wise_tax_detail) as d (value)), 0)) > v_unit then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A tax row''s amounts per line do not add up to it.';
    end if;

    v_tax := v_tax + v_row.tax_amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.account_head, 'amount', -v_row.tax_amount, 'cost_center_id', v_row.cost_center);
  end loop;

  if v_doc.is_return and v_tax_rows <> (select count(*) from public.pos_invoice_taxes o where o.pos_invoice_id = v_doc.return_against) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'A return carries every tax row of its sale.';
  end if;

  -- 20.2: the additional discount. Its lines' shares are all of it when it was taken from the Net Total,
  -- and the net part of it from the Grand Total (the rest is tax); a percentage is of that total before it.
  -- A return's is the share of the sale's that its lines took.
  if v_doc.is_return then
    if v_doc.apply_discount_on <> v_original.apply_discount_on
      or v_doc.additional_discount_percentage <> v_original.additional_discount_percentage
      or abs(v_doc.discount_amount - coalesce(v_original.discount_amount * v_distributed / nullif((
        select sum(o.distributed_discount_amount) from public.pos_invoice_items o where o.pos_invoice_id = v_doc.return_against
      ), 0), 0)) > v_unit then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A return''s discount is not its share of the sale''s.';
    end if;
  elsif v_distributed > v_doc.discount_amount + v_unit
    or (v_doc.apply_discount_on = 'Net Total' and abs(v_distributed - v_doc.discount_amount) > v_unit)
    or (v_doc.additional_discount_percentage > 0 and abs(v_doc.discount_amount - v_doc.additional_discount_percentage / 100
      * case when v_doc.apply_discount_on = 'Net Total' then v_net + v_distributed else v_doc.grand_total + v_doc.discount_amount end) > v_unit) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'The additional discount does not add up.';
  end if;

  -- The totals add up. An inclusive tax, or a discount off the Grand Total, can leave the grand total a few
  -- units off net + tax (the entered prices are kept); the Rounded Total is the grand total at the
  -- currency's smallest coin, or itself.
  if abs(v_doc.net_total - v_net) > v_unit or abs(v_doc.total_taxes_and_charges - v_tax) > v_unit
    or abs(v_doc.grand_total - v_net - v_tax) > 5 * v_unit
    or abs(v_doc.rounding_adjustment - (v_doc.rounded_total - v_doc.grand_total)) > v_unit
    or abs(v_doc.rounding_adjustment) > greatest(1, coalesce((
      select c.smallest_currency_fraction_value from public.currencies c
      where c.merchant_id = v_doc.merchant_id and c.code = v_company.default_currency
    ), 0)) then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'The sale''s totals do not add up.';
  end if;

  -- "Only the modes set here will be available when using POS", and for a refund only those with
  -- "Allow in Returns".
  for v_row in
    select r.id, r.amount, m.default_account, pp.id as offered, pp.allow_in_returns
    from public.pos_invoice_payments r
    join public.modes_of_payment m on m.id = r.mode_of_payment_id
    left join public.pos_profile_payments pp on pp.pos_profile_id = v_doc.pos_profile_id and pp.mode_of_payment_id = r.mode_of_payment_id
    where r.pos_invoice_id = p_id
  loop
    if v_row.offered is null then
      raise exception 'payment_method_not_offered' using errcode = '23514', detail = 'The POS Profile does not offer that mode of payment.';
    end if;
    if v_doc.is_return and not v_row.allow_in_returns then
      raise exception 'refund_method_not_allowed' using errcode = '23514', detail = 'That mode of payment is not marked Allow in Returns on the POS Profile.';
    end if;
    if (v_row.amount < 0) is distinct from v_doc.is_return then
      raise exception 'totals_mismatch' using errcode = '23514', detail = 'A sale is paid in; a return is paid out.';
    end if;
    v_paid := v_paid + v_row.amount;
    v_gl := v_gl || jsonb_build_object('account_id', v_row.default_account, 'amount', v_row.amount);
    update public.pos_invoice_payments r set account = v_row.default_account where r.id = v_row.id;
  end loop;

  if v_doc.is_return then
    -- The refund is the whole of the return: nothing to hand back, nothing to write off.
    if abs(v_paid - v_doc.rounded_total) > v_unit then
      raise exception 'refund_mismatch' using errcode = '23514', detail = 'The refund is not the return''s total.';
    end if;
  else
    -- "Paid in full, change returned, a small difference written off within the limit."
    v_change := greatest(v_paid - v_doc.rounded_total, 0);
    v_write_off := greatest(v_doc.rounded_total - v_paid, 0);
    if v_write_off > v_profile.write_off_limit then
      raise exception 'underpaid' using errcode = '23514', detail = 'The payments do not cover the total, and the shortfall is over the Write Off Limit.';
    end if;
  end if;
  if abs(v_doc.paid_amount - v_paid) > v_unit or abs(v_doc.change_amount - v_change) > v_unit
    or abs(v_doc.write_off_amount - v_write_off) > v_unit then
    raise exception 'totals_mismatch' using errcode = '23514', detail = 'Paid, change and write-off do not match the payments.';
  end if;

  v_gl := v_gl
    -- Change goes back out of the till.
    || jsonb_build_object('account_id', coalesce(v_profile.account_for_change_amount, v_company.default_cash_account), 'amount', -v_change)
    || jsonb_build_object(
      'account_id', coalesce(v_profile.write_off_account, v_company.write_off_account), 'amount', v_write_off,
      'cost_center_id', coalesce(v_profile.write_off_cost_center, v_company.cost_center))
    -- What rounding added or took: the Rounded Total less net and taxes.
    || jsonb_build_object(
      'account_id', v_company.round_off_account, 'amount', -(v_doc.rounded_total - v_net - v_tax),
      'cost_center_id', coalesce(v_company.round_off_cost_center, v_company.cost_center));

  -- An account still missing here is refused by private.post_gl (account_unusable), as an unbalanced voucher is.
  perform private.post_gl(v_doc.merchant_id, 'POS Invoice', p_id, v_doc.name, v_today, v_gl);

  update public.pos_invoices set
    posting_date = v_today,
    warehouse = v_warehouse,
    selling_price_list = case when v_doc.is_return then v_original.selling_price_list else v_price_list end,
    tax_category = case when v_doc.is_return then v_original.tax_category else v_profile.tax_category end,
    additional_discount_account = case when v_doc.discount_amount <> 0 then v_additional_account end
  where id = p_id;
end;
$$;

revoke execute on function private.submit_pos_invoices(uuid) from public, anon, authenticated, service_role;


-- ===== 20261012131350_access_for_documents.sql =====

-- Step 21 of the POS system, on ERPNext's model: Access for the New Documents
-- (.claude/erpnext-docs/POS-System-Added-Features.md 21.1–21.2; docs.frappe.io/erpnext/user-permissions,
-- /role-based-permissions).
--
-- 21.1 was laid with each step: every document type of Steps 13–20 has its rules, with Submit and Cancel
-- (20261011165554_ledgers.sql). Nothing here changes a rule.
--
-- 21.2 is this file. A User Permission holds a person to one record of a restrictable doctype — a Warehouse,
-- an Item Group, an Account, a Cost Center. Until now that filtered the master itself and nothing else. The
-- docs: "User Permissions can be used to restrict access to select documents based on the link fields in the
-- document", and Applicable For makes one "applicable only under the selected Document Type". So:
--
-- 1. public.doctype_links: which document types link to a restrictable doctype, and through which column.
-- 2. private.restricted_merchant_ids() and private.allowed_record_ids() take the document type the question
--    is asked for, so Apply To All Document Types and Applicable For both answer.
-- 3. private.apply_doctype_policies() writes the link into every policy of a linking table, and holds a
--    linking document's rows to the documents the person may see.
-- 4. A User Permission's Applicable For must be a document type that links to its Allow.
--
-- The human's decision of 2026-10-12: documents and ledgers follow their own link, and so do the two records
-- that belong to one — an Item to its Item Group, a POS Profile to its Warehouse. A default on a master (an
-- Item's Default Warehouse, a Tax Rule's Item Group, the Company's accounts) restricts nothing — ERPNext's
-- "Ignore User Permissions" on a field — or a cashier held to one warehouse would lose the prices and taxes
-- the Register needs.
--
-- Known ceilings (ponytail): a Stock Reconciliation names its warehouses on its rows, so it follows no link
-- (only a Stock Manager holds it); and the rows of a restrictable master (an Item Group's Item Tax rows) stay
-- readable by whoever may read the doctype, as Step 11 left them.
-- Re-runnable, like the rest of supabase/migrations.

create schema if not exists private;


-- 1. The links. Global and read-only, like public.doctypes: only a migration writes it.

create table if not exists public.doctype_links (
  -- The document type whose rows are restricted,
  doctype text not null references public.doctypes (name) on delete cascade,
  -- the restrictable doctype one of its fields links to,
  link_doctype text not null references public.doctypes (name) on delete cascade,
  -- and that field: a column of the doctype's table.
  column_name text not null,

  primary key (doctype, column_name)
);

alter table public.doctype_links enable row level security;
create index if not exists doctype_links_link_doctype_idx on public.doctype_links (link_doctype);

drop policy if exists doctype_links_select on public.doctype_links;
create policy doctype_links_select on public.doctype_links
  for select to authenticated
  using (true);

insert into public.doctype_links (doctype, link_doctype, column_name)
values
  ('GL Entry', 'Account', 'account_id'),
  ('GL Entry', 'Cost Center', 'cost_center_id'),
  ('Stock Ledger Entry', 'Warehouse', 'warehouse_id'),
  ('Bin', 'Warehouse', 'warehouse_id'),
  ('Stock Entry', 'Warehouse', 'from_warehouse'),
  ('Stock Entry', 'Warehouse', 'to_warehouse'),
  ('POS Invoice', 'Warehouse', 'warehouse'),
  ('POS Profile', 'Warehouse', 'warehouse'),
  ('Item', 'Item Group', 'item_group_id')
on conflict (doctype, column_name) do nothing;


-- 2. The two questions a policy asks, now for one document type: `p_allow` is the restrictable doctype,
-- `p_applicable` the document type being read — the same doctype for the master itself. A User Permission
-- answers when it applies to all document types, or names that one as Applicable For.

-- The systems where a User Permission on `p_allow` restricts the caller under `p_applicable`. The owner has
-- no member row, so is never in it.
create or replace function private.restricted_merchant_ids(p_allow text, p_applicable text)
returns setof uuid
language sql
security definer
stable
set search_path = ''
as $$
  select distinct mm.merchant_id
  from public.user_permissions up
  join public.merchant_members mm on mm.id = up.member_id
  where mm.user_id = (select auth.uid())
    and mm.enabled
    and up.allow = p_allow
    and (up.apply_to_all_doctypes or up.applicable_for = p_applicable);
$$;

revoke execute on function private.restricted_merchant_ids(text, text) from public, anon, authenticated, service_role;
grant execute on function private.restricted_merchant_ids(text, text) to authenticated;

-- The records of `p_allow` those User Permissions allow: each For Value, and on a tree doctype its
-- descendants too unless Hide Descendants is on. The table name comes from the registry, quoted with %I.
create or replace function private.allowed_record_ids(p_allow text, p_applicable text)
returns setof uuid
language plpgsql
security definer
stable
set search_path = ''
as $$
declare
  v_table text;
  v_kind text;
begin
  select d.table_name, d.kind into v_table, v_kind from public.doctypes d where d.name = p_allow;

  if v_kind = 'tree' then
    return query execute format(
      'with recursive granted as (
         select up.for_value, up.hide_descendants
         from public.user_permissions up
         join public.merchant_members mm on mm.id = up.member_id
         where mm.user_id = $1 and mm.enabled and up.allow = $2
           and (up.apply_to_all_doctypes or up.applicable_for = $3)
       ),
       descendants (id) as (
         select g.for_value from granted g where not g.hide_descendants
         union
         select c.id from public.%I c join descendants d on c.parent_id = d.id
       )
       select g.for_value from granted g
       union
       select d.id from descendants d',
      v_table
    ) using (select auth.uid()), p_allow, p_applicable;
  else
    return query
      select up.for_value
      from public.user_permissions up
      join public.merchant_members mm on mm.id = up.member_id
      where mm.user_id = (select auth.uid()) and mm.enabled and up.allow = p_allow
        and (up.apply_to_all_doctypes or up.applicable_for = p_applicable);
  end if;
end;
$$;

revoke execute on function private.allowed_record_ids(text, text) from public, anon, authenticated, service_role;
grant execute on function private.allowed_record_ids(text, text) to authenticated;


-- 3. The policy helper (20261011165554_ledgers.sql), with the links.
-- A restrictable master: the person's allowed records of it, as before.
-- A linking table: for each link column, the system is not one where the person is restricted on the linked
--   doctype under this document type, or the column is empty, or it holds an allowed record. On insert too —
--   a person held to one warehouse cannot write a document for another.
-- A linking document's rows: only those of a document the person may see. The parent's own policies answer
--   the `exists`, so a row never outlives its document's visibility.
create or replace function private.apply_doctype_policies(p_table text, p_doctype text, p_child boolean default false)
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_kind text;
  v_parent text;
  v_restrictable boolean;
  -- What limits the rows a person may see or change, and the part of it a new row can be held to.
  v_restrict text := '';
  v_check text := '';
  v_cmd text;
  v_key text;
  v_link record;
begin
  select d.kind, d.restrictable, d.table_name into v_kind, v_restrictable, v_parent from public.doctypes d where d.name = p_doctype;
  if v_kind is null then
    raise exception 'unknown doctype %', p_doctype;
  end if;

  foreach v_cmd in array array['select', 'insert', 'update', 'delete'] loop
    execute format('drop policy if exists %I on public.%I', p_table || '_' || v_cmd, p_table);
  end loop;

  if p_child then
    -- This table's key to its document: the column of its foreign key to the doctype's table.
    select a.attname into v_key
    from pg_catalog.pg_constraint c
    join pg_catalog.pg_attribute a on a.attrelid = c.conrelid and a.attnum = any (c.conkey)
    where c.contype = 'f'
      and c.conrelid = format('public.%I', p_table)::regclass
      and c.confrelid = format('public.%I', v_parent)::regclass
      and a.attname <> 'merchant_id';

    if exists (select 1 from public.doctype_links l where l.doctype = p_doctype) then
      if v_key is null then
        raise exception '% has no foreign key to %', p_table, v_parent;
      end if;
      v_check := format(' and exists (select 1 from public.%I p where p.id = %I.%I)', v_parent, p_table, v_key);
      v_restrict := v_check;
    end if;
  else
    for v_link in
      select l.link_doctype, l.column_name from public.doctype_links l where l.doctype = p_doctype order by l.column_name
    loop
      v_check := v_check || format(
        ' and (merchant_id not in (select private.restricted_merchant_ids(%L, %L)) or %I is null or %I in (select private.allowed_record_ids(%L, %L)))',
        v_link.link_doctype, p_doctype, v_link.column_name, v_link.column_name, v_link.link_doctype, p_doctype
      );
    end loop;

    if v_restrictable then
      v_restrict := format(
        ' and (merchant_id not in (select private.restricted_merchant_ids(%L, %L)) or id in (select private.allowed_record_ids(%L, %L)))',
        p_doctype, p_doctype, p_doctype, p_doctype
      );
    end if;
    v_restrict := v_restrict || v_check;
  end if;

  execute format(
    'create policy %I on public.%I for select to authenticated using (merchant_id in (select private.permitted_merchant_ids(%L, %L))%s)',
    p_table || '_select', p_table, p_doctype, case when p_child then 'read' else 'select' end, v_restrict
  );

  if v_kind = 'ledger' then
    return;
  end if;

  execute format(
    'create policy %I on public.%I for update to authenticated
       using (merchant_id in (select private.permitted_merchant_ids(%L, ''write''))%s)
       with check (merchant_id in (select private.permitted_merchant_ids(%L, ''write''))%s)',
    p_table || '_update', p_table, p_doctype, v_restrict, p_doctype, v_restrict
  );

  if v_kind = 'single' and not p_child then
    return;
  end if;

  execute format(
    'create policy %I on public.%I for insert to authenticated with check (merchant_id in (select private.permitted_merchant_ids(%L, %L))%s)',
    p_table || '_insert', p_table, p_doctype, case when p_child then 'write' else 'create' end, v_check
  );

  execute format(
    'create policy %I on public.%I for delete to authenticated using (merchant_id in (select private.permitted_merchant_ids(%L, %L))%s)',
    p_table || '_delete', p_table, p_doctype, case when p_child then 'write' else 'delete' end, v_restrict
  );

  if v_kind <> 'document' then
    return;
  end if;

  execute format('drop trigger if exists %I on public.%I', p_table || '_docstatus', p_table);

  if not p_child then
    execute format(
      'create trigger %I before insert or update or delete on public.%I for each row execute function private.guard_docstatus()',
      p_table || '_docstatus', p_table
    );
    return;
  end if;

  if v_key is null then
    raise exception '% has no foreign key to %', p_table, v_parent;
  end if;

  execute format(
    'create trigger %I before insert or update or delete on public.%I for each row execute function private.guard_docstatus_child(%L, %L)',
    p_table || '_docstatus', p_table, v_parent, v_key
  );
end;
$$;

-- Every table whose policies change: the five restrictable masters (their policies named the one-argument
-- functions dropped below), the linking tables, and the rows of the linking documents and records.
select private.apply_doctype_policies('accounts', 'Account');
select private.apply_doctype_policies('cost_centers', 'Cost Center');
select private.apply_doctype_policies('fiscal_years', 'Fiscal Year');
select private.apply_doctype_policies('item_groups', 'Item Group');
select private.apply_doctype_policies('warehouses', 'Warehouse');

select private.apply_doctype_policies('gl_entries', 'GL Entry');
select private.apply_doctype_policies('stock_ledger_entries', 'Stock Ledger Entry');
select private.apply_doctype_policies('bins', 'Bin');
select private.apply_doctype_policies('stock_entries', 'Stock Entry');
select private.apply_doctype_policies('stock_entry_items', 'Stock Entry', true);
select private.apply_doctype_policies('pos_invoices', 'POS Invoice');
select private.apply_doctype_policies('pos_invoice_items', 'POS Invoice', true);
select private.apply_doctype_policies('pos_invoice_taxes', 'POS Invoice', true);
select private.apply_doctype_policies('pos_invoice_payments', 'POS Invoice', true);
select private.apply_doctype_policies('pos_profiles', 'POS Profile');
select private.apply_doctype_policies('pos_profile_users', 'POS Profile', true);
select private.apply_doctype_policies('pos_profile_payments', 'POS Profile', true);
select private.apply_doctype_policies('pos_profile_item_groups', 'POS Profile', true);
select private.apply_doctype_policies('items', 'Item');
select private.apply_doctype_policies('item_uoms', 'Item', true);
select private.apply_doctype_policies('item_taxes', 'Item', true);

-- No policy names them any more.
drop function if exists private.restricted_merchant_ids(text);
drop function if exists private.allowed_record_ids(text);


-- 4. A User Permission names a restrictable doctype and a record of it that exists in the same system
-- (20261008145056_users_and_access.sql) — and, when it is not for all document types, an Applicable For
-- that can follow it: the doctype itself, or a document type that links to it.
create or replace function private.validate_user_permission()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_table text;
  v_kind text;
  v_restrictable boolean;
  v_exists boolean;
begin
  select d.table_name, d.kind, d.restrictable into v_table, v_kind, v_restrictable
  from public.doctypes d where d.name = new.allow;

  if not coalesce(v_restrictable, false) then
    raise exception 'not_restrictable' using errcode = '23514', detail = format('%s cannot be restricted by a User Permission.', new.allow);
  end if;

  execute format('select exists (select 1 from public.%I where id = $1 and merchant_id = $2)', v_table)
    into v_exists using new.for_value, new.merchant_id;
  if not v_exists then
    raise exception 'for_value_missing' using errcode = '23503', detail = format('No %s with that id in this system.', new.allow);
  end if;

  if new.applicable_for is not null and new.applicable_for <> new.allow
    and not exists (select 1 from public.doctype_links l where l.doctype = new.applicable_for and l.link_doctype = new.allow) then
    raise exception 'not_applicable' using errcode = '23514', detail = format('%s does not link to a %s.', new.applicable_for, new.allow);
  end if;

  if v_kind <> 'tree' then
    new.hide_descendants := false;
  end if;

  return new;
end;
$$;

revoke execute on function private.validate_user_permission() from public, anon, authenticated, service_role;


-- ===== 20261012200010_dashboard.sql =====

-- Step 22 of the POS build, on ERPNext's model: the Dashboard
-- (.claude/erpnext-docs/POS-System-Added-Features.md 22.1–22.3; docs.frappe.io/erpnext/erpnext-dashboards,
-- /sales-analytics, /stock-level-report).
--
-- 1. public.stock_alerts(): the items out of stock or at or below their Re-order Level, per warehouse.
-- 2. public.dashboard_cards(): the four number cards of a period.
-- 3. public.sales_by_day(): the sales-per-day chart.
-- 4. public.top_selling(): the Top-Selling Items list, by quantity or amount, by Item or Item Group.
--
-- No table, so no doctype, seed or backfill. Every function is security INVOKER: the caller's own policies
-- decide each row, so a role reads here what it reads in Orders, Sell and Stock Balance, and a User
-- Permission on a Warehouse or an Item Group narrows these figures as it narrows those lists
-- (20261012131350_access_for_documents.sql). Rejected: definer functions with their own permission checks —
-- a second copy of what the policies already say.
--
-- Sales is the Net Total — before tax, after discounts — as ERPNext's Sales Analytics values a sale; a return
-- is a POS Invoice below zero, so it nets by itself. Gross Profit is Sales less what the stock sold cost (each
-- line's valuation rate, kept on the line when it posted), and is answered only to whoever may also read the
-- Stock Ledger, where that cost lives. The dates are the caller's: the app works out the period in the
-- system's time zone, the day a sale is dated by (private.merchant_today).
--
-- Out of scope, so absent: custom dashboards, a saved chart or number card, targets, the projected quantity.
-- Re-runnable, like the rest of supabase/migrations.


-- 1. Stock Alerts (22.3): a bin of an enabled stock item at zero or less, or at or below the item's Re-order
-- Level when it has one. An item never stocked in a warehouse has no bin there, so it does not alert.
-- p_limit null lists every one — what the Low Stock card counts.
create or replace function public.stock_alerts(p_merchant uuid, p_limit integer default 200)
returns table (
  item_id uuid, item_code text, item_name text, warehouse_id uuid, warehouse_name text, actual_qty numeric, reorder_level numeric
)
language sql
stable
security invoker
set search_path = ''
as $$
  select t.id, t.item_code, t.item_name, w.id, w.warehouse_name, b.actual_qty, t.reorder_level
  from public.bins b
  join public.items t on t.id = b.item_id
  join public.warehouses w on w.id = b.warehouse_id
  where b.merchant_id = p_merchant
    and t.is_stock_item
    and not t.disabled
    and (b.actual_qty <= 0 or (coalesce(t.reorder_level, 0) > 0 and b.actual_qty <= t.reorder_level))
  order by b.actual_qty, t.item_code, w.warehouse_name
  limit p_limit;
$$;

revoke execute on function public.stock_alerts(uuid, integer) from public, anon, authenticated, service_role;
grant execute on function public.stock_alerts(uuid, integer) to authenticated;


-- 2. The number cards (22.1). Sales and its invoice count, and Gross Profit, are the period's; Open Registers
-- and Low Stock are as things stand now.
-- ponytail: change comes off the expected cash only for a sale with a Cash-type payment — the closing entry's
-- fallback to a sale's first payment (private.submit_pos_closing_entries) is not repeated here; a change mode
-- column on the invoice would serve both.
create or replace function public.dashboard_cards(p_merchant uuid, p_from date, p_to date)
returns table (
  sales numeric, invoices bigint, gross_profit numeric, open_registers bigint, expected_cash numeric, low_stock bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  with sold as (
    select i.id, i.net_total, i.is_return
    from public.pos_invoices i
    where i.merchant_id = p_merchant and i.docstatus = 1 and i.posting_date between p_from and p_to
  ),
  open_sessions as (
    select s.id
    from public.pos_opening_entries s
    where s.merchant_id = p_merchant and s.docstatus = 1 and s.status = 'Open'
  ),
  session_sales as (
    select i.id, i.change_amount
    from public.pos_invoices i
    where i.pos_opening_entry_id in (select o.id from open_sessions o) and i.docstatus = 1
  )
  select
    coalesce((select sum(s.net_total) from sold s), 0),
    (select count(*) from sold s where not s.is_return),
    case
      when p_merchant in (select private.permitted_merchant_ids('Stock Ledger Entry', 'read')) then
        coalesce((
          select sum(r.net_amount - coalesce(r.valuation_rate, 0) * r.stock_qty)
          from public.pos_invoice_items r
          where r.pos_invoice_id in (select s.id from sold s)
        ), 0)
    end,
    (select count(*) from open_sessions),
    coalesce((
      select sum(b.opening_amount)
      from public.pos_opening_entry_balances b
      join public.modes_of_payment m on m.id = b.mode_of_payment_id
      where b.pos_opening_entry_id in (select o.id from open_sessions o) and m.type = 'Cash'
    ), 0)
    + coalesce((
      select sum(p.amount)
      from public.pos_invoice_payments p
      join public.modes_of_payment m on m.id = p.mode_of_payment_id
      where p.pos_invoice_id in (select x.id from session_sales x) and m.type = 'Cash'
    ), 0)
    - coalesce((
      select sum(x.change_amount)
      from session_sales x
      where x.change_amount > 0 and exists (
        select 1
        from public.pos_invoice_payments p
        join public.modes_of_payment m on m.id = p.mode_of_payment_id
        where p.pos_invoice_id = x.id and m.type = 'Cash'
      )
    ), 0),
    (select count(distinct a.item_id) from public.stock_alerts(p_merchant, null) a);
$$;

revoke execute on function public.dashboard_cards(uuid, date, date) from public, anon, authenticated, service_role;
grant execute on function public.dashboard_cards(uuid, date, date) to authenticated;


-- 3. Sales per day (22.2): one row a day, a day without a sale at zero. At most a year and a day of them.
create or replace function public.sales_by_day(p_merchant uuid, p_from date, p_to date)
returns table (day date, sales numeric, invoices bigint)
language sql
stable
security invoker
set search_path = ''
as $$
  select d.day::date, coalesce(sum(i.net_total), 0), count(i.id) filter (where not i.is_return)
  from generate_series(p_from::timestamp, least(p_to, p_from + 366)::timestamp, interval '1 day') as d (day)
  left join public.pos_invoices i
    on i.merchant_id = p_merchant and i.docstatus = 1 and i.posting_date = d.day::date
  group by d.day
  order by d.day;
$$;

revoke execute on function public.sales_by_day(uuid, date, date) from public, anon, authenticated, service_role;
grant execute on function public.sales_by_day(uuid, date, date) to authenticated;


-- 4. Top-Selling Items (22.2): by Item, or by the Item Group each item is in; ranked by the quantity sold in
-- stock units or by the net amount. What was sold and wholly returned drops out. `code` is an item's; a
-- group has none.
create or replace function public.top_selling(
  p_merchant uuid, p_from date, p_to date, p_by text default 'qty', p_group boolean default false, p_limit integer default 10
)
returns table (id uuid, code text, name text, qty numeric, amount numeric)
language sql
stable
security invoker
set search_path = ''
as $$
  select
    case when p_group then g.id else t.id end,
    case when p_group then null else t.item_code end,
    case when p_group then g.item_group_name else t.item_name end,
    sum(r.stock_qty),
    sum(r.net_amount)
  from public.pos_invoice_items r
  join public.pos_invoices i on i.id = r.pos_invoice_id
  join public.items t on t.id = r.item_id
  join public.item_groups g on g.id = t.item_group_id
  where i.merchant_id = p_merchant and i.docstatus = 1 and i.posting_date between p_from and p_to
  group by 1, 2, 3
  having sum(r.stock_qty) > 0 or sum(r.net_amount) > 0
  order by case when p_by = 'amount' then sum(r.net_amount) else sum(r.stock_qty) end desc, 3
  limit least(coalesce(p_limit, 10), 100);
$$;

revoke execute on function public.top_selling(uuid, date, date, text, boolean, integer) from public, anon, authenticated, service_role;
grant execute on function public.top_selling(uuid, date, date, text, boolean, integer) to authenticated;


-- ===== 20261012204315_import_items.sql =====

-- Step 23 of the POS build, on ERPNext's model: Bulk Import of Items
-- (.claude/erpnext-docs/POS-System-Added-Features.md 23.1; docs.frappe.io/erpnext/data-import, /opening-stock).
--
-- public.import_items(): the rows of one CSV file become items, their first prices and their opening stock in
-- one transaction — every row or none. The app reads the file and checks it first
-- (src/features/items/csv.ts); this is the write, and the database's own rules still decide it.
--
-- No table, so no doctype, seed or backfill. Security INVOKER, over the RPCs one item's form already uses:
-- public.save_item() for each row, so private.prepare_item(), private.validate_defaults(), the Item naming
-- series and the Standard Selling Rate's Item Price all run as they do for one item; then ONE Opening Stock
-- reconciliation for the whole file, saved and submitted as the importer. So it needs what the form needs:
-- Item create, Item Price create for a row with a rate, Stock Reconciliation create and submit for a row with
-- opening stock. Rejected: a definer function with its own permission checks — a second copy of what the
-- policies already say; a reconciliation per item (public.save_item_with_opening_stock in a loop) — 300 items
-- would leave 300 documents in the list.
--
-- Out of scope, so absent: updating existing items, any other document type, import of a file kept on the
-- server, a saved import log. Re-runnable, like the rest of supabase/migrations.


-- A row is the payload public.save_item() takes, plus opening_stock and valuation_rate; `id` and
-- `merchant_id` are set here whatever the row says, so the function only ever creates, in p_merchant. An
-- imported item's Default Warehouse is Stock Settings', as a new item's form starts with, and its Opening
-- Stock goes there. "Valuation Rate is mandatory if Opening Stock entered", falling back to the Standard
-- Selling Rate (public.save_item_with_opening_stock).
--
-- A refusal is re-raised as it was, with a hint saying where: 'row 3' — the third row of p_rows — or
-- 'opening stock' once the rows are in and the reconciliation is what failed. Answers the created codes and
-- names in the file's order (a code may be the naming series').
--
-- ponytail: 500 rows a call — the whole file is one statement under the authenticated role's 8 s
-- statement_timeout. A shop with more splits the file; a staged, resumable import if that stops being enough.
create or replace function public.import_items(p_merchant uuid, p_rows jsonb)
returns table (item_code text, item_name text)
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_count integer := case when jsonb_typeof(p_rows) = 'array' then jsonb_array_length(p_rows) else 0 end;
  v_warehouse uuid;
  v_row jsonb;
  v_n integer := 0;
  v_id uuid;
  v_ids uuid[] := '{}';
  v_opening numeric;
  v_rate numeric;
  v_stock jsonb := '[]'::jsonb;
  v_reconciliation uuid;
  v_state text;
  v_message text;
  v_detail text;
begin
  if v_count < 1 then
    raise exception 'no_rows' using errcode = '23514', detail = 'The file has no item rows.';
  elsif v_count > 500 then
    raise exception 'too_many_rows' using errcode = '23514', detail = 'A file holds at most 500 items.';
  end if;

  select s.default_warehouse into v_warehouse from public.stock_settings s where s.merchant_id = p_merchant;

  begin
    for v_row, v_n in select r.value, r.idx from jsonb_array_elements(p_rows) with ordinality as r (value, idx) loop
      v_id := public.save_item(v_row || jsonb_build_object(
        'id', '', 'merchant_id', p_merchant, 'default_warehouse', coalesce(v_warehouse::text, '')
      ));
      v_ids := v_ids || v_id;

      v_opening := nullif(v_row ->> 'opening_stock', '')::numeric;
      if coalesce(v_opening, 0) > 0 and coalesce((v_row ->> 'is_stock_item')::boolean, true) then
        v_rate := coalesce(nullif(v_row ->> 'valuation_rate', '')::numeric, nullif(v_row ->> 'standard_rate', '')::numeric);
        if coalesce(v_rate, 0) <= 0 then
          raise exception 'valuation_rate_required' using errcode = '23514', detail = 'Valuation Rate is mandatory if Opening Stock is entered.';
        end if;
        if v_warehouse is null then
          raise exception 'no_default_warehouse' using errcode = '23514', detail = 'Stock Settings names no warehouse for the opening stock.';
        end if;

        v_stock := v_stock || jsonb_build_object('item_id', v_id, 'warehouse_id', v_warehouse, 'qty', v_opening, 'valuation_rate', v_rate);
      end if;
    end loop;

    -- Past the rows: what fails from here is the reconciliation.
    v_n := 0;
    if jsonb_array_length(v_stock) > 0 then
      v_reconciliation := public.save_stock_reconciliation(jsonb_build_object(
        'merchant_id', p_merchant, 'purpose', 'Opening Stock', 'items', v_stock
      ));
      perform public.submit_document('Stock Reconciliation', v_reconciliation);
    end if;
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_message = message_text, v_detail = pg_exception_detail;
    raise exception using
      errcode = v_state, message = v_message, detail = v_detail,
      hint = case when v_n > 0 then 'row ' || v_n else 'opening stock' end;
  end;

  return query
  select i.item_code, i.item_name
  from unnest(v_ids) with ordinality as u (id, idx)
  join public.items i on i.id = u.id
  order by u.idx;
end;
$$;

revoke execute on function public.import_items(uuid, jsonb) from public, anon, authenticated, service_role;
grant execute on function public.import_items(uuid, jsonb) to authenticated;


-- ===== 20261013213537_access_codes.sql =====

-- Access Codes: the one way into someone else's system (.claude/updates-and-revamps/access-codes-references/
-- access-codes.txt). The owner makes codes and sends them outside the app; whoever uses one waits for the
-- owner to approve them.
--
-- 1. private.owned_merchant_ids(): the systems the caller owns, for the owner-only policies below.
-- 2. access_codes, access_requests and notifications. The first two are owner-only tenancy tables like
--    merchants, not doctypes: no role may make a code or let someone in (tenancy.md).
-- 3. merchant_members: the email invite is gone. A member row is made by decide_access_request alone.
-- 4. Notifications, written by triggers so no client can write one to someone else.
-- 5. The RPCs: create_access_codes, claim_access_code and decide_access_request.
--
-- Deletes the member rows no account claimed (none on the hosted project, 2026-10-14). Re-runnable, like
-- the rest of supabase/migrations.

create schema if not exists private;


-- 1. Security definer for the same reason as current_merchant_ids(): a policy calling it reads merchants
-- without going through merchants' own policy.
create or replace function private.owned_merchant_ids()
returns setof uuid
language sql
security definer
stable
set search_path = ''
as $$
  select m.id from public.merchants m where m.owner_id = (select auth.uid());
$$;

revoke execute on function private.owned_merchant_ids() from public, anon, authenticated, service_role;
grant execute on function private.owned_merchant_ids() to authenticated;


-- 2. The tables.

-- No insert or update policy: codes are made by create_access_codes only, so nobody picks a code — picking
-- one and reading the unique violation would tell whether it exists without the claim's rate limit. A code
-- is not edited: delete it and make another.
create table if not exists public.access_codes (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  -- Six of the 32 characters nobody misreads (no 0/O, 1/I). Shown as ABC-123.
  code text not null,
  -- The owner's note; blank shows the code.
  label text,
  -- Null: never expires.
  expires_at timestamptz,
  -- Null: any number of people. A use is a pending or approved request; a declined one frees its use.
  max_uses integer,
  created_at timestamptz not null default now(),

  constraint access_codes_code_unique unique (code),
  constraint access_codes_code_shape check (code ~ '^[2-9A-HJ-NP-Z]{6}$'),
  constraint access_codes_label_length check (label is null or length(label) between 1 and 40),
  constraint access_codes_max_uses check (max_uses is null or max_uses >= 1)
);

alter table public.access_codes enable row level security;
create index if not exists access_codes_merchant_id_idx on public.access_codes (merchant_id, created_at desc);

drop policy if exists access_codes_select on public.access_codes;
create policy access_codes_select on public.access_codes
  for select to authenticated
  using (merchant_id in (select private.owned_merchant_ids()));

drop policy if exists access_codes_delete on public.access_codes;
create policy access_codes_delete on public.access_codes
  for delete to authenticated
  using (merchant_id in (select private.owned_merchant_ids()));

-- A code used by someone. Copies, taken when the code is used: the requester cannot read the system, the
-- code may be deleted, and the owner sees the person as they were when they asked.
create table if not exists public.access_requests (
  id uuid primary key default gen_random_uuid(),
  merchant_id uuid not null references public.merchants (id) on delete cascade,
  merchant_name text not null,
  access_code_id uuid references public.access_codes (id) on delete set null,
  code text not null,
  user_id uuid not null references auth.users (id) on delete cascade,
  full_name text,
  email text,
  avatar_url text,
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  decided_at timestamptz,

  constraint access_requests_status check (status in ('pending', 'approved', 'declined'))
);

alter table public.access_requests enable row level security;
-- One open request per person and system.
create unique index if not exists access_requests_one_pending on public.access_requests (merchant_id, user_id) where status = 'pending';
create index if not exists access_requests_merchant_id_idx on public.access_requests (merchant_id, created_at desc);
create index if not exists access_requests_user_id_idx on public.access_requests (user_id);
create index if not exists access_requests_access_code_id_idx on public.access_requests (access_code_id);

-- Select only: the owner sees the requests to their systems, the requester their own. The definer RPCs
-- below are the only writers.
drop policy if exists access_requests_select on public.access_requests;
create policy access_requests_select on public.access_requests
  for select to authenticated
  using (merchant_id in (select private.owned_merchant_ids()) or user_id = (select auth.uid()));

-- One person's inbox. They read, mark read and clear their own; only the triggers below write one.
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  merchant_id uuid references public.merchants (id) on delete cascade,
  kind text not null,
  title text not null,
  body text,
  request_id uuid references public.access_requests (id) on delete set null,
  read_at timestamptz,
  created_at timestamptz not null default now(),

  constraint notifications_kind check (kind in ('access_requested', 'access_approved', 'access_declined', 'access_removed', 'access_changed'))
);

alter table public.notifications enable row level security;
create index if not exists notifications_user_id_idx on public.notifications (user_id, created_at desc);
create index if not exists notifications_merchant_id_idx on public.notifications (merchant_id);
create index if not exists notifications_request_id_idx on public.notifications (request_id);

drop policy if exists notifications_select on public.notifications;
create policy notifications_select on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists notifications_update on public.notifications;
create policy notifications_update on public.notifications
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists notifications_delete on public.notifications;
create policy notifications_delete on public.notifications
  for delete to authenticated
  using (user_id = (select auth.uid()));

-- The claim's rate limit: a wrong, expired or used-up code is a failure, and ten in 15 minutes stop the
-- caller. In private, out of PostgREST's reach; RLS on with no policy all the same.
create table if not exists private.access_code_failures (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  failed_at timestamptz not null default now()
);

alter table private.access_code_failures enable row level security;
create index if not exists access_code_failures_user_id_idx on private.access_code_failures (user_id, failed_at);


-- 3. Members. The invite by email and its two claim triggers go: a code is the only way in.

drop trigger if exists on_auth_user_claim_memberships on auth.users;
drop function if exists private.claim_memberships_for_user();
drop trigger if exists merchant_members_claim on public.merchant_members;
drop function if exists private.claim_membership();

delete from public.merchant_members where user_id is null;
alter table public.merchant_members alter column user_id set not null;

-- Was set null, which left a row nobody could use behind a deleted account.
alter table public.merchant_members drop constraint if exists merchant_members_user_id_fkey;
alter table public.merchant_members add constraint merchant_members_user_id_fkey
  foreign key (user_id) references auth.users (id) on delete cascade;

alter table public.merchant_members drop constraint if exists merchant_members_user_unique;
alter table public.merchant_members add constraint merchant_members_user_unique unique (merchant_id, user_id);

-- The email, name and photo are copies from the request now, for the owner to recognise the person — not
-- a key, and not typed by anyone, so neither the email's uniqueness nor its shape is checked any more. A
-- Facebook account may have no email.
alter table public.merchant_members alter column email drop not null;
alter table public.merchant_members drop constraint if exists merchant_members_email_unique;
alter table public.merchant_members drop constraint if exists merchant_members_email_shape;
alter table public.merchant_members add column if not exists avatar_url text;
-- The code they joined with: the Members tab's "via".
alter table public.merchant_members add column if not exists access_code text;

-- Only decide_access_request makes a member (it runs as the table's owner, not as `authenticated`), and
-- nobody moves a member row to another person or system — that would let someone in without a code.
create or replace function private.require_access_request()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and current_user in ('authenticated', 'anon') then
    raise exception 'access_code_required' using errcode = '42501',
      detail = 'People join a system by using one of its access codes.';
  end if;

  if tg_op = 'UPDATE' and (new.user_id is distinct from old.user_id or new.merchant_id is distinct from old.merchant_id) then
    raise exception 'member_locked' using errcode = '42501';
  end if;

  return new;
end;
$$;

revoke execute on function private.require_access_request() from public, anon, authenticated, service_role;

drop trigger if exists merchant_members_require_access_request on public.merchant_members;
create trigger merchant_members_require_access_request
  before insert or update of user_id, merchant_id on public.merchant_members
  for each row execute function private.require_access_request();


-- 4. Notifications.

create or replace function private.notify_access_request()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text := format('%s-%s', left(new.code, 3), right(new.code, 3));
begin
  if tg_op = 'INSERT' then
    insert into public.notifications (user_id, merchant_id, kind, title, body, request_id)
    select m.owner_id, new.merchant_id, 'access_requested', 'Access code used',
      format('%s used %s to ask for access to %s.', coalesce(new.full_name, new.email, 'Someone'), v_code, new.merchant_name),
      new.id
    from public.merchants m where m.id = new.merchant_id;
  elsif new.status = 'approved' then
    insert into public.notifications (user_id, merchant_id, kind, title, body, request_id)
    values (new.user_id, new.merchant_id, 'access_approved', 'Request approved',
      format('You can open %s from Home now.', new.merchant_name), new.id);
  elsif new.status = 'declined' then
    insert into public.notifications (user_id, merchant_id, kind, title, body, request_id)
    values (new.user_id, new.merchant_id, 'access_declined', 'Request declined',
      format('The owner of %s declined your request.', new.merchant_name), new.id);
  end if;

  return null;
end;
$$;

revoke execute on function private.notify_access_request() from public, anon, authenticated, service_role;

drop trigger if exists access_requests_notify_insert on public.access_requests;
create trigger access_requests_notify_insert
  after insert on public.access_requests
  for each row execute function private.notify_access_request();

drop trigger if exists access_requests_notify_decided on public.access_requests;
create trigger access_requests_notify_decided
  after update of status on public.access_requests
  for each row when (old.status is distinct from new.status)
  execute function private.notify_access_request();

create or replace function private.notify_member_removed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text;
begin
  select m.name into v_name from public.merchants m where m.id = old.merchant_id;

  -- Removing the system, or deleting either account, takes the member row with it: then there is no system
  -- to name or nobody to tell, and the insert would fail the foreign keys.
  if v_name is null or not exists (select 1 from auth.users u where u.id = old.user_id) then
    return null;
  end if;

  insert into public.notifications (user_id, merchant_id, kind, title, body)
  values (old.user_id, old.merchant_id, 'access_removed', 'Access removed',
    format('The owner of %s removed your access.', v_name));
  return null;
end;
$$;

revoke execute on function private.notify_member_removed() from public, anon, authenticated, service_role;

drop trigger if exists merchant_members_notify_removed on public.merchant_members;
create trigger merchant_members_notify_removed
  after delete on public.merchant_members
  for each row execute function private.notify_member_removed();


-- 5. The RPCs. Security definer, each in `public` because the app calls it, so each revokes and grants by
-- name and checks (select auth.uid()) itself (CLAUDE.md §6.2).

-- Make 1–20 codes for a system the caller owns. Expiry is decided here, not on the phone: minutes from now,
-- or the end of a day where the system is (System Settings' time zone). Neither: never expires. No
-- p_max_uses: any number of people — so the app leaves out what it means as none.
create or replace function public.create_access_codes(
  p_merchant uuid,
  p_label text default null,
  p_quantity integer default 1,
  p_expires_minutes integer default null,
  p_expires_on date default null,
  p_max_uses integer default null
)
returns setof public.access_codes
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_expires timestamptz;
  v_code text;
  v_row public.access_codes;
begin
  if not exists (select 1 from public.merchants m where m.id = p_merchant and m.owner_id = (select auth.uid())) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  if p_quantity is null or p_quantity not between 1 and 20 then
    raise exception 'invalid_quantity' using errcode = '22023', detail = 'Make 1 to 20 codes at a time.';
  end if;

  if p_expires_minutes is not null then
    if p_expires_minutes < 1 then
      raise exception 'invalid_expiry' using errcode = '22023';
    end if;
    v_expires := now() + make_interval(mins => p_expires_minutes);
  elsif p_expires_on is not null then
    if p_expires_on < private.merchant_today(p_merchant) then
      raise exception 'expiry_in_past' using errcode = '22023', detail = 'Pick today or a later day.';
    end if;
    v_expires := (p_expires_on + 1)::timestamp at time zone coalesce(
      (select s.time_zone from public.system_settings s where s.merchant_id = p_merchant), 'UTC'
    );
  end if;

  for i in 1 .. p_quantity loop
    loop
      -- 256 is a multiple of 32, so every character is equally likely.
      select string_agg(substr('23456789ABCDEFGHJKLMNPQRSTUVWXYZ', get_byte(b.bytes, n) % 32 + 1, 1), '' order by n)
      into v_code
      from (select extensions.gen_random_bytes(6) as bytes) b, generate_series(0, 5) as n;

      insert into public.access_codes (merchant_id, code, label, expires_at, max_uses)
      values (p_merchant, v_code, nullif(btrim(p_label), ''), v_expires, p_max_uses)
      on conflict (code) do nothing
      returning * into v_row;

      -- Taken already (one in a billion per code): draw again.
      exit when v_row.id is not null;
    end loop;

    return next v_row;
  end loop;
end;
$$;

revoke execute on function public.create_access_codes(uuid, text, integer, integer, date, integer) from public, anon, authenticated, service_role;
grant execute on function public.create_access_codes(uuid, text, integer, integer, date, integer) to authenticated;

-- Use a code: a request the owner approves or declines. Answers with a status instead of raising, so a
-- failure's rate-limit row is kept: requested | invalid | expired | used_up | own_system | already_member |
-- already_requested | declined | too_many_attempts. The system's name only once the code is real and not
-- spent, so guessing names nothing.
create or replace function public.claim_access_code(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  c public.access_codes;
  v_name text;
  v_owner uuid;
  v_status text;
begin
  if v_uid is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  delete from private.access_code_failures f where f.user_id = v_uid and f.failed_at < now() - interval '15 minutes';
  if (select count(*) from private.access_code_failures f where f.user_id = v_uid) >= 10 then
    return jsonb_build_object('status', 'too_many_attempts');
  end if;

  -- Locked: two people using a one-person code at once are served one after the other.
  select * into c from public.access_codes ac
  where ac.code = upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'))
  for update;

  if c.id is null or c.expires_at <= now() then
    insert into private.access_code_failures (user_id) values (v_uid);
    return jsonb_build_object('status', case when c.id is null then 'invalid' else 'expired' end);
  end if;

  select m.name, m.owner_id into v_name, v_owner from public.merchants m where m.id = c.merchant_id;

  v_status := case
    when v_owner = v_uid then 'own_system'
    when exists (select 1 from public.merchant_members mm where mm.merchant_id = c.merchant_id and mm.user_id = v_uid) then 'already_member'
    when exists (select 1 from public.access_requests r where r.merchant_id = c.merchant_id and r.user_id = v_uid and r.status = 'pending') then 'already_requested'
    -- A decline frees the code's use for someone else, not for the person declined.
    when exists (select 1 from public.access_requests r where r.access_code_id = c.id and r.user_id = v_uid and r.status = 'declined') then 'declined'
  end;
  if v_status is not null then
    return jsonb_build_object('status', v_status, 'merchant_name', v_name);
  end if;

  if c.max_uses is not null and (
    select count(*) from public.access_requests r where r.access_code_id = c.id and r.status in ('pending', 'approved')
  ) >= c.max_uses then
    insert into private.access_code_failures (user_id) values (v_uid);
    return jsonb_build_object('status', 'used_up');
  end if;

  insert into public.access_requests (merchant_id, merchant_name, access_code_id, code, user_id, full_name, email, avatar_url)
  select c.merchant_id, v_name, c.id, c.code, v_uid, p.display_name, u.email, p.avatar_url
  from auth.users u
  left join public.profiles p on p.id = u.id
  where u.id = v_uid;

  return jsonb_build_object('status', 'requested', 'merchant_name', v_name);
end;
$$;

revoke execute on function public.claim_access_code(text) from public, anon, authenticated, service_role;
grant execute on function public.claim_access_code(text) to authenticated;

-- Approve or decline a pending request to a system the caller owns. Approving makes the member, with no
-- role. Already a member (approved through another code meanwhile): only the request changes.
create or replace function public.decide_access_request(p_request uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r public.access_requests;
begin
  select * into r from public.access_requests ar
  where ar.id = p_request
    and ar.merchant_id in (select m.id from public.merchants m where m.owner_id = (select auth.uid()))
  for update;

  if r.id is null then
    raise exception 'request_not_found' using errcode = 'P0002';
  end if;
  if r.status <> 'pending' then
    raise exception 'request_decided' using errcode = '23514', detail = 'This request was already approved or declined.';
  end if;

  update public.access_requests
  set status = case when p_approve then 'approved' when not p_approve then 'declined' end, decided_at = now()
  where id = r.id;

  if p_approve then
    insert into public.merchant_members (merchant_id, user_id, email, full_name, avatar_url, access_code)
    values (r.merchant_id, r.user_id, r.email, left(r.full_name, 120), r.avatar_url, r.code)
    on conflict (merchant_id, user_id) do nothing;
  end if;
end;
$$;

revoke execute on function public.decide_access_request(uuid, boolean) from public, anon, authenticated, service_role;
grant execute on function public.decide_access_request(uuid, boolean) to authenticated;


-- ===== 20261014034106_employees_and_permissions.sql =====

-- Employees & permissions: Discord-style roles replace ERPNext's
-- (.claude/updates-and-revamps/roles-perms-references/revamp-roles-perms.txt).
--
-- A system's owner makes roles, turns permissions on for each, gives every employee one role, and may turn a
-- permission on or off for one employee — that employee's own setting wins over their role's. An employee
-- with no role sees Home only.
--
-- 1. The catalog, global and read-only: public.permissions (what an owner turns on) and
--    public.permission_rules (what each one lets a person do: a doctype and a permission type).
-- 2. Per system, owner-only: public.role_grants (a role's permissions) and public.member_overrides (one
--    employee's exceptions).
-- 3. roles lose ERPNext's standard roles; merchant_members gets role_id and loses role profiles and Enabled.
-- 4. The seam keeps its signature: private.permitted_merchant_ids(doctype, ptype) now expands the caller's
--    effective permissions through the rules, so every policy, poster and RPC that asks it keeps working.
--    public.my_permissions keeps its shape and adds `permissions`, the keys themselves.
-- 5. The sale's poster checks Process Sales, Process Refunds and Apply Discounts.
-- 6. The policies, re-applied without User Permissions; then the old model is dropped: role permissions, the
--    standard matrix, role profiles, member roles, User Permissions and doctype links.
-- 7. public.save_role and public.save_member_access, and an "Access changed" notification for whoever a
--    change reaches.
-- 8. Every system starts with Cashier, Stock Clerk and Store Manager.
--
-- DROPS, with their rows: role assignments (member_roles), role profiles, the Role Permissions Manager's
-- rules, User Permissions and the ERPNext roles. On the hosted project before this ran (2026-10-14): 0 members,
-- 0 role assignments, 0 role profiles, 0 User Permissions, 0 custom roles, every system's matrix the standard
-- one. Re-runnable, like the rest of supabase/migrations.
--
-- Known limits (ponytail): a `select` rule is a lookup the screens need (a price, a tax, a register), and RLS
-- cannot tell a lookup from a list — so Process Sales can read every sale through the API, though no screen
-- lists them without View Sales. Apply Discounts is checked against each line's Price List Rate, which the app
-- sends (the poster's "app calculates, database checks" ceiling); a second price engine in SQL is the upgrade.

create schema if not exists private;


-- 1. The catalog. Read by every signed-in person (the editors list it); written by migrations only.

create table if not exists public.permissions (
  key text primary key,
  category text not null,
  label text not null,
  description text not null,
  position integer not null,
  -- The permission this one needs: the editors turn both on together and save_* refuse one without it.
  requires text references public.permissions (key)
);

alter table public.permissions enable row level security;
create index if not exists permissions_requires_idx on public.permissions (requires);

drop policy if exists permissions_select on public.permissions;
create policy permissions_select on public.permissions
  for select to authenticated
  using (true);

-- `select` is a lookup — a field's options, a price, a register's setup — and passes RLS; `read` is what a
-- person may open, as a list or a page. The rest are ERPNext's.
create table if not exists public.permission_rules (
  permission text not null references public.permissions (key) on delete cascade,
  doctype text not null references public.doctypes (name) on delete cascade,
  ptype text not null,

  primary key (permission, doctype, ptype),
  constraint permission_rules_ptype check (ptype in ('select', 'read', 'write', 'create', 'delete', 'submit', 'cancel'))
);

alter table public.permission_rules enable row level security;
create index if not exists permission_rules_doctype_idx on public.permission_rules (doctype, ptype);

drop policy if exists permission_rules_select on public.permission_rules;
create policy permission_rules_select on public.permission_rules
  for select to authenticated
  using (true);

