-- 7. The owner's two saves. Security invoker: RLS decides, and only the owner passes role_grants',
-- member_overrides' and a role's or member's write policies.

-- A role, its permissions and — when `member_ids` is given — who holds it: those employees move to it, and
-- whoever held it and is not listed is left with no role.
create or replace function public.save_role(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_keys text[] := array(select jsonb_array_elements_text(coalesce(payload -> 'permissions', '[]'::jsonb)));
  v_members uuid[] := array(select jsonb_array_elements_text(coalesce(payload -> 'member_ids', '[]'::jsonb)))::uuid[];
  v_missing text;
begin
  select p.label into v_missing
  from public.permissions p
  where p.key = any (v_keys) and p.requires is not null and not (p.requires = any (v_keys))
  limit 1;
  if v_missing is not null then
    raise exception 'permission_requires' using errcode = '23514', detail = v_missing;
  end if;

  if v_id is null then
    insert into public.roles (merchant_id, role_name, description, color)
    values (v_merchant, btrim(payload ->> 'role_name'), nullif(btrim(payload ->> 'description'), ''), coalesce(payload ->> 'color', 'grey'))
    returning id into v_id;
  else
    update public.roles set
      role_name = btrim(payload ->> 'role_name'),
      description = nullif(btrim(payload ->> 'description'), ''),
      color = coalesce(payload ->> 'color', 'grey')
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    -- RLS filters an UPDATE rather than refusing it.
    if v_id is null then
      raise exception 'role_not_found' using errcode = 'P0002';
    end if;
  end if;

  delete from public.role_grants g where g.role_id = v_id and not (g.permission = any (v_keys));
  insert into public.role_grants (merchant_id, role_id, permission)
  select v_merchant, v_id, k.key from unnest(v_keys) as k (key)
  on conflict (role_id, permission) do nothing;

  if payload ? 'member_ids' then
    update public.merchant_members mm set role_id = null
    where mm.role_id = v_id and not (mm.id = any (v_members));
    update public.merchant_members mm set role_id = v_id
    where mm.merchant_id = v_merchant and mm.id = any (v_members) and mm.role_id is distinct from v_id;
  end if;

  return v_id;
end;
$$;

revoke execute on function public.save_role(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_role(jsonb) to authenticated;

-- One employee's role and their exceptions to it, replaced as a set: p_overrides is [{permission, allowed}],
-- only where the employee differs from the role. No p_role: no role — the generated RPC types forbid null, so
-- the app leaves out an argument it means as none.
create or replace function public.save_member_access(p_member uuid, p_role uuid default null, p_overrides jsonb default '[]'::jsonb)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_merchant uuid;
  v_missing text;
begin
  update public.merchant_members set role_id = p_role where id = p_member
  returning merchant_id into v_merchant;

  -- RLS filters an UPDATE rather than refusing it.
  if v_merchant is null then
    raise exception 'member_not_found' using errcode = 'P0002';
  end if;

  delete from public.member_overrides o
  where o.member_id = p_member
    and not exists (
      select 1 from jsonb_array_elements(coalesce(p_overrides, '[]'::jsonb)) as x (value)
      where x.value ->> 'permission' = o.permission
    );

  insert into public.member_overrides (merchant_id, member_id, permission, allowed)
  select v_merchant, p_member, x.value ->> 'permission', (x.value ->> 'allowed')::boolean
  from jsonb_array_elements(coalesce(p_overrides, '[]'::jsonb)) as x (value)
  on conflict (member_id, permission) do update set allowed = excluded.allowed
  where public.member_overrides.allowed is distinct from excluded.allowed;

  -- What the employee holds now: a permission comes with the one it requires.
  with effective as (
    select g.permission from public.role_grants g
    where g.role_id = p_role
      and not exists (
        select 1 from public.member_overrides o where o.member_id = p_member and o.permission = g.permission and not o.allowed
      )
    union
    select o.permission from public.member_overrides o where o.member_id = p_member and o.allowed
  )
  select p.label into v_missing
  from effective e
  join public.permissions p on p.key = e.permission
  where p.requires is not null and p.requires not in (select f.permission from effective f)
  limit 1;

  if v_missing is not null then
    raise exception 'permission_requires' using errcode = '23514', detail = v_missing;
  end if;
end;
$$;

revoke execute on function public.save_member_access(uuid, uuid, jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_member_access(uuid, uuid, jsonb) to authenticated;

-- "Access changed", once per employee until they read it: a role's permissions changed (role_grants), their
-- role (merchant_members.role_id) or their own exceptions (member_overrides). Skipped when the system, the
-- employee or their account is going — removing any of them takes these rows with it.
create or replace function private.notify_access_changed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  insert into public.notifications (user_id, merchant_id, kind, title, body)
  select mm.user_id, mm.merchant_id, 'access_changed', 'Access changed',
    format('The owner of %s changed what you can do there.', m.name)
  from public.merchant_members mm
  join public.merchants m on m.id = mm.merchant_id
  where case tg_table_name
      when 'role_grants' then mm.role_id = (v_row ->> 'role_id')::uuid
      when 'member_overrides' then mm.id = (v_row ->> 'member_id')::uuid
      else mm.id = (v_row ->> 'id')::uuid
    end
    and exists (select 1 from auth.users u where u.id = mm.user_id)
    and not exists (
      select 1 from public.notifications n
      where n.user_id = mm.user_id and n.merchant_id = mm.merchant_id and n.kind = 'access_changed' and n.read_at is null
    );
  return null;
end;
$$;

revoke execute on function private.notify_access_changed() from public, anon, authenticated, service_role;

drop trigger if exists role_grants_notify on public.role_grants;
create trigger role_grants_notify
  after insert or delete on public.role_grants
  for each row execute function private.notify_access_changed();

drop trigger if exists member_overrides_notify on public.member_overrides;
create trigger member_overrides_notify
  after insert or update or delete on public.member_overrides
  for each row execute function private.notify_access_changed();

drop trigger if exists merchant_members_notify_role on public.merchant_members;
create trigger merchant_members_notify_role
  after update of role_id on public.merchant_members
  for each row when (old.role_id is distinct from new.role_id)
  execute function private.notify_access_changed();


-- 8. Every system's starter roles, with their permissions — only for a role this run made, so a role the
-- owner has edited keeps their changes.
create or replace function private.seed_roles(p_merchant uuid)
returns void
language sql
set search_path = ''
as $$
  with made as (
    insert into public.roles (merchant_id, role_name, description, color)
    values
      (p_merchant, 'Cashier', 'Rings up sales and opens and closes their register.', 'green'),
      (p_merchant, 'Stock Clerk', 'Sees stock levels and receives shipments.', 'orange'),
      (p_merchant, 'Store Manager', 'Every permission in the system.', 'maroon')
    on conflict (merchant_id, role_name) do nothing
    returning id, role_name
  )
  insert into public.role_grants (merchant_id, role_id, permission)
  select p_merchant, r.id, p.key
  from made r
  join public.permissions p on case r.role_name
    when 'Cashier' then p.key in ('process_sales', 'open_close_register')
    when 'Stock Clerk' then p.key in ('view_stock', 'move_stock')
    else true
  end;
$$;

revoke execute on function private.seed_roles(uuid) from public, anon, authenticated, service_role;

create or replace function private.seed_access()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is not null and new.owner_id <> (select auth.uid()) then
    raise exception 'not_the_owner' using errcode = '42501';
  end if;

  perform private.seed_roles(new.id);
  return new;
end;
$$;

-- The systems that already exist.
select private.seed_roles(m.id) from public.merchants m;


-- ===== 20261014170428_backend_performance.sql =====

-- Backend performance before deployment (supabase/database-improvements.txt, checked against the live
-- functions, the app's queries and get_advisors on 2026-10-15). Nothing a person sees changes.
--
-- 1. public.bins and public.naming_series_counters keep free space on each page (fillfactor 70) and are
--    vacuumed sooner. Every sale rewrites its items' bins and its series counter, and neither update touches an
--    indexed column, so with room on the page Postgres updates them in place (HOT) instead of leaving a dead row
--    and a new index entry behind.
-- 2. Three partial indexes, each shaped like the query it serves: a system's open sessions (the Dashboard's Open
--    Registers), its submitted sales by date with the figures the Dashboard adds up (an index-only scan for
--    dashboard_cards, sales_by_day and top_selling), and a person's unread notifications (polled every minute).
-- 3. public.dashboard_cards() counts Low Stock itself instead of through public.stock_alerts() — that call
--    sorted every alert only to count them — and reads a session's Cash payments once instead of twice. Same
--    rows, same answer: the warehouses join stays, so what the caller's policies let them see is unchanged.
-- 4. The save_* RPCs clear a record's child rows only when the record was already saved; a record just
--    inserted has none. public.import_items saves through public.save_item, so a 500-row file skips 1,000
--    deletes.
--
-- Rejected, with the human on 2026-10-15 (ARCHITECTURE.md, Backend performance):
-- - numbering a document at the end of its submit — post_gl and post_sle write the name as voucher_no, a
--   document keeps its name (private.guard_docstatus), and a draft shows its number from its first save;
-- - CACHE 100 on the two ledger sequences — the ledger reports order a day's rows by id, and cached blocks
--   hand ids out of order across connections; nextval already logs only one value in 32;
-- - dropping bins_item_idx — no bin update touches it, and it covers bins_item_fk;
-- - statement-level child guards — private.guard_docstatus_child is the drafts-only boundary and costs one
--   primary-key lookup a row;
-- - a key swap on pos_invoice_items, an item-name or trigram index (the Register searches on the device),
--   wider ledger voucher indexes (voucher_id is a uuid), and a pg_cron clean-up of things a person still sees.
--
-- Re-runnable, like the rest of supabase/migrations.


-- 1. Room for in-place updates on the two rows every sale rewrites.
alter table public.bins set (
  fillfactor = 70,
  autovacuum_vacuum_scale_factor = 0.01,
  autovacuum_analyze_scale_factor = 0.005
);

alter table public.naming_series_counters set (
  fillfactor = 70,
  autovacuum_vacuum_scale_factor = 0.01
);


-- 2. Indexes for the Dashboard and the notifications' poll.
create index if not exists pos_opening_entries_open_merchant_idx
  on public.pos_opening_entries (merchant_id)
  where docstatus = 1 and status = 'Open';

-- id is included: dashboard_cards, sales_by_day and top_selling each read it, so none needs the table.
create index if not exists pos_invoices_submitted_date_idx
  on public.pos_invoices (merchant_id, posting_date desc)
  include (id, net_total, is_return)
  where docstatus = 1;

create index if not exists notifications_unread_idx
  on public.notifications (user_id, created_at desc)
  where read_at is null;


-- 3. The number cards (22.1), as 20261012200010_dashboard.sql made them, read more cheaply.
-- ponytail: change comes off the expected cash only for a sale with a Cash-type payment — the closing entry's
-- fallback to a sale's first payment (private.submit_pos_closing_entries) is not repeated here; a change mode
-- column on the invoice would serve both.
create or replace function public.dashboard_cards(p_merchant uuid, p_from date, p_to date)
returns table (
  sales numeric, invoices bigint, gross_profit numeric, open_registers bigint, expected_cash numeric, low_stock bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  with sold as (
    select i.id, i.net_total, i.is_return
    from public.pos_invoices i
    where i.merchant_id = p_merchant and i.docstatus = 1 and i.posting_date between p_from and p_to
  ),
  open_sessions as (
    select s.id
    from public.pos_opening_entries s
    where s.merchant_id = p_merchant and s.docstatus = 1 and s.status = 'Open'
  ),
  session_sales as (
    select i.id, i.change_amount
    from public.pos_invoices i
    where i.pos_opening_entry_id in (select o.id from open_sessions o) and i.docstatus = 1
  ),
  -- Each open-session sale that took cash, and how much: read once, used twice below.
  session_cash as (
    select p.pos_invoice_id, sum(p.amount) as cash
    from public.pos_invoice_payments p
    join public.modes_of_payment m on m.id = p.mode_of_payment_id
    where p.pos_invoice_id in (select x.id from session_sales x) and m.type = 'Cash'
    group by p.pos_invoice_id
  )
  select
    coalesce((select sum(s.net_total) from sold s), 0),
    (select count(*) from sold s where not s.is_return),
    case
      when p_merchant in (select private.permitted_merchant_ids('Stock Ledger Entry', 'read')) then
        coalesce((
          select sum(r.net_amount - coalesce(r.valuation_rate, 0) * r.stock_qty)
          from public.pos_invoice_items r
          where r.pos_invoice_id in (select s.id from sold s)
        ), 0)
    end,
    (select count(*) from open_sessions),
    coalesce((
      select sum(b.opening_amount)
      from public.pos_opening_entry_balances b
      join public.modes_of_payment m on m.id = b.mode_of_payment_id
      where b.pos_opening_entry_id in (select o.id from open_sessions o) and m.type = 'Cash'
    ), 0)
    + coalesce((select sum(c.cash) from session_cash c), 0)
    - coalesce((
      select sum(x.change_amount)
      from session_sales x
      join session_cash c on c.pos_invoice_id = x.id
      where x.change_amount > 0
    ), 0),
    -- public.stock_alerts()'s rule, counted: no sort, no row built for an alert nobody lists.
    (
      select count(distinct b.item_id)
      from public.bins b
      join public.items t on t.id = b.item_id
      join public.warehouses w on w.id = b.warehouse_id
      where b.merchant_id = p_merchant
        and t.is_stock_item
        and not t.disabled
        and (b.actual_qty <= 0 or (coalesce(t.reorder_level, 0) > 0 and b.actual_qty <= t.reorder_level))
    );
$$;

revoke execute on function public.dashboard_cards(uuid, date, date) from public, anon, authenticated, service_role;
grant execute on function public.dashboard_cards(uuid, date, date) to authenticated;


-- 4. The save RPCs, as they stand, with each child table cleared only on an update.
create or replace function public.save_item(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_id uuid := nullif(payload ->> 'id', '')::uuid;
  v_merchant uuid := (payload ->> 'merchant_id')::uuid;
  v_rate numeric := nullif(payload ->> 'standard_rate', '')::numeric;
  v_list uuid;
begin
  if v_id is null then
    insert into public.items (
      merchant_id, item_code, item_name, item_group_id, stock_uom, description, brand_id, disabled, is_stock_item,
      valuation_method, allow_negative_stock, reorder_level, sales_uom,
      default_warehouse, default_price_list, selling_cost_center, income_account, expense_account,
      max_discount, discount_account
    )
    values (
      v_merchant,
      payload ->> 'item_code',
      payload ->> 'item_name',
      (payload ->> 'item_group_id')::uuid,
      (payload ->> 'stock_uom')::uuid,
      nullif(btrim(payload ->> 'description'), ''),
      nullif(payload ->> 'brand_id', '')::uuid,
      coalesce((payload ->> 'disabled')::boolean, false),
      coalesce((payload ->> 'is_stock_item')::boolean, true),
      nullif(payload ->> 'valuation_method', ''),
      coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      nullif(payload ->> 'reorder_level', '')::numeric,
      nullif(payload ->> 'sales_uom', '')::uuid,
      nullif(payload ->> 'default_warehouse', '')::uuid,
      nullif(payload ->> 'default_price_list', '')::uuid,
      nullif(payload ->> 'selling_cost_center', '')::uuid,
      nullif(payload ->> 'income_account', '')::uuid,
      nullif(payload ->> 'expense_account', '')::uuid,
      coalesce(nullif(payload ->> 'max_discount', '')::numeric, 0),
      nullif(payload ->> 'discount_account', '')::uuid
    )
    returning id into v_id;

    if coalesce(v_rate, 0) > 0 then
      select s.default_price_list into v_list from public.selling_settings s where s.merchant_id = v_merchant;
      if v_list is null then
        raise exception 'no_default_price_list' using errcode = '23514',
          detail = 'Selling Settings names no default price list for the Standard Selling Rate.';
      end if;

      insert into public.item_prices (merchant_id, item_id, price_list_id, uom_id, price_list_rate)
      values (v_merchant, v_id, v_list, (payload ->> 'stock_uom')::uuid, v_rate);
    end if;
  else
    update public.items set
      item_name = payload ->> 'item_name',
      item_group_id = (payload ->> 'item_group_id')::uuid,
      stock_uom = (payload ->> 'stock_uom')::uuid,
      description = nullif(btrim(payload ->> 'description'), ''),
      brand_id = nullif(payload ->> 'brand_id', '')::uuid,
      disabled = coalesce((payload ->> 'disabled')::boolean, false),
      is_stock_item = coalesce((payload ->> 'is_stock_item')::boolean, true),
      valuation_method = nullif(payload ->> 'valuation_method', ''),
      allow_negative_stock = coalesce((payload ->> 'allow_negative_stock')::boolean, false),
      reorder_level = nullif(payload ->> 'reorder_level', '')::numeric,
      sales_uom = nullif(payload ->> 'sales_uom', '')::uuid,
      default_warehouse = nullif(payload ->> 'default_warehouse', '')::uuid,
      default_price_list = nullif(payload ->> 'default_price_list', '')::uuid,
      selling_cost_center = nullif(payload ->> 'selling_cost_center', '')::uuid,
      income_account = nullif(payload ->> 'income_account', '')::uuid,
      expense_account = nullif(payload ->> 'expense_account', '')::uuid,
      max_discount = coalesce(nullif(payload ->> 'max_discount', '')::numeric, 0),
      discount_account = nullif(payload ->> 'discount_account', '')::uuid
    where id = v_id and merchant_id = v_merchant
    returning id into v_id;

    if v_id is null then
      raise exception 'item_not_found' using errcode = 'P0002';
    end if;

    -- A saved item's rows are replaced; a new one has none to clear.
    delete from public.item_uoms where item_id = v_id;
    delete from public.item_taxes where item_id = v_id;
  end if;

  insert into public.item_uoms (merchant_id, item_id, idx, uom_id, conversion_factor)
  select v_merchant, v_id, r.idx::integer, (r.value ->> 'uom_id')::uuid, (r.value ->> 'conversion_factor')::numeric
  from jsonb_array_elements(coalesce(payload -> 'uoms', '[]'::jsonb)) with ordinality as r (value, idx);

  insert into public.item_taxes (merchant_id, item_id, idx, item_tax_template_id, tax_category_id, valid_from)
  select
    v_merchant, v_id, r.idx::integer,
    (r.value ->> 'item_tax_template_id')::uuid,
    nullif(r.value ->> 'tax_category_id', '')::uuid,
    nullif(r.value ->> 'valid_from', '')::date
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

revoke execute on function public.save_item(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.save_item(jsonb) to authenticated;

create or replace function public.save_item_group(payload jsonb)
returns uuid
language plpgsql
security invoker
set search_path = ''
as $$
declare
