    coalesce(nullif(r.value ->> 'minimum_net_rate', '')::numeric, 0),
    coalesce(nullif(r.value ->> 'maximum_net_rate', '')::numeric, 0)
  from jsonb_array_elements(coalesce(payload -> 'taxes', '[]'::jsonb)) with ordinality as r (value, idx);

  return v_id;
end;
$$;

