begin
  if v_id is null then
    insert into public.item_groups (
      merchant_id, item_group_name, parent_id, is_group,
      default_price_list, default_warehouse, income_account, expense_account
    )
    values (
      v_merchant,
      btrim(payload ->> 'item_group_name'),
